head.script:
scwin.onpageload = function () {
    console.log("projectMainPage 페이지 로드 시작");

    // 사용자 인증 정보 확인 (메인페이지에서 전달받은 정보 사용)
    var userId = scwin.getCurrentUserId();
    if (!userId) {
        console.error("사용자 인증 정보가 없습니다.");
        console.log("메인페이지에서 사용자 정보가 전달되지 않았습니다.");
        console.log("⚠️ 사용자 정보가 없지만 WebSocket 연결은 시도합니다.");
    } else {
        console.log("사용자 인증 확인 완료:", userId);
    }

    // 페이지 로드 시 데이터 바인딩
    scwin.loadProjectData();

    // WebSocket 연결 초기화 (사용자 정보 없어도 연결 시도)
    console.log("WebSocket 초기화 시작...");
    scwin.initWebSocket();

    // 정렬 기본값 설정
    scwin.initSortControls();

    console.log("projectMainPage 초기화 완료");
};

// 프로젝트 데이터 로드 함수
scwin.loadProjectData = function () {
    console.log("프로젝트 데이터 로드 완료");
};

// ==================== WebSocket 연결 및 관리 ====================

// WebSocket 전역 변수
scwin.websocket = null;
scwin.isWebSocketConnected = false;
scwin.reconnectAttempts = 0;
scwin.maxReconnectAttempts = 5;
scwin.reconnectDelay = 3000; // 3초
scwin.wsUrls = null; // WebSocket URL 목록 저장

// 태스크 데이터 전역 변수
scwin.taskList = null; // 서버에서 받아온 태스크 목록

// 드래그 락 시스템 전역 변수
scwin.lockedCards = new Map(); // taskId -> {userId, userName, timestamp}
scwin.myLockedCards = new Set(); // 내가 락한 카드들의 taskId
scwin.lockTimeout = 30000; // 30초 후 자동 락 해제

/**
 * WebSocket 연결 초기화
 */
scwin.initWebSocket = function () {
    console.log("WebSocket 연결 테스트 시작");

    // 디바운싱 타이머 변수
    scwin.debounceTimer = null;
    scwin.debounceDelay = 2000;

    console.log("현재 위치:", window.location.href);
    console.log("현재 프로토콜:", window.location.protocol);
    console.log("현재 호스트:", window.location.host);

    // 간단한 WebSocket URL
    var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    var host = window.location.host;

    // 다양한 WebSocket 경로 시도
    var possibleUrls = [
        protocol + '//' + host + '/InsWebApp/kanban',
        protocol + '//' + host + '/kanban',
        protocol + '//' + host + '/websocket',
        protocol + '//' + host + '/ws',
        protocol + '//' + host + '/InsWebApp/ws'
    ];

    console.log("시도할 WebSocket URL 목록:", possibleUrls);
    var websocketUrl = possibleUrls[0]; // 첫 번째 URL 시도

    console.log("연결 시도 URL:", websocketUrl);

    try {
        console.log("WebSocket 객체 생성 시도...");
        scwin.websocket = new WebSocket(websocketUrl);
        console.log("✅ WebSocket 객체 생성 성공:", scwin.websocket);
        console.log("WebSocket 초기 상태:", scwin.websocket.readyState);

        // 핸들러 설정
        scwin.setupWebSocketHandlers(websocketUrl);

        // 연결 상태 모니터링
        setTimeout(function () {
            if (scwin.websocket) {
                console.log("5초 후 WebSocket 상태 체크:");
                console.log("- 상태:", scwin.websocket.readyState);
                console.log("- 연결됨:", scwin.isWebSocketConnected);
                if (scwin.websocket.readyState !== WebSocket.OPEN) {
                    console.warn("⚠️ WebSocket이 5초 내에 연결되지 않았습니다.");
                    console.warn("다른 URL을 시도합니다...");
                    scwin.tryAlternativeWebSocketUrl();
                }
            } else {
                console.error(" WebSocket 객체가 사라졌습니다.");
            }
        }, 5000);

    } catch (error) {
        console.error(" WebSocket 생성 중 치명적 오류 발생!");
        console.error("- 오류 메시지:", error.message);
        console.error("- 오류 스택:", error.stack);
        console.error("- 브라우저 WebSocket 지원:", typeof WebSocket !== 'undefined');
        console.error("- 시도한 URL:", websocketUrl);
        scwin.websocket = null;
        scwin.isWebSocketConnected = false;

        // 대체 URL 시도
        scwin.tryAlternativeWebSocketUrl();
    }
};

/**
 * 대체 WebSocket URL 시도
 */
scwin.currentUrlIndex = 0;
scwin.tryAlternativeWebSocketUrl = function () {
    scwin.currentUrlIndex = (scwin.currentUrlIndex || 0) + 1;

    var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    var host = window.location.host;
    var possibleUrls = [
        protocol + '//' + host + '/InsWebApp/kanban',
        protocol + '//' + host + '/kanban',
        protocol + '//' + host + '/websocket',
        protocol + '//' + host + '/ws',
        protocol + '//' + host + '/InsWebApp/ws'
    ];

    if (scwin.currentUrlIndex < possibleUrls.length) {
        var nextUrl = possibleUrls[scwin.currentUrlIndex];
        console.log("대체 WebSocket URL 시도:", nextUrl, "(", scwin.currentUrlIndex + 1, "/", possibleUrls.length, ")");

        setTimeout(function () {
            try {
                scwin.websocket = new WebSocket(nextUrl);
                scwin.setupWebSocketHandlers(nextUrl);
            } catch (error) {
                console.error("대체 URL 연결 실패:", error);
                scwin.tryAlternativeWebSocketUrl();
            }
        }, 2000); // 2초 후 재시도
    } else {
        console.error(" 모든 WebSocket URL 시도 실패. WebSocket 연결을 포기합니다.");
        scwin.websocket = null;
        scwin.isWebSocketConnected = false;
    }
};

/**
 * WebSocket 핸들러 설정 (재사용 가능한 함수)
 */
scwin.setupWebSocketHandlers = function (websocketUrl) {
    scwin.websocket.onopen = function (event) {
        console.log(" WebSocket 연결 성공! URL:", websocketUrl);
        scwin.isWebSocketConnected = true;
        scwin.sendUserJoinMessage();
    };

    scwin.websocket.onmessage = function (event) {
        console.log("=== WebSocket 메시지 수신 ===");
        try {
            var message = JSON.parse(event.data);
            scwin.handleWebSocketMessage(message);
        } catch (error) {
            console.error("메시지 파싱 오류:", error);
        }
    };

    scwin.websocket.onclose = function (event) {
        console.log(" WebSocket 연결 종료");
        scwin.isWebSocketConnected = false;
        scwin.websocket = null;
    };

    scwin.websocket.onerror = function (event) {
        console.error(" WebSocket 연결 오류:", websocketUrl);
        scwin.isWebSocketConnected = false;
        scwin.tryAlternativeWebSocketUrl();
    };
};

/**
 * WebSocket 연결 성공 이벤트
 */
scwin.onWebSocketOpen = function (event) {
    console.log("=== WebSocket 연결 성공 ===");
    scwin.isWebSocketConnected = true;
    scwin.reconnectAttempts = 0;

    // 사용자 참여 메시지 전송
    scwin.sendUserJoinMessage();

    // 연결 상태 표시 (선택사항)
    scwin.updateConnectionStatus(true);
};

/**
 * WebSocket 메시지 수신 이벤트
 */
scwin.onWebSocketMessage = function (event) {
    console.log("WebSocket 메시지 수신:", event.data);

    try {
        var message = JSON.parse(event.data);
        scwin.handleWebSocketMessage(message);
    } catch (error) {
        console.error("메시지 파싱 오류:", error);
    }
};

/**
 * WebSocket 연결 종료 이벤트
 */
scwin.onWebSocketClose = function (event) {
    console.log("WebSocket 연결 종료:", event.code, event.reason);
    scwin.isWebSocketConnected = false;

    // 연결 상태 표시 업데이트
    scwin.updateConnectionStatus(false);

    // 자동 재연결 제거됨
};

// 복잡한 재시도 로직 제거됨

/**
 * WebSocket 에러 이벤트
 */
scwin.onWebSocketError = function (event) {
    console.error(" WebSocket 에러 발생:");
    console.error("  - readyState:", scwin.websocket ? scwin.websocket.readyState : 'undefined');
    console.error("  - event:", event);

    scwin.isWebSocketConnected = false;

    // 상세 에러 정보 표시
    var readyStateText = {
        0: "CONNECTING (연결 중)",
        1: "OPEN (연결됨)",
        2: "CLOSING (연결 종료 중)",
        3: "CLOSED (연결 종료됨)"
    };

    if (scwin.websocket) {
        console.error(" WebSocket 상태:", readyStateText[scwin.websocket.readyState] || "알 수 없음");
    }
};

/**
 * 사용자 참여 메시지 전송
 */
scwin.sendUserJoinMessage = function () {
    var currentUserId = scwin.getCurrentUserId();
    var message = {
        type: "USER_JOIN",
        userId: currentUserId || "unknown",
        timestamp: Date.now()
    };

    console.log("사용자 참여 메시지 전송:", message);
    scwin.sendWebSocketMessage(message);
};

/**
 * WebSocket 메시지 전송
 */
scwin.sendWebSocketMessage = function (message) {
    console.log("=== WebSocket 메시지 전송 시도 ===");
    console.log("전송할 메시지:", message);
    console.log("WebSocket 상태:", scwin.websocket ? scwin.websocket.readyState : "WebSocket 객체 없음");

    if (scwin.websocket && scwin.websocket.readyState === WebSocket.OPEN) {
        var jsonMessage = JSON.stringify(message);
        scwin.websocket.send(jsonMessage);
        console.log("✅ WebSocket 메시지 전송 성공:", jsonMessage);
    } else {
        console.error("❌ WebSocket 연결이 되어있지 않습니다.");
        console.log("WebSocket 상태 상세:");
        if (scwin.websocket) {
            console.log("- readyState:", scwin.websocket.readyState);
            console.log("- CONNECTING (0):", scwin.websocket.readyState === 0);
            console.log("- OPEN (1):", scwin.websocket.readyState === 1);
            console.log("- CLOSING (2):", scwin.websocket.readyState === 2);
            console.log("- CLOSED (3):", scwin.websocket.readyState === 3);
        } else {
            console.log("- WebSocket 객체가 존재하지 않습니다.");
        }
    }
};

/**
 * WebSocket 메시지 처리
 */
scwin.handleWebSocketMessage = function (message) {
    console.log("메시지 처리:", message.type);

    switch (message.type) {
        case "CONNECTION_SUCCESS":
            console.log("연결 성공:", message.message);
            break;
        case "USER_JOIN_SUCCESS":
            console.log("사용자 참여 성공:", message.message);
            break;
        case "CARD_MOVED":
        case "CARD_MOVE":
            scwin.handleCardMovedMessage(message);
            break;
        case "CARD_LOCK":
            scwin.handleCardLockMessage(message);
            break;
        case "TASK_UPDATED":
            scwin.handleTaskUpdatedMessage(message);
            break;
        case "TASK_DELETED":
            scwin.handleTaskDeletedMessage(message);
            break;
        case "PONG":
            console.log("PONG 수신");
            break;
        case "ERROR":
            console.error("서버 에러:", message.message);
            break;
        default:
            console.log("알 수 없는 메시지 타입:", message.type);
    }
};

/**
 * 카드 이동 메시지 처리 (다른 사용자의 실시간 카드 이동 반영)
 */
scwin.handleCardMovedMessage = function (message) {
    console.log("=== 카드 이동 메시지 수신 ===");
    console.log("전체 메시지:", message);
    console.log("- 메시지 타입:", message.type);
    console.log("- taskId:", message.taskId, "타입:", typeof message.taskId);
    console.log("- fromBoardId:", message.fromBoardId, "타입:", typeof message.fromBoardId);
    console.log("- toBoardId:", message.toBoardId, "타입:", typeof message.toBoardId);
    console.log("- userId:", message.userId);
    console.log("- projectId:", message.projectId);
    console.log("- timestamp:", message.timestamp);

    // 중복 방지 로직 개선
    var currentUserId = scwin.getCurrentUserId();
    console.log("현재 사용자 ID:", currentUserId);
    console.log("메시지 사용자 ID:", message.userId);

    // CARD_MOVE (본인이 보낸 메시지)는 무시, CARD_MOVED (서버 브로드캐스트)는 처리
    if (message.type === "CARD_MOVE" && message.userId === currentUserId) {
        console.log("ℹ️ 본인이 보낸 CARD_MOVE 메시지이므로 처리하지 않습니다.");
        return;
    }

    // CARD_MOVED 메시지거나 다른 사용자의 메시지인 경우 처리
    if (message.type === "CARD_MOVED") {
        console.log("������ CARD_MOVED 메시지를 처리합니다.");
    } else if (message.userId !== currentUserId) {
        console.log("������ 다른 사용자의 카드 이동을 처리합니다.");
    } else {
        console.log("ℹ️ 처리하지 않는 메시지입니다.");
        return;
    }

    // 메시지 유효성 검증
    if (!message.taskId || !message.toBoardId) {
        console.error("❌ 잘못된 카드 이동 메시지:", message);
        console.error("필수 필드 확인: taskId=", message.taskId, "toBoardId=", message.toBoardId);
        return;
    }

    console.log("✅ 메시지 유효성 검증 통과 - 카드 이동 처리 시작");

    // 실제 카드 이동 처리
    scwin.updateCardPositionFromMessage(message);
};

/**
 * 태스크 업데이트 메시지 처리 (다른 사용자의 실시간 태스크 수정 반영)
 */
scwin.handleTaskUpdatedMessage = function (message) {
    console.log("=== 태스크 업데이트 메시지 수신 ===");
    console.log("전체 메시지:", message);

    // 메시지 유효성 검증
    if (!message.taskId || !message.projectId) {
        console.error("❌ 잘못된 태스크 업데이트 메시지:", message);
        return;
    }

    // 현재 프로젝트가 아니면 무시
    var currentProjectId = $p.getComponentById("dm_projectVo").get("projectId");
    if (message.projectId !== currentProjectId) {
        console.log("ℹ️ 다른 프로젝트의 태스크 업데이트이므로 무시합니다.");
        return;
    }

    console.log("������ 태스크 업데이트 처리 시작:", message.taskId);

    try {
        // 현재 사용자의 변경사항인지 확인
        var currentUserId = scwin.getCurrentUserId();
        var isMyChange = (message.userId && message.userId === currentUserId);

        if (!isMyChange) {
            console.log("������ 다른 사용자의 태스크 변경사항 - 보드 새로고침:", message.boardId);

            // 해당 보드 데이터 새로고침 (다른 사용자의 변경사항만)
            if (message.boardId && scwin.refreshBoardData) {
                scwin.refreshBoardData(message.boardId);
            }
        } else {
            console.log("ℹ️ 내가 변경한 태스크이므로 중복 새로고침 방지");
        }

        // 1. 로컬 캐시 데이터 업데이트
        scwin.updateLocalTaskCache(message);

        // 2. 칸반 보드의 해당 카드 업데이트
        scwin.updateKanbanCardFromMessage(message);

        // 3. 열려있는 태스크 모달이 해당 태스크라면 새로고침 알림
        scwin.checkAndNotifyOpenTaskModal(message);

        console.log("✅ 태스크 업데이트 반영 완료:", message.taskId);

    } catch (error) {
        console.error("❌ 태스크 업데이트 처리 실패:", error);
    }
};

/**
 * 로컬 태스크 캐시 데이터 업데이트
 */
scwin.updateLocalTaskCache = function (message) {
    if (scwin.allTasksData && scwin.allTasksData.length > 0) {
        for (var i = 0; i < scwin.allTasksData.length; i++) {
            var task = scwin.allTasksData[i];
            if (task.taskId === message.taskId) {
                // 업데이트된 속성들을 로컬 캐시에 반영
                if (message.taskTitle !== undefined) task.taskTitle = message.taskTitle;
                if (message.priority !== undefined) task.priority = message.priority;
                if (message.startDate !== undefined) task.startDate = message.startDate;
                if (message.endDate !== undefined) task.endDate = message.endDate;
                if (message.tags !== undefined) task.tags = message.tags;
                if (message.boardId !== undefined) task.boardId = message.boardId;

                console.log("������ 로컬 태스크 캐시 업데이트 완료:", task.taskId);
                break;
            }
        }
    }
};

/**
 * 칸반 보드의 카드 업데이트
 */
scwin.updateKanbanCardFromMessage = function (message) {
    try {
        // 칸반 보드에서 해당 태스크 카드 찾기
        var cardElement = document.querySelector('[data-task-id="' + message.taskId + '"]');
        if (cardElement) {
            // 카드 제목 업데이트
            if (message.taskTitle !== undefined) {
                var titleElement = cardElement.querySelector('.card-title');
                if (titleElement) {
                    titleElement.textContent = message.taskTitle;
                }
            }

            // 우선순위 배지 업데이트
            if (message.priority !== undefined) {
                var priorityElement = cardElement.querySelector('.priority-badge');
                if (priorityElement) {
                    priorityElement.className = 'priority-badge priority-' + (message.priority || 'none');
                    priorityElement.textContent = message.priority || '';
                }
            }

            // 날짜 정보 업데이트
            if (message.startDate !== undefined || message.endDate !== undefined) {
                var dateElement = cardElement.querySelector('.task-dates');
                if (dateElement && (message.startDate || message.endDate)) {
                    var dateText = '';
                    if (message.startDate && message.endDate) {
                        dateText = message.startDate + ' ~ ' + message.endDate;
                    } else if (message.startDate) {
                        dateText = '시작: ' + message.startDate;
                    } else if (message.endDate) {
                        dateText = '마감: ' + message.endDate;
                    }
                    dateElement.textContent = dateText;
                }
            }

            // 카드에 업데이트 애니메이션 효과 추가
            cardElement.style.boxShadow = '0 0 10px rgba(0, 123, 255, 0.5)';
            setTimeout(function() {
                cardElement.style.boxShadow = '';
            }, 2000);

            console.log("������ 칸반 카드 UI 업데이트 완료:", message.taskId);
        } else {
            console.log("⚠️ 칸반 보드에서 해당 카드를 찾을 수 없음:", message.taskId);
        }
    } catch (error) {
        console.error("❌ 칸반 카드 업데이트 실패:", error);
    }
};

/**
 * 열려있는 태스크 모달 확인 및 알림
 */
scwin.checkAndNotifyOpenTaskModal = function (message) {
    try {
        // 현재 열려있는 팝업이 해당 태스크의 모달인지 확인
        var openPopups = $p.getPopupList();
        for (var i = 0; i < openPopups.length; i++) {
            var popup = openPopups[i];
            if (popup.id === "exa_popup" && popup.dataObject && popup.dataObject.data) {
                var popupTaskId = popup.dataObject.data.taskId;
                if (popupTaskId === message.taskId) {
                    // 같은 태스크 모달이 열려있으면 알림 표시
                    console.log("������ 현재 편집 중인 태스크가 다른 사용자에 의해 수정되었습니다:", message.taskId);
                    // TODO: 사용자에게 알림 표시 (예: 토스트 메시지)
                    break;
                }
            }
        }
    } catch (error) {
        console.error("❌ 태스크 모달 확인 실패:", error);
    }
};

/**
 * 태스크 삭제 메시지 처리 (다른 사용자의 실시간 태스크 삭제 반영)
 */
scwin.handleTaskDeletedMessage = function (message) {
    console.log("=== 태스크 삭제 메시지 수신 ===");
    console.log("전체 메시지:", message);

    // 메시지 유효성 검증
    if (!message.taskId || !message.projectId) {
        console.error("❌ 잘못된 태스크 삭제 메시지:", message);
        return;
    }

    // 현재 프로젝트가 아니면 무시
    var currentProjectId = $p.getComponentById("dm_projectVo").get("projectId");
    if (message.projectId !== currentProjectId) {
        console.log("ℹ️ 다른 프로젝트의 태스크 삭제이므로 무시합니다.");
        return;
    }

    console.log("������️ 태스크 삭제 처리 시작:", message.taskId);

    try {
        // 1. 로컬 캐시 데이터에서 제거
        scwin.removeTaskFromLocalCache(message.taskId);

        // 2. 칸반 보드에서 해당 카드 제거
        scwin.removeKanbanCardFromUI(message.taskId);

        // 3. 열려있는 태스크 모달이 해당 태스크라면 닫기
        scwin.closeOpenTaskModalIfMatches(message.taskId);

        console.log("✅ 태스크 삭제 반영 완료:", message.taskId);

    } catch (error) {
        console.error("❌ 태스크 삭제 처리 실패:", error);
    }
};

/**
 * 로컬 태스크 캐시에서 삭제된 태스크 제거
 */
scwin.removeTaskFromLocalCache = function (taskId) {
    if (scwin.allTasksData && scwin.allTasksData.length > 0) {
        for (var i = scwin.allTasksData.length - 1; i >= 0; i--) {
            if (scwin.allTasksData[i].taskId === taskId) {
                scwin.allTasksData.splice(i, 1);
                console.log("������ 로컬 태스크 캐시에서 삭제 완료:", taskId);
                break;
            }
        }
    }
};

/**
 * 칸반 보드에서 삭제된 카드 제거
 */
scwin.removeKanbanCardFromUI = function (taskId) {
    try {
        // 칸반 보드에서 해당 태스크 카드 찾기
        var cardElement = document.querySelector('[data-task-id="' + taskId + '"]');
        if (cardElement) {
            // 삭제 애니메이션 효과
            cardElement.style.transition = 'all 0.3s ease-out';
            cardElement.style.transform = 'scale(0)';
            cardElement.style.opacity = '0';

            // 애니메이션 완료 후 DOM에서 제거
            setTimeout(function() {
                if (cardElement.parentNode) {
                    cardElement.parentNode.removeChild(cardElement);
                }
            }, 300);

            console.log("������ 칸반 카드 UI에서 삭제 완료:", taskId);
        } else {
            console.log("⚠️ 칸반 보드에서 해당 카드를 찾을 수 없음:", taskId);
        }
    } catch (error) {
        console.error("❌ 칸반 카드 삭제 실패:", error);
    }
};

/**
 * 삭제된 태스크의 모달이 열려있으면 닫기
 */
scwin.closeOpenTaskModalIfMatches = function (taskId) {
    try {
        // 현재 열려있는 팝업 확인
        var openPopups = $p.getPopupList();
        for (var i = 0; i < openPopups.length; i++) {
            var popup = openPopups[i];
            if (popup.id === "exa_popup" && popup.dataObject && popup.dataObject.data) {
                var popupTaskId = popup.dataObject.data.taskId;
                if (popupTaskId === taskId) {
                    // 삭제된 태스크의 모달이면 닫기
                    console.log("������ 삭제된 태스크의 모달을 닫습니다:", taskId);
                    $p.closePopup(popup.id);
                    // TODO: 사용자에게 삭제 알림 표시
                    break;
                }
            }
        }
    } catch (error) {
        console.error("❌ 태스크 모달 닫기 실패:", error);
    }
};

/**
 * 연결 상태 표시 업데이트
 */
scwin.updateConnectionStatus = function (isConnected) {
    // TODO: UI에 연결 상태 표시
    console.log("연결 상태:", isConnected ? "연결됨" : "연결 끔어짐");
};

/**
 * 카드 이동 메시지 전송
 */
scwin.sendCardMoveMessage = function (taskId, fromBoardId, toBoardId) {
    console.log("=== 카드 이동 메시지 전송 시작 ===");
    console.log("파라미터:", { taskId: taskId, fromBoardId: fromBoardId, toBoardId: toBoardId });

    // 현재 프로젝트 ID 가져오기
    var projectId = null;
    if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
        projectId = scwin.currentProjectData.projectId;
        console.log("currentProjectData에서 projectId 가져옴:", projectId);
    } else {
        // 프로젝트 데이터가 없으면 URL에서 추출 시도
        var urlParams = new URLSearchParams(window.location.search);
        projectId = urlParams.get('projectId');
        console.log("URL에서 projectId 가져옴:", projectId);
    }

    var currentUserId = scwin.getCurrentUserId();
    console.log("현재 사용자 ID:", currentUserId);

    var message = {
        type: "CARD_MOVE",
        taskId: taskId,
        fromBoardId: fromBoardId,
        toBoardId: toBoardId,
        projectId: projectId,
        userId: currentUserId,
        timestamp: Date.now()
    };

    console.log("������ 카드 이동 메시지 전송:", message);
    scwin.sendWebSocketMessage(message);
};

/**
 * 현재 사용자 ID 가져오기 (dm_userInfo에서만 조회)
 */
scwin.getCurrentUserId = function () {
    var currentUserId = null;

    try {
        console.log("현재 사용자 ID 조회 시작");

        // dm_userInfo에서 가져오기 (메인페이지에서 전달받은 데이터)
        var userInfo = $p.getComponentById("dm_userInfo").get("userId");
        if (userInfo) {
            currentUserId = userInfo.trim();
            console.log("dm_userInfo에서 사용자 ID:", currentUserId);
        } else {
            console.error("dm_userInfo에 사용자 ID가 없습니다.");
        }

    } catch (e) {
        console.error("사용자 ID 가져오기 실패:", e);
        currentUserId = null;
    }

    return currentUserId;
};

/**
 * 현재 사용자 이름 가져오기
 */
scwin.getCurrentUserName = function () {
    try {
        var userInfo = $p.getComponentById("dm_userInfo");
        if (userInfo) {
            var userName = userInfo.get("userName");
            if (userName) {
                return userName.trim();
            }
        }
        console.error("dm_userInfo에 사용자 이름이 없습니다.");
        return "알 수 없음";
    } catch (e) {
        console.error("사용자 이름 가져오기 실패:", e);
        return "알 수 없음";
    }
};

/**
 * 사용자 역할 확인 후 프로젝트 설정 버튼 제어
 */
scwin.checkUserPermissionForSettings = function() {
    console.log("사용자 권한 확인 시작");

    try {
        var userId = scwin.getCurrentUserId();
        var projectId = scwin.currentProjectData ? scwin.currentProjectData.projectId : null;

        // 프로젝트 ID가 없으면 URL에서 가져오기 시도
        if (!projectId) {
            try {
                var urlParams = new URLSearchParams(window.location.search);
                projectId = urlParams.get('projectId');
            } catch (e) {
                console.error("URL에서 projectId 가져오기 실패:", e);
            }
        }

        if (!userId || !projectId) {
            console.error("사용자 ID 또는 프로젝트 ID가 없습니다.", {userId: userId, projectId: projectId});
            // 기본적으로 버튼을 숨김
            scwin.hideSettingsButton();
            return;
        }

        console.log("역할 확인 요청:", {userId: userId, projectId: projectId});

        // 백엔드 API 호출
        $.ajax({
            type: "GET",
            url: "/InsWebApp/checkUserRole.pwkjson",
            data: {
                userId: userId,
                projectId: projectId
            },
            dataType: "json",
            success: function(data) {
                console.log("역할 확인 응답:", data);

                if (data.success && data.isAdmin) {
                    console.log("관리자 권한 확인 - 설정 버튼 표시");
                    scwin.showSettingsButton();
                } else {
                    console.log("관리자 권한 없음 - 설정 버튼 숨김");
                    scwin.hideSettingsButton();
                }
            },
            error: function(xhr, status, error) {
                console.error("역할 확인 API 호출 실패:", error);
                // 오류 시 기본적으로 버튼을 숨김
                scwin.hideSettingsButton();
            }
        });

    } catch (e) {
        console.error("사용자 권한 확인 중 오류:", e);
        scwin.hideSettingsButton();
    }
};

/**
 * 프로젝트 설정 버튼 표시
 */
scwin.showSettingsButton = function() {
    try {
        var settingsBtn = $p.getComponentById("btn_settings");
        if (settingsBtn) {
            settingsBtn.show();
            console.log("프로젝트 설정 버튼 표시됨");
        } else {
            console.error("btn_settings 컴포넌트를 찾을 수 없습니다.");
        }
    } catch (e) {
        console.error("설정 버튼 표시 중 오류:", e);
    }
};

/**
 * 프로젝트 설정 버튼 숨김
 */
scwin.hideSettingsButton = function() {
    try {
        var settingsBtn = $p.getComponentById("btn_settings");
        if (settingsBtn) {
            settingsBtn.hide();
            console.log("프로젝트 설정 버튼 숨김");
        } else {
            console.error("btn_settings 컴포넌트를 찾을 수 없습니다.");
        }
    } catch (e) {
        console.error("설정 버튼 숨김 중 오류:", e);
    }
};

/**
 * 사용자 ID로 사용자 이름 가져오기 (태스크 데이터에서 userName 사용)
 */
scwin.getUserNameByUserId = function (userId, taskData) {
    if (!userId) {
        return "담당자 없음";
    }

    try {
        // taskData에 userName이 있으면 우선 사용
        if (taskData && taskData.userName) {
            return taskData.userName;
        }

        // 태스크 리스트에서 해당 userId의 userName 찾기
        scwin.taskList = $p.getComponentById("dlt_scwin.taskList");
        if (scwin.taskList) {
            var rowCount = scwin.taskList.getRowCount();
            for (var i = 0; i < rowCount; i++) {
                var projectUserId = scwin.taskList.getCellData(i, "projectUserId");
                var userName = scwin.taskList.getCellData(i, "userName");
                if (projectUserId === userId && userName) {
                    return userName;
                }
            }
        }

        // 현재 로그인한 사용자의 정보인지 확인
        var currentUserId = scwin.getCurrentUserId();
        if (userId === currentUserId) {
            var userInfo = $p.getComponentById("dm_userInfo");
            if (userInfo) {
                var userName = userInfo.get("userName");
                if (userName) {
                    return userName;
                }
            }
        }

        // 모든 방법이 실패하면 userId 반환
        return userId;
    } catch (e) {
        console.error("사용자 이름 조회 실패:", e);
        return userId || "알 수 없음";
    }
};

/**
 * 메시지로부터 카드 위치 업데이트 (실시간 동기화 핵심 로직)
 */
scwin.updateCardPositionFromMessage = function (message) {
    console.log("������ === 실시간 카드 위치 업데이트 시작 ===");
    console.log("������ 수신된 메시지:", message);

    var taskId = message.taskId;
    var fromBoardId = message.fromBoardId;
    var toBoardId = message.toBoardId;

    console.log("������ 이동 정보:");
    console.log("- taskId:", taskId);
    console.log("- fromBoardId:", fromBoardId);
    console.log("- toBoardId:", toBoardId);

    // 1. 이동할 카드 찾기
    console.log("������ 1단계: 이동할 카드 찾기");
    var cardElement = scwin.findCardByTaskId(taskId);
    if (!cardElement) {
        console.error("❌ 카드를 찾을 수 없습니다:", taskId);
        console.error("현재 페이지의 모든 카드 확인:");
        var allCards = document.querySelectorAll("[data-task-id]");
        allCards.forEach((card, index) => {
            console.error(`카드 ${index + 1}: taskId=${card.getAttribute("data-task-id")}, id=${card.id}`);
        });
        return;
    }

    console.log("✅ 카드 찾기 성공!");
    console.log("카드 요소:", cardElement);
    console.log("카드 현재 위치:", cardElement.parentElement);

    // 2. 타겟 보드 컨테이너 찾기
    console.log("������ 2단계: 타겟 보드 컨테이너 찾기");
    var targetContainerId = "card_container_" + toBoardId;
    console.log("찾을 컨테이너 ID:", targetContainerId);

    var targetContainer = null;

    try {
        targetContainer = eval(targetContainerId);
        console.log("eval 결과:", targetContainer);
    } catch (e) {
        console.error("❌ eval로 타겟 컨테이너 찾기 실패:", targetContainerId, e);
    }

    // 백업 방법: $p.getComponentById 사용
    if (!targetContainer) {
        console.log("������ 백업 방법: $p.getComponentById 사용");
        try {
            targetContainer = $p.getComponentById(targetContainerId);
            console.log("$p.getComponentById 결과:", targetContainer);
        } catch (e) {
            console.error("❌ $p.getComponentById도 실패:", e);
        }
    }

    if (!targetContainer) {
        console.error("❌ 타겟 컨테이너를 찾을 수 없습니다:", targetContainerId);
        console.error("현재 페이지의 모든 컨테이너 확인:");
        var allContainers = document.querySelectorAll("[id*='card_container_']");
        allContainers.forEach((container, index) => {
            console.error(`컨테이너 ${index + 1}: id=${container.id}`);
        });
        return;
    }

    console.log("✅ 타겟 컨테이너 찾기 성공!");
    console.log("타겟 컨테이너:", targetContainer);
    console.log("타겟 컨테이너 ID:", targetContainer.id || targetContainer.getID());

    // 3. 카드 이동 애니메이션 및 DOM 업데이트
    console.log("������ 3단계: 카드 이동 애니메이션 실행");
    try {
        scwin.animateCardMove(cardElement, targetContainer, fromBoardId, toBoardId, taskId);
        console.log("✅ 카드 이동 애니메이션 호출 성공");
    } catch (error) {
        console.error("❌ 카드 이동 애니메이션 실행 중 오류:", error);
        console.error("오류 스택:", error.stack);
    }

    console.log("������ === 실시간 카드 위치 업데이트 완료 ===");
};

/**
 * taskId로 카드 DOM 요소 찾기 (강화된 디버깅 버전)
 */
scwin.findCardByTaskId = function (taskId) {
    console.log("=== 카드 찾기 시작 ===");
    console.log("찾을 taskId:", taskId, "타입:", typeof taskId);

    // 방법 1: data-task-id 속성으로 찾기
    console.log("방법 1: data-task-id 속성으로 검색");
    var cardElement = document.querySelector(`[data-task-id="${taskId}"]`);
    if (cardElement) {
        console.log("✅ data-task-id로 카드 찾기 성공:", cardElement);
        console.log("카드 element:", cardElement.outerHTML.substring(0, 200) + "...");
        return cardElement;
    } else {
        console.log("❌ data-task-id로 찾기 실패");
        // 디버깅: 현재 존재하는 모든 data-task-id 출력
        var allCards = document.querySelectorAll("[data-task-id]");
        console.log("현재 존재하는 카드들:", Array.from(allCards).map(card => card.getAttribute("data-task-id")));
    }

    // 방법 2: 카드 ID로 찾기 (card_taskId 형식)
    console.log("방법 2: 카드 ID로 검색");
    var cardId = "card_" + taskId;
    console.log("검색할 카드 ID:", cardId);

    var cardComponent = null;
    try {
        cardComponent = eval(cardId);
        console.log("eval 결과:", cardComponent);
        if (cardComponent && cardComponent.element) {
            console.log("✅ 카드 ID로 컴포넌트 찾기 성공:", cardComponent);
            return cardComponent.element;
        }
    } catch (e) {
        console.log("❌ eval로 카드 ID 찾기 실패:", cardId, e.message);
    }

    // 방법 3: WebSquare 컴포넌트 ID로 찾기
    console.log("방법 3: WebSquare 컴포넌트 ID로 검색");
    try {
        cardComponent = $p.getComponentById(cardId);
        console.log("$p.getComponentById 결과:", cardComponent);
        if (cardComponent && cardComponent.element) {
            console.log("✅ WebSquare ID로 카드 찾기 성공:", cardComponent);
            return cardComponent.element;
        }
    } catch (e) {
        console.log("❌ WebSquare ID로 찾기 실패:", cardId, e.message);
    }

    // 방법 4: DOM에서 직접 ID로 찾기
    console.log("방법 4: DOM에서 직접 ID로 검색");
    cardElement = document.getElementById(cardId);
    if (cardElement) {
        console.log("✅ DOM ID로 카드 찾기 성공:", cardElement);
        return cardElement;
    } else {
        console.log("❌ DOM ID로 찾기 실패:", cardId);
    }

    // 방법 5: 모든 project-card 클래스 요소에서 검색
    console.log("방법 5: 모든 project-card에서 taskId 매칭 검색");
    var allProjectCards = document.querySelectorAll(".project-card, .draggable-card");
    console.log("총 프로젝트 카드 수:", allProjectCards.length);

    for (var i = 0; i < allProjectCards.length; i++) {
        var card = allProjectCards[i];
        var cardTaskId = card.getAttribute("data-task-id");
        console.log(`카드 ${i + 1}: data-task-id="${cardTaskId}"`);

        // 문자열과 숫자 비교 모두 확인
        if (cardTaskId == taskId || cardTaskId === taskId.toString() || cardTaskId === parseInt(taskId)) {
            console.log("✅ 매칭되는 카드 발견:", card);
            return card;
        }
    }

    console.error("=== 모든 방법으로 카드를 찾을 수 없습니다 ===");
    console.error("찾으려던 taskId:", taskId);
    console.error("현재 페이지의 모든 카드 정보:");
    allProjectCards.forEach((card, index) => {
        console.error(`카드 ${index + 1}: ID=${card.id}, data-task-id=${card.getAttribute("data-task-id")}`);
    });

    return null;
};

/**
 * 카드 이동 애니메이션 및 DOM 업데이트
 */
scwin.animateCardMove = function (cardElement, targetContainer, fromBoardId, toBoardId, taskId) {
    console.log("������ === 카드 이동 애니메이션 시작 ===");
    console.log("������ 이동 파라미터:");
    console.log("- cardElement:", cardElement);
    console.log("- targetContainer:", targetContainer);
    console.log("- fromBoardId:", fromBoardId);
    console.log("- toBoardId:", toBoardId);
    console.log("- taskId:", taskId);

    try {
        // 애니메이션 클래스 추가
        console.log("������ 1단계: 애니메이션 클래스 추가");
        cardElement.classList.add("moving-remotely");
        console.log("✅ moving-remotely 클래스 추가 완료");

        // 실제 DOM 이동
        console.log("������ 2단계: DOM 이동 처리");
        var targetElement = targetContainer.element || targetContainer;
        console.log("타겟 엘리먼트:", targetElement);
        console.log("타겟 엘리먼트 타입:", typeof targetElement);
        console.log("타겟 엘리먼트 태그:", targetElement.tagName);
        console.log("현재 카드 위치:", cardElement.parentElement);

        // DOM 이동 실행
        targetElement.appendChild(cardElement);
        console.log("✅ DOM 이동 완료");
        console.log("이동 후 카드 위치:", cardElement.parentElement);

        // 카드의 data-board-id 업데이트
        console.log("������️ 3단계: data-board-id 업데이트");
        console.log("이전 data-board-id:", cardElement.getAttribute("data-board-id"));
        cardElement.setAttribute("data-board-id", toBoardId);
        console.log("새로운 data-board-id:", cardElement.getAttribute("data-board-id"));

        // 보드 카운트 업데이트
        console.log("������ 4단계: 보드 카운트 업데이트");
        scwin.updateBoardCardCounts(fromBoardId, toBoardId);

        // 애니메이션 완료 후 클래스 제거
        setTimeout(function () {
            console.log("������ 5단계: 애니메이션 클래스 제거");
            cardElement.classList.remove("moving-remotely");
            console.log("✅ 카드 이동 애니메이션 완료:", taskId);

            // 이동 완료 알림 (선택사항)
            try {
                scwin.showCardMoveNotification(taskId, fromBoardId, toBoardId);
            } catch (notificationError) {
                console.log("알림 표시 중 오류 (무시 가능):", notificationError.message);
            }
        }, 300);

        console.log("������ 카드 DOM 이동 성공:", taskId, "->", toBoardId);

    } catch (error) {
        console.error("������ 카드 이동 중 치명적 오류 발생:");
        console.error("- 오류 메시지:", error.message);
        console.error("- 오류 스택:", error.stack);
        console.error("- cardElement 상태:", cardElement);
        console.error("- targetContainer 상태:", targetContainer);

        // 오류 시 애니메이션 클래스 제거
        if (cardElement && cardElement.classList) {
            cardElement.classList.remove("moving-remotely");
            console.log("������ 오류 시 애니메이션 클래스 제거 완료");
        }
    }
};

/**
 * 보드별 카드 개수 업데이트
 */
scwin.updateBoardCardCounts = function (sourceBoardId, targetBoardId) {
    console.log("보드 카운트 업데이트:", sourceBoardId, "->", targetBoardId);

    // 출발 보드 카운트 감소
    if (sourceBoardId) {
        scwin.updateSingleBoardCardCount(sourceBoardId, -1);
    }

    // 목적지 보드 카운트 증가
    if (targetBoardId) {
        scwin.updateSingleBoardCardCount(targetBoardId, 1);
    }
};

/**
 * 단일 보드의 카드 개수 업데이트
 */
scwin.updateSingleBoardCardCount = function (boardId, delta) {
    var countSpanId = "grp_dynamic_" + boardId + "_count";

    try {
        var countSpan = eval(countSpanId);
        if (!countSpan) {
            countSpan = $p.getComponentById(countSpanId);
        }

        if (countSpan) {
            var currentCount = parseInt(countSpan.getValue() || "0");
            var newCount = Math.max(0, currentCount + delta);
            countSpan.setValue(newCount);

            console.log(`보드 [${boardId}] 카운트 업데이트: ${currentCount} -> ${newCount}`);
        } else {
            console.warn("카운트 스팬을 찾을 수 없습니다:", countSpanId);
        }
    } catch (error) {
        console.error("카운트 업데이트 중 오류:", countSpanId, error);
    }
};

/**
 * 보드 제목 가져오기
 */
scwin.getBoardTitle = function (boardId) {
    try {
        // dlt_boardListVo에서 보드 제목 찾기
        var boardList = dlt_boardListVo.getAllJSON();
        if (boardList && boardList.length > 0) {
            for (var i = 0; i < boardList.length; i++) {
                if (boardList[i].boardId === boardId) {
                    return boardList[i].boardTitle;
                }
            }
        }

        // 제목을 찾지 못한 경우 기본값 반환
        return boardId;
    } catch (error) {
        console.error("보드 제목 가져오기 실패:", boardId, error);
        return boardId;
    }
};

/**
 * 카드 이동 완료 알림 표시
 */
scwin.showCardMoveNotification = function (taskId, fromBoardId, toBoardId) {
    try {
        var fromTitle = scwin.getBoardTitle(fromBoardId);
        var toTitle = scwin.getBoardTitle(toBoardId);

        var message = `다른 사용자가 카드를 "${fromTitle}"에서 "${toTitle}"로 이동했습니다.`;
        console.log("������ " + message);

        // 선택사항: 화면에 토스트 알림 표시
        // scwin.showToastNotification(message, "info");

    } catch (error) {
        console.error("알림 표시 중 오류:", error);
    }
};

/**
 * 테스트용 핑 메시지 전송
 */
scwin.sendPingMessage = function () {
    var message = {
        type: "PING",
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

/**
 * 실시간 동기화 테스트용 함수 (디버깅용)
 */
scwin.testRealtimeSync = function () {
    console.log("=== 실시간 동기화 테스트 시작 ===");

    // 현재 카드 목록 출력
    var allCards = document.querySelectorAll("[data-task-id]");
    console.log("현재 페이지의 카드 수:", allCards.length);
    allCards.forEach((card, index) => {
        console.log(`카드 ${index + 1}: taskId=${card.getAttribute("data-task-id")}, boardId=${card.getAttribute("data-board-id")}`);
    });

    // 테스트 메시지 시뮬레이션
    if (allCards.length > 0) {
        var testCard = allCards[0];
        var testMessage = {
            type: "CARD_MOVED",
            taskId: testCard.getAttribute("data-task-id"),
            fromBoardId: testCard.getAttribute("data-board-id"),
            toBoardId: "BOARD_DONE_001", // 임시 목적지
            userId: "test-user", // 다른 사용자로 시뮬레이션
            timestamp: Date.now()
        };

        console.log("테스트 메시지 시뮬레이션:", testMessage);
        scwin.handleCardMovedMessage(testMessage);
    } else {
        console.log("테스트할 카드가 없습니다.");
    }

    console.log("=== 실시간 동기화 테스트 완료 ===");
};

/**
 * WebSocket 연결 테스트 함수 (디버깅용)
 */
scwin.testWebSocketConnection = function () {
    console.log(" WebSocket 연결 테스트 시작");

    if (!scwin.websocket) {
        console.error(" WebSocket이 초기화되지 않았습니다.");
        return;
    }

    console.log(" 현재 WebSocket 상태:");
    console.log("  - readyState:", scwin.websocket.readyState);
    console.log("  - url:", scwin.websocket.url);

    switch (scwin.websocket.readyState) {
        case WebSocket.CONNECTING:
            console.log(" 연결 시도 중...");
            break;
        case WebSocket.OPEN:
            console.log("✅ 연결됨 - PING 메시지 전송");
            scwin.sendPingMessage();
            break;
        case WebSocket.CLOSING:
            console.log("연결 종료 중...");
            break;
        case WebSocket.CLOSED:
            console.log(" 연결 끊어짐 - 재연결 시도");
            scwin.reconnectWebSocket();
            break;
    }
};

/**
 * 서버 연결 테스트 (HTTP 요청으로 서버 상태 확인)
 */
scwin.testServerConnection = function () {
    console.log("서버 연결 테스트 시작...");

    var testUrl = window.location.protocol + '//' + window.location.host + '/InsWebApp/board/list.pwkjson';

    fetch(testUrl, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
        },
        body: 'projectId=test'
    })
        .then(response => {
            console.log("서버 HTTP 연결 성공:", response.status);
            if (response.ok) {
                console.log(" 서버가 정상 작동 중 - WebSocket 설정 문제일 가능성");
            }
            return response.text();
        })
        .then(data => {
            console.log(" 서버 응답:", data.substring(0, 200) + "...");
        })
        .catch(error => {
            console.error(" 서버 HTTP 연결 실패:", error);
            console.error(" 서버가 실행되지 않았거나 포트가 다를 수 있습니다.");
        });
};

// 프로젝트 데이터 저장 (외부에서 호출 가능)
scwin.currentProjectData = null;

// 프로젝트 데이터 설정 함수
scwin.setProjectData = function (projectData) {
    // 중복 실행 방지
    if (scwin.isSettingProjectData) {
        console.log("이미 프로젝트 데이터를 설정 중입니다. 중복 실행을 방지합니다.");
        return;
    }

    scwin.isSettingProjectData = true;
    scwin.currentProjectData = projectData;
    console.log("프로젝트 데이터 설정됨:", projectData);

    // 프로젝트 제목 업데이트
    if (projectData && projectData.projectName) {
        txt_title.setValue(projectData.projectName);
    }

    // 프로젝트 ID를 dm_projectVo에 설정하고 보드 데이터 로드
    if (projectData && projectData.projectId) {
        console.log("프로젝트 ID로 보드 데이터 로드:", projectData.projectId);
        dm_projectVo.set("projectId", projectData.projectId);
        $p.executeSubmission("load_Board");  // 보드 데이터 로드 실행
    } else {
        console.warn("프로젝트 ID가 없어 보드 데이터를 로드할 수 없습니다:", projectData);
    }

    // 프로젝트 데이터 설정 완료 후 사용자 권한 확인
    scwin.checkUserPermissionForSettings();

    // 플래그 해제
    setTimeout(function () {
        scwin.isSettingProjectData = false;
    }, 100);
};

/**
 * 'Add card' 버튼 클릭 시 동적으로 카드를 생성하는 함수
 * @param {String} parentId 카드를 추가할 부모 Group(칸반 컬럼)의 ID
 */
scwin.addCard_onclick = function (parentId) {
    var parentGroup = $p.getComponentById(parentId);
    var cardId = "dyn_card_" + new Date().getTime();
    var cardOptions = {
        className: "project-card",
        style: "border-color: #2da44e; background-color: #f6ffed;"
    };
    var newCard = $p.dynamicCreate(cardId, "group", cardOptions, parentGroup);

    // 생성된 카드에 onclick 이벤트 핸들러를 연결합니다.
    newCard.bind("onclick", scwin.new_task_onclick);

    // 생성된 input 컴포넌트 객체를 변수에 할당합니다.
    var newInput = $p.dynamicCreate("dyn_input_" + new Date().getTime(), "input", {
        placeholder: "새 작업명을 입력하세요.",
        style: "width: 100%; height: 24px;"
    }, newCard);

    // --- 추가된 코드 ---
    // 1. 생성된 input에 onkeydown 이벤트 핸들러를 연결합니다. [cite: 5]
    newInput.bind("onkeydown", scwin.dynamicInput_onkeydown);

    // 2. 생성된 input에 바로 포커스를 줍니다.
    newInput.focus();
};

/**
 * 동적으로 생성된 Input의 키보드 이벤트(keydown)를 처리하는 함수
 * @param {Event} e 키보드 이벤트 객체
 */
scwin.dynamicInput_onkeydown = function (e) {
    // 이벤트가 발생한 컴포넌트(input) 객체
    var inputComponent = this;

    // 눌린 키의 코드 확인 (Enter: 13, ESC: 27)
    var keyCode = e.keyCode;

    if (keyCode === 13) { // Enter 키를 눌렀을 때
        let input = this.getValue();
        dm_taskVo.set("taskTitle", input);
        $c.sbm.execute("dm_taskVo");

    } else if (keyCode === 27) { // ESC 키를 눌렀을 때
        // 삭제할 대상은 input을 감싸고 있는 부모 컴포넌트(카드 그룹)입니다.
        var cardComponent = inputComponent.getParent();

        if (cardComponent) {
            // $p.remove API로 카드 컴포넌트를 화면에서 삭제합니다.
            cardComponent.remove();
        }
    }
};


// 프로젝트 카드 클릭 이벤트
scwin.projectCard_onclick = function (e) {
    var selectedRow = parseInt(e.target.getAttribute('data-row'));
    if (!isNaN(selectedRow)) {
