        var filterPanel = $p.getComponentById("grp_tag_filter");
        if (filterPanel) {
            filterPanel.show();
            scwin.isTagFilterVisible = true;

            // 현재 선택된 태그들을 UI에 반영
            scwin.updateTagFilterUI();

