    }
};

/**
 * 태그 필터 토글 공통 함수
 */
scwin.toggleTagFilter = function (tagValue) {
    console.log("태그 필터 토글:", tagValue);

    if (tagValue) {
        var tagIndex = scwin.selectedTags.indexOf(tagValue);

        if (tagIndex > -1) {
            // 태그 제거
            scwin.selectedTags.splice(tagIndex, 1);
            console.log("태그 제거됨:", tagValue);
        } else {
            // 태그 추가
            scwin.selectedTags.push(tagValue);
            console.log("태그 추가됨:", tagValue);
        }

        console.log("현재 선택된 태그들:", scwin.selectedTags);

        // UI 업데이트
        scwin.updateTagFilterUI();

        // 태스크 필터링 적용
        scwin.applyTagFilter();
    }
};

