 */
scwin.selectAllTags = function () {
    var allTags = ["dev", "test", "doc", "plan", "analytics", "collabo", "untagged"];

    // 현재 모든 태그가 선택되어 있는지 확인
    var isAllSelected = allTags.every(function (tag) {
        return scwin.selectedTags.indexOf(tag) > -1;
    });

    if (isAllSelected) {
        // 모든 태그가 선택되어 있으면 전체 해제
        scwin.selectedTags = [];
        console.log("전체 태그 해제됨");
    } else {
        // 일부 또는 전혀 선택되어 있지 않으면 전체 선택
        scwin.selectedTags = allTags.slice(); // 배열 복사
        console.log("전체 태그 선택됨:", scwin.selectedTags);
    }

    scwin.updateTagFilterUI();
    scwin.applyTagFilter();
};

