/**
 * 태그 필터 UI 업데이트 (WebSquare trigger 컴포넌트용) - 디버깅 강화
 */
scwin.updateTagFilterUI = function () {
    console.log("====== 태그 UI 업데이트 시작 ======");
    console.log("현재 선택된 태그:", scwin.selectedTags);
    console.log("선택된 태그 개수:", scwin.selectedTags.length);

    var tagButtons = ["btn_tag_dev", "btn_tag_test", "btn_tag_doc", "btn_tag_plan", "btn_tag_analytics", "btn_tag_collabo"];
    var tagValues = ["dev", "test", "doc", "plan", "analytics", "collabo"];

    for (var i = 0; i < tagButtons.length; i++) {
        console.log("\n--- 버튼 " + (i + 1) + "/" + tagButtons.length + " 처리 시작 ---");
        console.log("버튼 ID:", tagButtons[i]);
        console.log("태그 값:", tagValues[i]);

        try {
            // 선택 상태 확인
            var isSelected = scwin.selectedTags.indexOf(tagValues[i]) > -1;
            console.log("선택 상태:", isSelected);

            // WebSquare 컴포넌트 조회
            var buttonComponent = eval(tagButtons[i]);
            console.log("컴포넌트 조회 결과:", buttonComponent);

            if (buttonComponent) {
                // WebSquare 컴포넌트의 모든 속성 탐색
                console.log("=== 컴포넌트 속성 탐색 시작 ===");

                // 컴포넌트 기본 메서드들 확인
                console.log("기본 메서드 확인:");
                console.log("- getID:", buttonComponent.getID ? buttonComponent.getID() : "없음");
                console.log("- getTagName:", buttonComponent.getTagName ? buttonComponent.getTagName() : "없음");

                // getStyle로 가져올 수 있는 모든 속성 시도
                console.log("getStyle 속성 탐색:");
                var styleProps = ["class", "className", "classList", "cssClass", "style", "css", "attr", "attribute"];
                for (var j = 0; j < styleProps.length; j++) {
                    try {
                        var propValue = buttonComponent.getStyle(styleProps[j]);
                        console.log("- getStyle('" + styleProps[j] + "'):", JSON.stringify(propValue));
                    } catch (e) {
                        console.log("- getStyle('" + styleProps[j] + "') 실패:", e.message);
                    }
                }

                // getAttribute 메서드 확인
                if (buttonComponent.getAttribute) {
                    console.log("getAttribute 메서드 탐색:");
                    var attrProps = ["class", "className", "classList"];
                    for (var k = 0; k < attrProps.length; k++) {
                        try {
                            var attrValue = buttonComponent.getAttribute(attrProps[k]);
                            console.log("- getAttribute('" + attrProps[k] + "'):", JSON.stringify(attrValue));
                        } catch (e) {
                            console.log("- getAttribute('" + attrProps[k] + "') 실패:", e.message);
                        }
                    }
                }

                // 컴포넌트 속성 직접 접근
                console.log("컴포넌트 속성 직접 접근:");
                console.log("- buttonComponent.class:", buttonComponent.class);
                console.log("- buttonComponent.className:", buttonComponent.className);
                console.log("- buttonComponent.classList:", buttonComponent.classList);
                console.log("- buttonComponent.style:", buttonComponent.style);

                // render 속성 확인
                if (buttonComponent.render) {
                    console.log("render 속성 확인:");
                    console.log("- render.className:", buttonComponent.render.className);
                    console.log("- render.class:", buttonComponent.render.class);
                    console.log("- render.classList:", buttonComponent.render.classList);

                    // DOM 클래스 기반으로 상태 업데이트
                    var currentClass = buttonComponent.render.className || "btn-tag";
                    console.log("현재 DOM 클래스:", currentClass);

                    // 클래스 업데이트 로직
                    var newClass = currentClass;
                    if (isSelected) {
                        if (currentClass.indexOf("active") === -1) {
                            newClass = currentClass + " active";
                        }
                    } else {
                        newClass = currentClass.replace(" active", "").replace("active", "").trim();
                        if (!newClass) newClass = "btn-tag";
                    }

                    console.log("새 클래스:", newClass);

                    // 클래스 업데이트 시도
                    try {
                        buttonComponent.render.className = newClass;
                        console.log("✅ DOM className 업데이트 성공");

                        // 검증
                        setTimeout(function () {
                            console.log("업데이트 후 확인:", buttonComponent.render.className);
                        }, 50);

                    } catch (updateError) {
                        console.error("❌ 클래스 업데이트 실패:", updateError);
                    }
                } else {
                    console.log("render 속성 없음");
                }

                console.log("=== 컴포넌트 속성 탐색 완료 ===");

            } else {
                console.warn("❌ WebSquare 컴포넌트를 찾을 수 없음:", tagButtons[i]);
            }

        } catch (error) {
            console.error("❌ 태그 버튼 UI 업데이트 중 치명적 오류:", tagButtons[i], error);
        }

        console.log("--- 버튼 " + (i + 1) + " 처리 완료 ---\n");
    }

    console.log("====== 태그 UI 업데이트 완료 ======");
};

