/**
 * 태스크가 선택된 태그들과 매칭되는지 확인
 */
scwin.isTaskMatchesTags = function (task, selectedTags) {
    var taskTags = task.tags;

    // 태그 필터가 없으면 모든 태스크 표시 (전체 선택 상태)
    if (!selectedTags || selectedTags.length === 0) {
        return true;
    }

    // 태스크에 태그가 없는 경우 처리
    if (!taskTags || taskTags.trim() === "") {
        // "untagged" 옵션이 선택되었거나, 모든 태그가 선택된 상태이면 표시
        var allTags = ["dev", "test", "doc", "plan", "analytics", "collabo", "untagged"];
        var isAllTagsSelected = allTags.every(function (tag) {
            return selectedTags.indexOf(tag) > -1;
        });
        return selectedTags.indexOf("untagged") > -1 || isAllTagsSelected;
    }

    // 태스크의 태그들을 배열로 변환
    var taskTagArray = taskTags.split(",");

    // 선택된 태그 중 하나라도 매칭되면 true (OR 조건)
    for (var i = 0; i < selectedTags.length; i++) {
        var selectedTag = selectedTags[i].trim();
        for (var j = 0; j < taskTagArray.length; j++) {
            if (taskTagArray[j].trim() === selectedTag) {
                return true;
            }
        }
    }

    return false;
};

/**
 * 필터링된 태스크들을 화면에 표시
 */
scwin.displayFilteredTasks = function (boardId, filteredTasks) {
    // 기존 카드들 제거
    scwin.clearBoardCards(boardId);

    // 필터링된 태스크들로 카드 생성
    for (var i = 0; i < filteredTasks.length; i++) {
        var task = filteredTasks[i];
        scwin.createKanbanCardInBoard(task);
    }

    // 카드 개수 업데이트
    scwin.updateBoardCardCount(boardId, filteredTasks.length);
};

/**
 * 보드의 기존 카드들 제거
 */
scwin.clearBoardCards = function (boardId) {
    var cardContainerId = "card_container_" + boardId;
    try {
        var cardContainer = eval(cardContainerId);
        if (cardContainer) {
            // 컨테이너의 모든 자식 카드들 제거
            var children = cardContainer.getChildren();
            for (var i = children.length - 1; i >= 0; i--) {
                children[i].remove();
            }
        }
    } catch (error) {
        console.error("보드 카드 제거 중 오류:", boardId, error);
    }
};

/**
 * 보드 카드 개수 업데이트
 */
scwin.updateBoardCardCount = function (boardId, count) {
    try {
        var countSpanId = "grp_dynamic_" + boardId + "_count";
        var countSpan = eval(countSpanId);
        if (countSpan) {
            countSpan.setValue(count);
        }
    } catch (error) {
        console.error("카드 개수 업데이트 실패:", boardId, error);
    }
};

/**
 * 전체 태스크 데이터 저장 (초기 로드 시 호출)
 */
scwin.storeAllTasksData = function (boardId, tasksArray) {
    scwin.allTasksData[boardId] = tasksArray || [];
    console.log("보드 " + boardId + " 전체 태스크 데이터 저장:", tasksArray.length + "개");
};

