/**
 * 정렬과 필터링을 모두 적용 (서버에서 정렬된 데이터 요청)
 */
scwin.applySortAndFilter = function () {
    console.log("������ 서버에서 정렬된 데이터 요청 시작");

    // 모든 보드에 대해 서버에서 정렬된 데이터 요청
    var boardList = $p.getComponentById("dlt_boardListVo");
    if (boardList && boardList.getRowCount() > 0) {
        console.log("������ 처리할 보드 개수:", boardList.getRowCount());

        for (var i = 0; i < boardList.getRowCount(); i++) {
            var boardId = boardList.getCellData(i, "boardId");
            var boardTitle = boardList.getCellData(i, "boardTitle");

            if (boardId) {
                console.log("������ 보드 " + boardId + " (" + boardTitle + ")에 대한 정렬된 데이터 요청");

                // 서버에 정렬 파라미터와 함께 요청
                scwin.loadTasksWithSort(boardId);
            }
        }
    } else {
        console.warn("⚠️ 보드 리스트가 없거나 비어있습니다");
    }

    console.log("✅ 모든 보드에 대한 정렬 데이터 요청 완료");
};

/**
 * 특정 보드에 대해 정렬된 태스크 데이터를 서버에서 로드
 */
scwin.loadTasksWithSort = function (boardId) {
    console.log("������ 보드 " + boardId + " 정렬된 데이터 요청 - sortField: " + scwin.currentSortField + ", sortOrder: " + scwin.currentSortOrder);

    // 검색 조건에 정렬 파라미터 추가
    dm_search_task.set("boardId", boardId);
    dm_search_task.set("sortField", scwin.currentSortField);
    dm_search_task.set("sortOrder", scwin.currentSortOrder);

    // 서버 요청 (기존 load_Tasks submission 사용)
    $p.executeSubmission("load_Tasks_With_UserName");
};

/**
 * 특정 보드의 태스크에 태그 필터링만 적용 (정렬은 서버에서 처리됨)
 */
scwin.sortAndFilterBoardTasks = function (boardId) {
    console.log("������ 보드 태그 필터링 시작:", boardId);

    // 해당 보드의 전체 태스크 데이터 가져오기 (이미 서버에서 정렬된 상태)
    var allTasks = scwin.allTasksData[boardId] || [];
    console.log("������ 보드 " + boardId + " 서버 정렬된 태스크:", allTasks.length + "개");

    // 원본 태스크 데이터가 없는 경우 경고
    if (allTasks.length === 0) {
        console.warn("⚠️ 보드 " + boardId + "에 대한 태스크 데이터가 없습니다!");
        console.warn("������ 전체 allTasksData:", scwin.allTasksData);
        // 빈 데이터라도 화면에 표시 (기존 카드 제거를 위해)
        scwin.displayFilteredTasks(boardId, []);
        return;
    }

    // 디버깅: 태스크 상세 정보 출력 (서버에서 이미 정렬된 상태)
    console.log("������ 보드 " + boardId + " 서버 정렬된 태스크 목록:");
    for (var idx = 0; idx < Math.min(allTasks.length, 3); idx++) {
        var task = allTasks[idx];
        console.log("  " + (idx + 1) + ". " + task.taskTitle + " (시작일: " + task.startDate + ", 종료일: " + task.endDate + ")");
    }
    if (allTasks.length > 3) {
        console.log("  ... 총 " + allTasks.length + "개 (서버에서 정렬됨)");
    }

    // 태그 필터링만 적용 (정렬은 이미 서버에서 처리됨)
    var filteredTasks = [];
    if (scwin.selectedTags.length === 0) {
        // 선택된 태그가 없으면 모든 태스크 표시 (서버 정렬 순서 유지)
        filteredTasks = allTasks;
        console.log("������️ 태그 필터 없음 - 서버 정렬된 모든 태스크 표시");
    } else {
        // 선택된 태그가 있으면 필터링 (서버 정렬 순서 유지)
        console.log("������️ 태그 필터링 적용:", scwin.selectedTags);
        for (var i = 0; i < allTasks.length; i++) {
            var task = allTasks[i];
            if (scwin.isTaskMatchesTags(task, scwin.selectedTags)) {
                filteredTasks.push(task);
            }
        }
        console.log("������️ 태그 필터링 결과:", filteredTasks.length + "개 (서버 정렬 순서 유지)");
    }

    console.log("✅ 보드 " + boardId + " 처리 완료: " + filteredTasks.length + "개 (서버 정렬 적용됨)");

    // 화면에 표시 (이미 서버에서 정렬된 데이터)
    scwin.displayFilteredTasks(boardId, filteredTasks);
};

