// 목록 보기 (간트차트) 버튼 클릭
scwin.list_onclick = async function (e) {
    console.log("List 버튼 클릭됨");

    // 게시판 숨기기
    var kanbanBoard = $p.getComponentById("grp_kanban_board");
    if (kanbanBoard) {
        kanbanBoard.hide();
    }

    // 캘린더 숨기기
    var calendarView = $p.getComponentById("grp_calendar_view");
    if (calendarView) {
        calendarView.hide();
    }

    // 간트차트 보이기 전 기존 객체 정리
    var ganttView = $p.getComponentById("grp_gantt_view");
    if (ganttView) {
        // 기존 FusionCharts 객체 확인
        try {
            if (gantt_chart && gantt_chart.fc()) {
                console.log("List 버튼 클릭 시 기존 간트차트 객체 재사용");
            }
        } catch (e) {
            console.log("간트차트 객체 상태 확인:", e);
        }

        ganttView.show();
    }

    // 메인 콘텐츠 overflow 설정 (간트차트: hidden)
    var mainContent = $p.getComponentById("mf_grp_mainContent");
    if (mainContent) {
        mainContent.setStyle("overflow", "hidden");
    }

    // 간트차트 월별 네비게이션 초기화
    scwin.initGanttNavigation();

    // 프로젝트 데이터 확인 후 간트차트 데이터 로딩
    var projectId = dm_projectVo.get("projectId");
    if (!projectId && (!scwin.currentProjectData || !scwin.currentProjectData.projectId)) {
        console.warn("프로젝트 데이터가 아직 로드되지 않았습니다. 간트차트 로딩을 지연합니다.");
        // 1초 후 재시도
        setTimeout(function () {
            // 간트 뷰가 여전히 보이는 경우에만 데이터 로드
            try {
                var isVisible = false;
                if (grp_gantt_view) {
                    if (typeof grp_gantt_view.isVisible === 'function') {
                        isVisible = grp_gantt_view.isVisible();
                    } else {
                        // 안전한 fallback - 항상 로드
                        isVisible = true;
                    }
                }
                if (isVisible) {
                    scwin.loadGanttData();
                }
            } catch (error) {
                console.error("간트차트 가시성 확인 중 오류:", error);
                // 오류 발생 시 안전하게 데이터 로드
                scwin.loadGanttData();
            }
        }, 1000);
    } else {
        // 칸반에서 최신 태스크 데이터가 있는지 확인
        console.log("간트차트 뷰 전환: 최신 태스크 데이터 확인 중...");
        if (scwin.taskList && scwin.taskList.length > 0) {
            console.log("기존 칸반 데이터를 사용하여 간트차트 업데이트");
            scwin.loadGanttData();
        } else {
            console.log("태스크 데이터가 없습니다. 태스크 데이터를 먼저 로드합니다.");
            // 태스크 데이터가 없으면 먼저 로드 (async/await 패턴 사용)
            try {
                if (typeof scwin.loadTasksWithUserNameAsync === 'function') {
                    console.log("비동기 태스크 로드 시작...");
                    await scwin.loadTasksWithUserNameAsync();
                    console.log("태스크 로드 완료, 간트차트 데이터 로드 시작...");

                    // 간트 뷰 가시성을 안전하게 확인
                    try {
                        var isVisible = false;
                        if (grp_gantt_view) {
                            if (typeof grp_gantt_view.isVisible === 'function') {
                                isVisible = grp_gantt_view.isVisible();
                            } else {
                                // 안전한 fallback - 항상 로드
                                isVisible = true;
                            }
                        }
                        if (isVisible) {
                            scwin.loadGanttData();
                        }
                    } catch (error) {
                        console.error("간트차트 가시성 확인 중 오류:", error);
                        // 오류 발생 시 안전하게 데이터 로드
                        scwin.loadGanttData();
                    }
                } else {
                    // fallback: 기존 방식 사용
                    console.warn("비동기 태스크 로드 함수가 없습니다. 기존 방식을 사용합니다.");
                    if (typeof scwin.loadTasksWithUserName === 'function') {
                        scwin.loadTasksWithUserName();
                        // 태스크 로드 완료 후 간트차트 로드 (비동기)
                        setTimeout(function () {
                            // 간트 뷰 가시성을 안전하게 확인
                            try {
                                var isVisible = false;
                                if (grp_gantt_view) {
                                    if (typeof grp_gantt_view.isVisible === 'function') {
                                        isVisible = grp_gantt_view.isVisible();
                                    } else {
                                        // 안전한 fallback - 항상 로드
                                        isVisible = true;
                                    }
                                }
                                if (isVisible) {
                                    scwin.loadGanttData();
                                }
                            } catch (error) {
                                console.error("간트차트 가시성 확인 중 오류:", error);
                                // 오류 발생 시 안전하게 데이터 로드
                                scwin.loadGanttData();
                            }
                        }, 1000);
                    } else {
                        // 기본 간트차트 데이터 로딩
                        scwin.loadGanttData();
                    }
                }
            } catch (error) {
                console.error("비동기 태스크 로드 중 오류:", error);
                console.log("오류 발생으로 인해 기본 간트차트 데이터를 로드합니다.");
                scwin.loadGanttData();
            }
        }
    }
};

// 캘린더 보기 버튼 클릭
