/**
 * 태스크 데이터를 캘린더 형식으로 변환하여 로드
 */
scwin.loadTasksToCalendar = function () {
    console.log("태스크 데이터를 캘린더로 변환 시작");

    // 캘린더 데이터 리스트 초기화
    var calendarDataList = $p.getComponentById("dlt_calendar_schedule");
    if (!calendarDataList) {
        console.error("dlt_calendar_schedule 컴포넌트를 찾을 수 없습니다.");
        return;
    }

    // 기존 데이터 모두 제거
    calendarDataList.removeAll();

    // 현재 allTasksData 상태 확인
    console.log("현재 allTasksData:", scwin.allTasksData);

    // 모든 보드의 태스크 데이터를 수집
    var allTasks = [];
    if (scwin.allTasksData) {
        for (var boardId in scwin.allTasksData) {
            if (scwin.allTasksData.hasOwnProperty(boardId)) {
                var boardTasks = scwin.allTasksData[boardId];
                console.log("보드 " + boardId + "의 태스크:", boardTasks);
                if (boardTasks && boardTasks.length > 0) {
                    allTasks = allTasks.concat(boardTasks);
                }
            }
        }
    } else {
        console.warn("allTasksData가 없습니다. 대체 방법으로 dlt_scwin.taskList에서 데이터를 가져옵니다.");

        // 대체 방법: dlt_scwin.taskList에서 직접 데이터 가져오기
        scwin.taskList = $p.getComponentById("dlt_scwin.taskList");
        if (scwin.taskList) {
            var taskData = scwin.taskList.getAllJSON();
            console.log("dlt_scwin.taskList에서 가져온 데이터:", taskData);
            if (taskData && taskData.length > 0) {
                allTasks = taskData;
            }
        }
    }

    console.log("캘린더에 표시할 총 태스크 수:", allTasks.length);

    // 태스크 데이터 샘플 출력
    if (allTasks.length > 0) {
        console.log("첫 번째 태스크 샘플:", allTasks[0]);
    }

    // 태스크 데이터를 캘린더 형식으로 변환
    for (var i = 0; i < allTasks.length; i++) {
        var task = allTasks[i];

        console.log("태스크 " + (i + 1) + ":", {
            taskId: task.taskId,
            taskTitle: task.taskTitle,
            startDate: task.startDate,
            endDate: task.endDate,
            boardId: task.boardId
        });

        // 시작일이 있는 태스크만 캘린더에 표시 (종료일이 없으면 시작일과 같게)
        if (task.startDate) {
            var startDate = scwin.formatDateForCalendar(task.startDate);
            var endDate = task.endDate ? scwin.formatDateForCalendar(task.endDate) : startDate;
            var scheduleData = {
                id: task.taskId,
                title: task.taskTitle || "제목 없음",
                start: startDate,
                end: endDate,
                boardId: task.boardId,
                boardTitle: scwin.getBoardTitle(task.boardId),
                priority: task.priority || "normal",
                tags: task.tags || ""
            };

            // 순서대로 다양한 색상 적용 (우선순위/보드 구분 없이)
            var colors = [
                "#FF6B6B", "#4ECDC4", "#45B7D1", "#96CEB4", "#FFEAA7", "#DDA0DD", 
                "#98D8C8", "#F7DC6F", "#FF8A65", "#81C784", "#64B5F6", "#FFB74D", 
                "#BA68C8", "#4DB6AC", "#A1C181", "#F48FB1"
            ];
            var colorIndex = i % colors.length;
            var backgroundColor = colors[colorIndex];

            // themeColumn에 사용할 JSON 데이터 생성
            var themeData = {
                "backgroundColor": backgroundColor,
                "borderColor": backgroundColor,
                "textColor": "#FFFFFF"
            };
            var themeJson = JSON.stringify(themeData);

            console.log("캘린더에 추가할 일정:", scheduleData, "테마:", themeJson);

            // 캘린더 데이터 리스트에 추가
            calendarDataList.insertRow();
            var newRowIndex = calendarDataList.getRowCount() - 1;

            calendarDataList.setCellData(newRowIndex, "id", scheduleData.id);
            calendarDataList.setCellData(newRowIndex, "title", scheduleData.title);
            calendarDataList.setCellData(newRowIndex, "start", scheduleData.start);
            calendarDataList.setCellData(newRowIndex, "end", scheduleData.end);
            calendarDataList.setCellData(newRowIndex, "boardId", scheduleData.boardId);
            calendarDataList.setCellData(newRowIndex, "boardTitle", scheduleData.boardTitle);
            calendarDataList.setCellData(newRowIndex, "priority", scheduleData.priority);
            calendarDataList.setCellData(newRowIndex, "tags", scheduleData.tags);
            calendarDataList.setCellData(newRowIndex, "theme", themeJson);

            console.log("캘린더에 태스크 추가:", scheduleData.title, scheduleData.start, "~", scheduleData.end, "색상:", backgroundColor);
        }
    }

    console.log("캘린더 데이터 로드 완료:", calendarDataList.getRowCount() + "개 일정");

    // 캘린더 컴포넌트 새로고침
    var calendarComponent = $p.getComponentById("calendar_schedule");
    if (calendarComponent && calendarComponent.refresh) {
        calendarComponent.refresh();
    }
};

/**
 * 날짜 형식을 캘린더에 맞게 변환 (YYYYMMDD 형식)
 * @param {String} dateString - 변환할 날짜 문자열
 * @returns {String} 변환된 날짜 문자열 (YYYYMMDD 형식)
 */
scwin.formatDateForCalendar = function (dateString) {
    if (!dateString) return "";

    // 날짜 형식이 이미 YYYYMMDD 형태인지 확인
    if (dateString.match(/^\d{8}$/)) {
        return dateString;
    }

    // 다른 형식의 날짜를 YYYYMMDD로 변환
    try {
        var date;

        // YYYY-MM-DD 형식인 경우
        if (dateString.match(/^\d{4}-\d{2}-\d{2}$/)) {
            date = new Date(dateString);
        } else {
            date = new Date(dateString);
        }

        if (isNaN(date.getTime())) {
            console.warn("유효하지 않은 날짜 형식:", dateString);
            return dateString;
        }

        var year = date.getFullYear();
        var month = String(date.getMonth() + 1).padStart(2, '0');
        var day = String(date.getDate()).padStart(2, '0');

        return year + month + day; // YYYYMMDD 형식
    } catch (error) {
        console.error("날짜 변환 중 오류:", dateString, error);
        return dateString;
    }
};

/**
 * 태스크 데이터를 간트차트로 변환하여 로드 (모든 태스크 row 표시, 해당 월 그래프만 표시)
 */
scwin.loadTasksToGantt = function (allTasks, displayYear, displayMonth) {
    console.log("태스크 데이터를 간트차트로 변환 시작");
    console.log("표시할 년/월:", displayYear + "년 " + displayMonth + "월");

    if (!gantt_chart) {
        console.error("gantt_chart 컴포넌트를 찾을 수 없습니다.");
        return;
    }

    // 기존 FusionCharts 객체 확인 (중복 방지)
    try {
        var existingChart = gantt_chart.fc();
        if (existingChart) {
            console.log("기존 간트차트 객체가 존재합니다. 재사용합니다.");
            // 기존 객체 정리하지 않고 재사용
        }
    } catch (e) {
        console.log("새로운 간트차트 객체를 생성합니다.");
    }

    // 간트차트 데이터 리스트에서 태스크 데이터 가져오기
    // 기존 차트 초기화 (간트차트.txt 권장 방법)
    try {
        console.log("간트차트 초기화 시작");
        // clear() 메소드는 공식 문서에 없으므로 setJSONData로 초기화
    } catch (e) {
        console.log("간트차트 초기화 중 오류 (무시 가능):", e.message);
    }

    // 전달받은 전체 태스크 또는 dlt_gantt_schedule에서 가져오기
    var ganttTasks = allTasks || dlt_gantt_schedule.getAllJSON();
    console.log("=== 간트차트 데이터 검증 ===");
    console.log("표시할 전체 태스크 개수:", ganttTasks ? ganttTasks.length : 0);
    console.log("실제 데이터:", ganttTasks);

    if (!ganttTasks || ganttTasks.length === 0) {
        console.log("표시할 태스크가 없습니다. 전체 taskList 확인 중...");

        // 전체 scwin.taskList를 사용
        if (!scwin.taskList || scwin.taskList.length === 0) {
            console.warn("scwin.taskList도 없습니다.");
            // 빈 배열로 설정하여 더미 데이터가 생성되도록 함
            ganttTasks = [];
        } else {
            // 전체 taskList 데이터를 사용 (모든 태스크 표시)
            ganttTasks = scwin.taskList.filter(function (task) {
                return task.startDate && task.endDate &&
                    task.startDate.trim() !== "" && task.endDate.trim() !== "";
            });

            console.log("전체 taskList에서 유효한 태스크:", ganttTasks.length + "개");
        }
    }

    console.log("=== 로드할 태스크 " + ganttTasks.length + "개 ===");

    // 태스크 개수에 따른 동적 높이 조절 (row 높이 2배 증가)
    var taskCount = ganttTasks.length;
    var baseHeight = 150;  // 기본 높이 증가 (100 → 150)
    var taskHeight = 30;   // 태스크당 추가 높이 2배 (15 → 30)  
    var minHeight = 120;   // 최소 높이 증가 (80 → 120)
    var maxHeight = 600;   // 최대 높이 2배 (300 → 600)

    var dynamicHeight = Math.max(minHeight, baseHeight + (taskCount * taskHeight));

    console.log("동적 높이 조절 (1/3 크기): " + taskCount + "개 태스크 → " + dynamicHeight + "px");

    try {
        // width는 원래대로 90% 유지, height만 동적 조절
        gantt_chart.setStyle("height", dynamicHeight + "px");
        console.log("간트차트 높이 설정 완료: " + dynamicHeight + "px");
    } catch (sizeError) {
        console.log("크기 설정 오류:", sizeError);
    }

    // 간트차트.txt 방식으로 데이터 설정
    console.log("간트차트 JSON 데이터 설정 시작");

    // 1. 기본 차트 속성 설정 (간트차트.txt 형식)
    var chartOptions = {
        caption: "",  // 제목 제거
        dateformat: "mm/dd/yyyy",
        outputdateformat: "mm/dd/yyyy",


        showTaskNames: "1",
        showTaskLabels: "0",
        showConnectors: "0",
        taskBarFillMix: "",
        taskBarFillRatio: "",
        // 전역 그림자 효과 제거
        showBorder: "1",
        borderThickness: "1",

        showShadow: "0",
        dropShadow: "0"
    };
    gantt_chart.setChartAttribute(chartOptions);

    // 2. 카테고리 설정 (해당 월의 일별 카테고리만 표시)
    var currentDate = new Date();
    var currentYear = displayYear || scwin.currentGanttYear || currentDate.getFullYear();
    var currentMonth = displayMonth || scwin.currentGanttMonth || (currentDate.getMonth() + 1);

    var categoryData = scwin.createMonthlyCategories(currentYear, currentMonth);
    if (categoryData) {
        console.log("해당 월 카테고리 설정:", currentYear + "년 " + currentMonth + "월");
        gantt_chart.setCategories(categoryData);
        console.log(gantt_chart.getJSONData());
    }

    // 3. processes와 tasks 데이터 생성 (년/월 정보 전달)
    var ganttJSONData = scwin.createGanttJSONFromDataList_backup(ganttTasks, currentYear, currentMonth);

    // 4. JSON 데이터 설정
    if (ganttJSONData) {
        console.log("간트차트 JSON 데이터:", ganttJSONData);
        gantt_chart.setJSONData(ganttJSONData);
    }

    // 5. 색상 설정은 일단 건너뛰기 (processes 표시 테스트)
    console.log("색상 설정 건너뛰기 - processes 표시 우선 테스트");

    // 6. 간트차트 그리기
    console.log("간트차트 그리기 시작");
    gantt_chart.draw();

    // 최종적으로 차트 강제 다시 그리기
    try {
        if (typeof gantt_chart.draw === 'function') {
            gantt_chart.draw();
            console.log("간트차트 최종 다시 그리기 완료");
        }
    } catch (drawError) {
        console.log("최종 차트 다시 그리기 오류:", drawError);
    }

    console.log("간트차트 표시 완료");
};


/**
 * 특정 월의 카테고리만 생성
 */
scwin.createMonthlyCategories = function (year, month) {
    var firstDay = new Date(year, month - 1, 1);
    var lastDay = new Date(year, month, 0);
    var totalDays = lastDay.getDate(); // 해당 월의 총 일수

    var dailyCategories = [];

    // FusionCharts가 인덱스 1부터 그리는 문제 해결을 위해 빈 칸 2개 추가
    // 첫 번째 빈 칸 (인덱스 0)
    // dailyCategories.push({
    //     start: "",
    //     end: "",
    //     label: ""
    // });

    // // 두 번째 빈 칸 (인덱스 1) - FusionCharts 오프셋 보정용
    // dailyCategories.push({
    //     start: "07/01/2025",
    //     end: "07/01/2025",
    //     label: "0"
    // });

    // 1부터 총일수까지 실제 날짜 카테고리 생성
    for (var day = 0; day <= totalDays; day++) {
        var currentDate = new Date(year, month - 1, day); // 실제 날짜

        dailyCategories.push({
            start: scwin.formatDate(currentDate),
            end: scwin.formatDate(currentDate),
            label: day.toString() // 라벨은 실제 날짜 (1, 2, 3, ..., 31)
        });
    }

    console.log(year + "년 " + month + "월 일별 카테고리 생성:", totalDays + "일");
    console.log("첫 번째 카테고리 (빈 칸 0):", dailyCategories[0]);
    console.log("두 번째 카테고리 (빈 칸 1):", dailyCategories[1]);
    console.log("세 번째 카테고리 (1일):", dailyCategories[2]);
    console.log("네 번째 카테고리 (2일):", dailyCategories[3]);
    console.log("마지막 카테고리:", dailyCategories[dailyCategories.length - 1]);
    console.log("총 카테고리 개수:", dailyCategories.length);
    console.log("예상 개수:", totalDays + 2, "(빈 칸 2개 + 실제 날짜", totalDays + "개)");

    return { category: dailyCategories };
};

/**
 * 간트차트용 월별 + 일별 카테고리 생성 (2단계 카테고리)
 */
scwin.createGanttCategories = function (tasks) {
    if (!tasks || tasks.length === 0) {
        return null;
    }

    console.log("=== 태스크 기반 간트차트 카테고리 생성 ===");
    console.log("입력 태스크 개수:", tasks.length);

    // 모든 태스크의 날짜 범위 수집
    var allDates = [];
    tasks.forEach(function (task) {
        if (task.startDate) allDates.push(new Date(task.startDate));
        if (task.endDate) allDates.push(new Date(task.endDate));
    });

    if (allDates.length === 0) {
        console.log("유효한 날짜를 가진 태스크가 없습니다.");
        return null;
    }

    // 최소, 최대 날짜 구하기
    var minDate = new Date(Math.min.apply(null, allDates));
    var maxDate = new Date(Math.max.apply(null, allDates));

    console.log("날짜 범위:", minDate.toDateString(), "~", maxDate.toDateString());

    // 주차별 카테고리 생성 (더 간단한 표시)
    var categories = [];
    var currentDate = new Date(minDate);

    // 시작일부터 종료일까지 주 단위로 카테고리 생성
    while (currentDate <= maxDate) {
        var weekStart = new Date(currentDate);
        var weekEnd = new Date(currentDate);
        weekEnd.setDate(weekEnd.getDate() + 6); // 7일 후

        // 마지막 주는 최대 날짜로 제한
        if (weekEnd > maxDate) {
            weekEnd = new Date(maxDate);
        }

        categories.push({
            start: scwin.formatToMMDDYYYY(weekStart),
            end: scwin.formatToMMDDYYYY(weekEnd),
            label: (weekStart.getMonth() + 1) + "/" + weekStart.getDate() +
                " ~ " + (weekEnd.getMonth() + 1) + "/" + weekEnd.getDate()
        });

        currentDate.setDate(currentDate.getDate() + 7); // 다음 주로
    }

    console.log("생성된 카테고리 개수:", categories.length);
    console.log("카테고리 목록:", categories);

    return { category: categories };
};

