/**
 * DataList에서 간트차트 JSON 데이터 생성 (모든 태스크 row 표시, 해당 월 그래프만 표시) - 백업용
 */
scwin.createGanttJSONFromDataList_backup = function (ganttTasks, displayYear, displayMonth) {
    if (!ganttTasks || ganttTasks.length === 0) {
        console.log("데이터가 없어서 더미 간트차트 데이터를 생성합니다.");
        // 작고 투명한 더미 데이터 생성
        return scwin.createDummyGanttData(displayYear, displayMonth);
    }

    var processes = [];
    var tasks = [];

    // 해당 월의 시작일과 종료일 계산
    var monthStart = null;
    var monthEnd = null;
    if (displayYear && displayMonth) {
        monthStart = new Date(displayYear, displayMonth - 1, 1);
        monthEnd = new Date(displayYear, displayMonth, 0);
        console.log("표시할 월 범위:", monthStart.toDateString(), "~", monthEnd.toDateString());
    }

    // processes와 tasks 데이터 생성
    ganttTasks.forEach(function (task, index) {
        // processes (왼쪽 태스크 목록) - 모든 태스크를 row로 표시
        processes.push({
            id: task.taskId,
            label: task.taskTitle
        });

        // tasks (간트 바) - 해당 월과 겹치는 태스크만 표시
        var taskStartDate = scwin.parseValidDate(task.startDate);
        var taskEndDate = scwin.parseValidDate(task.endDate);

        // 유효하지 않은 날짜인 경우 해당 태스크는 그래프에 표시하지 않음 (processes에는 이미 추가됨)
        if (!taskStartDate || !taskEndDate) {
            console.warn("유효하지 않은 날짜 데이터:", task.taskId, task.startDate, task.endDate);
            return; // forEach의 현재 반복만 건너뛰기
        }

        var shouldShowTask = true;
        var actualStartDate = taskStartDate;
        var actualEndDate = taskEndDate;

        if (monthStart && monthEnd) {
            // 태스크가 해당 월과 겹치는지 확인
            if (taskEndDate < monthStart || taskStartDate > monthEnd) {
                // 해당 월과 전혀 겹치지 않으면 태스크 바를 표시하지 않음
                shouldShowTask = false;
            } else {
                // 해당 월과 겹치는 부분만 표시하도록 날짜 조정
                if (taskStartDate < monthStart) {
                    actualStartDate = monthStart;
                }
                if (taskEndDate > monthEnd) {
                    actualEndDate = monthEnd;
                }
            }
        }

        if (shouldShowTask) {
            // 1칸씩 밀리는 문제 해결: 시작일만 1일 앞당기고 종료일은 원래대로 유지
            var adjustedStartDate = new Date(actualStartDate.getTime() - 24 * 60 * 60 * 1000);
            var adjustedEndDate = actualEndDate;  // 종료일은 원래대로 유지

            // hover 툴팁에 표시할 원래 날짜 정보
            var originalStartStr = scwin.convertToMMDDYYYY(actualStartDate);
            var originalEndStr = scwin.convertToMMDDYYYY(actualEndDate);
            var tooltipText = task.taskTitle + "<br/>기간: " + originalStartStr + " ~ " + originalEndStr;

            tasks.push({
                id: task.taskId,
                start: scwin.convertToMMDDYYYY(adjustedStartDate),
                end: scwin.convertToMMDDYYYY(adjustedEndDate),
                processid: task.taskId,
                label: "",  // 라벨 숨기기
                color: scwin.getTaskColorByIndex(index),  // 인덱스별 다른 색상
                tooltext: tooltipText,  // 커스텀 툴팁
                // 테두리 완전 투명하게 설정
                borderThickness: "0",
                borderAlpha: "0"
            });
        }
    });

    console.log("생성된 processes:", processes.length + "개 (모든 태스크)");
    console.log("processes 데이터:", processes);
    console.log("생성된 tasks:", tasks.length + "개 (해당 월 표시 태스크)");
    console.log("tasks 데이터:", tasks);

    // 더미 태스크 제거 - processes만으로 표시 테스트
    console.log("더미 태스크 없이 processes만 표시 테스트");

    // 간단한 간트차트 구조로 반환
    return {
        chart: {
            caption: "프로젝트 일정",
            dateformat: "mm/dd/yyyy",
            showprocessname: "1",
            ganttrowheight: "40"
        },
        processes: {
            process: processes
        },
        tasks: {
            task: tasks.length > 0 ? tasks : scwin.createDummyTasksForProcesses(processes, displayYear, displayMonth)
        }
    };
};

/**
 * processes가 있지만 tasks가 없을 때 더미 tasks 생성
 */
scwin.createDummyTasksForProcesses = function (processes, displayYear, displayMonth) {
    var currentDate = new Date();
    var year = displayYear || currentDate.getFullYear();
    var month = displayMonth || (currentDate.getMonth() + 1);

    console.log("processes가 있지만 tasks가 없어서 더미 tasks 생성:", year + "년 " + month + "월");

    var dummyTasks = [];

    // 날짜 매핑 테스트를 위한 여러 개의 더미 태스크 생성
    if (processes.length > 0) {
        var process = processes[0];

        // 1일짜리 태스크들로 각 날짜별 매핑 테스트
        var testDates = [1, 5, 10, 15, 20, 25];

        for (var i = 0; i < testDates.length && i < 3; i++) { // 최대 3개만
            var testDay = testDates[i];
            // 1칸씩 밀리는 문제 해결: 날짜를 1일 앞당겨서 생성
            var testDate = new Date(year, month - 1, testDay - 1);
            // 사용자가 의도한 원래 날짜
            var intentedDate = new Date(year, month - 1, testDay);

            dummyTasks.push({
                id: "test_mapping_" + testDay,
                processid: process.id,
                start: scwin.formatDate(testDate),
                end: scwin.formatDate(testDate),
                label: "",  // 빈 라벨
                color: "FFFFFF",  // 흰색
                alpha: "0",  // 완전 투명
                fontcolor: "FFFFFF",  // 흰색 글자
                fontsize: "1",  // 최소 글자 크기
                showlabel: "0",  // 라벨 숨김
                // 테두리 완전 투명하게 설정
                borderThickness: "0",
                borderColor: "FFFFFF", 
                borderAlpha: "0",
                // 그림자 효과 제거
                shadow: "0",
                // 추가 투명도 설정
                fillalpha: "0",
                // 호버 효과 제거
                showHoverEffect: "0"
            });

            console.log("������ 날짜 매핑 테스트 - " + testDay + "일 위치에 표시하기 위해");
            console.log("    실제 생성 날짜:", scwin.formatDate(testDate));
        }
    }

    console.log("생성된 더미 tasks:", dummyTasks.length + "개");
    return dummyTasks;
};

