/**
 * 태스크 우선순위별 색상 반환 (로그아웃 버튼 색상으로 통일)
 */
/**
 * 인덱스별 다른 색상 반환 (각 태스크마다 다른 색상)
 */
scwin.getTaskColorByIndex = function (index) {
    var colors = [
        "#FF6B6B",  // 빨간색
        "#4ECDC4",  // 청록색  
        "#45B7D1",  // 파란색
        "#96CEB4",  // 초록색
        "#FFEAA7",  // 노란색
        "#DDA0DD",  // 자주색
        "#98D8C8",  // 민트색
        "#F7DC6F",  // 황금색
        "#FF8A65",  // 주황색
        "#81C784",  // 연한 초록색
        "#64B5F6",  // 연한 파란색
        "#FFB74D",  // 연한 주황색
        "#BA68C8",  // 연한 자주색
        "#4DB6AC",  // 청록색
        "#A1C181",  // 올리브색
        "#F48FB1"   // 핑크색
    ];

    return colors[index % colors.length];
};

scwin.getTaskColorByPriority = function (priority) {
    // 우선순위별 동적 색상 반환
    switch (priority) {
        case "HIGH":
            return "#FF6B6B";  // 빨간색 (고우선순위)
        case "MEDIUM":
            return "#4ECDC4";  // 청록색 (중우선순위)
        case "LOW":
            return "#95E1D3";  // 연한 청록색 (저우선순위)
        default:
            return "#A8E6CF";  // 기본 연한 초록색
    }
};

/**
 * 보드별 색상 반환 (대안 색상 스키마)
 */
scwin.getTaskColorByBoard = function (boardId) {
    var colors = [
        "#FF6B6B",  // 빨간색
        "#4ECDC4",  // 청록색  
        "#45B7D1",  // 파란색
        "#96CEB4",  // 초록색
        "#FFEAA7",  // 노란색
        "#DDA0DD",  // 자주색
        "#98D8C8",  // 민트색
        "#F7DC6F"   // 황금색
    ];

    // 보드 ID를 기반으로 색상 인덱스 계산
    var colorIndex = parseInt(boardId) % colors.length;
    return colors[colorIndex];
};

/**
 * yyyy-mm-dd 형식 또는 Date 객체를 mm/dd/yyyy 형식으로 변환 (간트차트.txt 형식)
 */
/**
 * 안전한 날짜 파싱 함수
 */
scwin.parseValidDate = function (dateInput) {
    if (!dateInput) {
        return null;
    }

    try {
        var dateString = dateInput.toString().trim();
        if (dateString === "" || dateString === "null" || dateString === "undefined") {
            return null;
        }

        var parsedDate = new Date(dateString);

        // 유효한 날짜인지 확인
        if (isNaN(parsedDate.getTime())) {
            console.warn("유효하지 않은 날짜:", dateInput);
            return null;
        }

        return parsedDate;
    } catch (e) {
        console.error("날짜 파싱 오류:", dateInput, e);
        return null;
    }
};

scwin.convertToMMDDYYYY = function (dateInput) {
    if (!dateInput) {
        return "";
    }

    try {
        // Date 객체인 경우
        if (dateInput instanceof Date) {
            // 유효한 Date 객체인지 확인
            if (isNaN(dateInput.getTime())) {
                return "";
            }
            var month = (dateInput.getMonth() + 1).toString().padStart(2, '0');
            var day = dateInput.getDate().toString().padStart(2, '0');
            var year = dateInput.getFullYear();
            return month + "/" + day + "/" + year;
        }

        // 문자열인 경우
        var dateString = dateInput.toString();
        if (dateString.trim() === "") {
            return "";
        }

        // yyyy-mm-dd -> mm/dd/yyyy 변환
        var parts = dateString.split("-");
        if (parts.length === 3) {
            var year = parts[0];
            var month = parts[1];
            var day = parts[2];
            return month + "/" + day + "/" + year;
        }
        return dateString;
    } catch (e) {
        console.error("날짜 변환 오류:", dateInput, e);
        return "";
    }
};

/**
 * Date 객체를 mm/dd/yyyy 형식으로 변환
 */
scwin.formatToMMDDYYYY = function (date) {
    var month = (date.getMonth() + 1).toString().padStart(2, '0');
    var day = date.getDate().toString().padStart(2, '0');
    var year = date.getFullYear();
    return month + "/" + day + "/" + year;
};

/**
 * 간트차트 월별 네비게이션 초기화
 */
scwin.initGanttNavigation = function () {
    // 현재 날짜로 동적 초기화
    var currentDate = new Date();
    scwin.currentGanttYear = currentDate.getFullYear();
    scwin.currentGanttMonth = currentDate.getMonth() + 1;

    // 레이블 업데이트
    scwin.updateGanttMonthLabel();

    console.log("간트차트 네비게이션 초기화:", scwin.currentGanttYear + "년 " + scwin.currentGanttMonth + "월");
};

/**
 * 간트차트 월 레이블 업데이트
 */
scwin.updateGanttMonthLabel = function () {
    var monthNames = ["1월", "2월", "3월", "4월", "5월", "6월",
        "7월", "8월", "9월", "10월", "11월", "12월"];

    var labelText = scwin.currentGanttYear + "년 " + monthNames[scwin.currentGanttMonth - 1];

    // 레이블 컴포넌트 업데이트
    var monthLabel = $p.getComponentById("lbl_gantt_current_month");
    if (monthLabel) {
        monthLabel.setValue(labelText);
    }

    console.log("간트차트 월 레이블 업데이트:", labelText);
};

/**
 * 이전 월로 이동
 */
scwin.moveToPreviousMonth = function () {
    if (scwin.currentGanttMonth > 1) {
        scwin.currentGanttMonth--;
    } else {
        scwin.currentGanttMonth = 12;
        scwin.currentGanttYear--;
    }

    console.log("이전 월로 이동:", scwin.currentGanttYear + "년 " + scwin.currentGanttMonth + "월");

    // 레이블 업데이트
    scwin.updateGanttMonthLabel();

    // 간트차트 새로고침
    scwin.refreshGanttChart();
};

/**
 * 다음 월로 이동
 */
scwin.moveToNextMonth = function () {
    if (scwin.currentGanttMonth < 12) {
        scwin.currentGanttMonth++;
    } else {
        scwin.currentGanttMonth = 1;
        scwin.currentGanttYear++;
    }

    console.log("다음 월로 이동:", scwin.currentGanttYear + "년 " + scwin.currentGanttMonth + "월");

    // 레이블 업데이트
    scwin.updateGanttMonthLabel();

    // 간트차트 새로고침
    scwin.refreshGanttChart();
};

/**
 * 간트차트 새로고침 (월 변경 시)
 */
scwin.refreshGanttChart = function () {
    console.log("간트차트 새로고침 시작");

    // 전체 scwin.taskList 확인
    if (!scwin.taskList || scwin.taskList.length === 0) {
        console.warn("scwin.taskList가 없습니다.");
        return;
    }

    console.log("전체 taskList:", scwin.taskList.length + "개");

    // 간트차트 데이터 리스트를 전체 태스크로 구성 (모든 태스크를 row로 표시)
    dlt_gantt_schedule.removeAll();

    for (var i = 0; i < scwin.taskList.length; i++) {
        var task = scwin.taskList[i];

        // 시작일과 종료일이 있는 태스크만 추가 (모든 태스크를 row로 표시)
        if (task.startDate && task.endDate &&
            task.startDate.trim() !== "" && task.endDate.trim() !== "") {

            dlt_gantt_schedule.insertRow(i);
            dlt_gantt_schedule.setCellData(i, "taskId", task.taskId);
            dlt_gantt_schedule.setCellData(i, "taskTitle", task.taskTitle);
            dlt_gantt_schedule.setCellData(i, "startDate", task.startDate);
            dlt_gantt_schedule.setCellData(i, "endDate", task.endDate);
            dlt_gantt_schedule.setCellData(i, "boardId", task.boardId);
            dlt_gantt_schedule.setCellData(i, "boardTitle", task.boardTitle || "보드");
            dlt_gantt_schedule.setCellData(i, "priority", task.priority || "MEDIUM");
            dlt_gantt_schedule.setCellData(i, "tags", task.tags || "");
        }
    }

    console.log("dlt_gantt_schedule 업데이트 완료 (전체 태스크):", dlt_gantt_schedule.getRowCount() + "개");

    // 해당 월의 카테고리 업데이트 (그래프는 해당 월 부분만 표시)
    var categoryData = scwin.createMonthlyCategories(scwin.currentGanttYear, scwin.currentGanttMonth);
    if (categoryData) {
        console.log("월별 카테고리 업데이트:", scwin.currentGanttYear + "년 " + scwin.currentGanttMonth + "월");
        gantt_chart.setCategories(categoryData);
    }

    // 간트차트 다시 그리기 (전체 태스크로 호출하되, 카테고리는 해당 월만)
    scwin.loadTasksToGantt(scwin.taskList, scwin.currentGanttYear, scwin.currentGanttMonth);
};

/**
 * 특정 월의 태스크만 필터링
 */
scwin.filterTasksByMonth = function (tasks, year, month) {
    return tasks.filter(function (task) {
        if (!task.startDate && !task.endDate) {
            return false;
        }

        var taskStartDate = new Date(task.startDate);
        var taskEndDate = new Date(task.endDate);

        var monthStart = new Date(year, month - 1, 1);
        var monthEnd = new Date(year, month, 0);

        // 태스크가 해당 월과 겹치는지 확인
        return (taskStartDate <= monthEnd && taskEndDate >= monthStart);
    });
};

/**
 * 칸반 데이터 업데이트 후 간트차트 동기화 함수
 * 현재 간트차트 뷰가 활성화되어 있을 때만 간트차트를 업데이트
 */
scwin.syncGanttWithKanban = function () {
    console.log("칸반-간트차트 동기화 함수 호출");

    // 간트차트 뷰가 현재 활성화되어 있는지 확인
    var ganttView = $p.getComponentById("grp_gantt_view");
    if (!ganttView) {
        console.log("간트차트 뷰 컴포넌트를 찾을 수 없습니다.");
        return;
    }

    // 간트차트 뷰가 보이는 상태인지 안전하게 확인
    try {
        // WebSquare 컴포넌트에서 가시성을 확인하는 안전한 방법들
        var isGanttVisible = false;

        // 방법 1: isVisible() 메소드 시도
        if (typeof ganttView.isVisible === 'function') {
            isGanttVisible = ganttView.isVisible();
        }
        // 방법 2: DOM 스타일 확인
        else if (ganttView.getElement && ganttView.getElement()) {
            var element = ganttView.getElement();
            isGanttVisible = element.style.display !== 'none';
        }
        // 방법 3: 간단히 항상 동기화 (안전한 fallback)
        else {
            console.log("가시성 확인 메소드를 찾을 수 없어 기본적으로 동기화를 수행합니다.");
            isGanttVisible = true;
        }

        console.log("간트차트 뷰 활성화 상태:", isGanttVisible);

        if (isGanttVisible) {
            console.log("간트차트가 현재 활성화되어 있으므로 데이터를 동기화합니다.");
            // 간트차트 데이터 로딩
            scwin.loadGanttData();
        } else {
            console.log("간트차트가 현재 비활성화되어 있으므로 동기화를 건너뜁니다.");
        }
    } catch (error) {
        console.error("간트차트 뷰 상태 확인 중 오류:", error);
        console.log("오류 발생으로 인해 안전하게 간트차트 동기화를 수행합니다.");
        // 오류 발생 시 안전하게 동기화 수행
        try {
            scwin.loadGanttData();
        } catch (loadError) {
            console.error("간트차트 데이터 로딩 중 오류:", loadError);
        }
    }
};

/**
 * 간트차트 데이터 로딩 함수
 */
scwin.loadGanttData = function () {
    console.log("간트차트 데이터 로딩 시작 (칸반 데이터 재사용)");

    // 간트차트 데이터 리스트 초기화
    dlt_gantt_schedule.removeAll();

    // 칸반의 태스크 데이터가 있는지 확인
    if (!scwin.taskList || scwin.taskList.length === 0) {
        console.warn("칸반 태스크 데이터가 없습니다. 더미 데이터로 간트차트를 표시합니다.");
        // 빈 배열로 설정하여 createGanttJSONFromDataList_backup에서 더미 데이터 생성
        scwin.taskList = [];
    }

    // 칸반의 태스크 데이터를 간트차트용으로 변환
    console.log("=== 간트차트 데이터 변환 시작 ===");
    console.log("칸반 태스크 수:", scwin.taskList.length);

    var validTaskIndex = 0;
    for (var i = 0; i < scwin.taskList.length; i++) {
        var task = scwin.taskList[i];

        console.log("태스크 확인:", {
            title: task.taskTitle,
            startDate: task.startDate,
            endDate: task.endDate,
            boardId: task.boardId
        });

        // 시작일과 종료일이 모두 있는 태스크만 간트차트에 표시
        if (!task.startDate || !task.endDate ||
            task.startDate.trim() === "" || task.endDate.trim() === "") {
            console.log("날짜 정보가 없는 태스크 제외:", task.taskTitle);
            continue;
        }

        // 간트차트 데이터 생성
        var ganttData = {
            taskId: task.taskId,
            taskTitle: task.taskTitle,
            startDate: task.startDate,
            endDate: task.endDate,
            boardId: task.boardId,
            boardTitle: task.boardTitle || "보드",
            priority: task.priority || "MEDIUM",
            tags: task.tags || ""
        };

        console.log("간트차트에 추가할 태스크:", ganttData);

        // 간트차트 데이터 리스트에 추가
        dlt_gantt_schedule.insertRow(validTaskIndex);
        dlt_gantt_schedule.setCellData(validTaskIndex, "taskId", ganttData.taskId);
        dlt_gantt_schedule.setCellData(validTaskIndex, "taskTitle", ganttData.taskTitle);
        dlt_gantt_schedule.setCellData(validTaskIndex, "startDate", ganttData.startDate);
        dlt_gantt_schedule.setCellData(validTaskIndex, "endDate", ganttData.endDate);
        dlt_gantt_schedule.setCellData(validTaskIndex, "boardId", ganttData.boardId);
        dlt_gantt_schedule.setCellData(validTaskIndex, "boardTitle", ganttData.boardTitle);
        dlt_gantt_schedule.setCellData(validTaskIndex, "priority", ganttData.priority);
        dlt_gantt_schedule.setCellData(validTaskIndex, "tags", ganttData.tags);

        validTaskIndex++;
    }

    console.log("간트차트에 유효한 태스크 수:", validTaskIndex);

    // 간트차트에 태스크 데이터 표시
    if (validTaskIndex > 0) {
        // 현재 월로 초기화 (월별 네비게이션 기본 설정)
        var currentDate = new Date();
        scwin.currentGanttYear = currentDate.getFullYear();
        scwin.currentGanttMonth = currentDate.getMonth() + 1;
        scwin.updateGanttMonthLabel();

        // 초기 로딩은 전체 데이터로 표시하되, 현재 월 범위만 그리기
        scwin.loadTasksToGantt(scwin.taskList, scwin.currentGanttYear, scwin.currentGanttMonth);
    } else {
        console.log("간트차트에 표시할 태스크가 없습니다. 더미 데이터로 간트차트를 표시합니다.");
        // 유효한 태스크가 없어도 계속 진행하여 더미 데이터 생성
        scwin.initGanttNavigation();

        var currentDate = new Date();
        scwin.currentGanttYear = currentDate.getFullYear();
        scwin.currentGanttMonth = currentDate.getMonth() + 1;
        scwin.updateGanttMonthLabel();

        // 빈 배열로 전달하여 더미 데이터 생성
        scwin.loadTasksToGantt([], scwin.currentGanttYear, scwin.currentGanttMonth);
    }
};

/**
 * 날짜 포맷팅 (mm/dd/yyyy)
 */
scwin.formatDate = function (date) {
    var month = (date.getMonth() + 1).toString().padStart(2, '0');
    var day = date.getDate().toString().padStart(2, '0');
    var year = date.getFullYear();
    return month + "/" + day + "/" + year;
};

// GitHub 버튼 클릭 - GitHub App 관리 페이지로 이동
scwin.github_onclick = function (e) {
    console.log("GitHub 버튼 클릭됨");

    // 현재 프로젝트 데이터 확인
    var projectData = scwin.currentProjectData;
    if (!projectData) {
        console.error("프로젝트 데이터가 없습니다.");
        $c.win.alert("프로젝트 정보를 불러오는 중입니다. 잠시 후 다시 시도해주세요.");
        return;
    }

    console.log("GitHub 관리자에게 전달할 프로젝트 데이터:", projectData);
    console.log(projectData.userId);
    // 현재 로그인된 사용자 정보 가져오기
    var currentUserId = null;
    try {
        // 1. 프로젝트 데이터에서 사용자 ID 가져오기 (우선순위 1)
        if (projectData && projectData.userId) {
            currentUserId = projectData.userId;
            console.log("프로젝트 데이터에서 사용자 ID 찾음:", currentUserId);
        }

        // 2. WebSquare 파라미터에서 가져오기
        if (!currentUserId && typeof $p !== "undefined" && $p.getParameter) {
            currentUserId = $p.getParameter("userId") || $p.getParameter("user_id") || $p.getParameter("userEmail");
        }

        // 3. 세션 스토리지에서 가져오기
        if (!currentUserId && typeof sessionStorage !== "undefined") {
            currentUserId = sessionStorage.getItem("userId") || sessionStorage.getItem("userEmail") || sessionStorage.getItem("user_id");
        }

        // 4. 로컬 스토리지에서 가져오기
        if (!currentUserId && typeof localStorage !== "undefined") {
            currentUserId = localStorage.getItem("userId") || localStorage.getItem("userEmail") || localStorage.getItem("user_id");
        }

        // 5. 전역 변수에서 가져오기
        if (!currentUserId && typeof window !== "undefined") {
            currentUserId = window.currentUserId || window.userEmail || window.userId;
        }

        if (currentUserId && currentUserId.trim().length > 0 && currentUserId !== "user01") {
            currentUserId = currentUserId.trim();
            console.log("최종 사용자 ID:", currentUserId);
        } else {
            console.error("사용자 ID를 찾을 수 없습니다. GitHub 연동이 불가능합니다.");
            $c.win.alert("로그인된 사용자 정보를 찾을 수 없습니다. 다시 로그인해주세요.");
            return;
        }
    } catch (e) {
        console.error("사용자 정보 가져오기 실패:", e);
        $c.win.alert("사용자 정보를 가져오는 중 오류가 발생했습니다.");
        return;
    }

    console.log("현재 사용자 ID:", currentUserId);

    // 프로젝트 정보를 팝업에 전달
    var jsnPopupData = {
        type: "json",
        name: "project_param",
        data: {
            projectId: projectData.projectId,
            projectName: projectData.projectName,
            description: projectData.description,
            userId: currentUserId
        }
    };

    var options = {
        id: "github_manager_popup",
        type: "wframePopup",
        width: "1000",
        height: "700",
        left: "" + ((window.innerWidth - 1000) / 2) + "",
        top: "100",
        popupName: "GitHub 관리 - " + projectData.projectName,
        modal: true,
        closeAction: "scwin.github_popup_closeAction",
        customTitleBar: false,
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/project/githubManager.xml", options);
};

// GitHub 팝업 닫기 액션
scwin.github_popup_closeAction = function (argRuntimeID, argJsnInfo) {
    var popObj = $p.getPopupWindow(argRuntimeID);
    // GitHub 관련 데이터 새로고침 로직 추가 가능
    console.log("GitHub 관리자 창이 닫혔습니다.");
    return true;
};

// 팝업 닫기 액션
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    var popObj = $p.getPopupWindow(argRuntimeID);
    scwin.loadProjectData(); // 팝업 닫기 후 데이터 새로고침
    return true;
};

scwin.add_task_submitdone = function (e) {
    console.log("Task creation successful:", e);

    // WebSquare 응답 구조에서 태스크 데이터 추출
    var responseData = e.responseJSON;
    var taskData = responseData.elData;

    console.log("응답 데이터 구조:", responseData);
    console.log("추출된 태스크 데이터:", taskData);

    if (!taskData || !taskData.taskId) {
        console.error("태스크 데이터를 찾을 수 없습니다. 응답 구조:", responseData);
        $c.win.alert("태스크 생성은 완료되었지만 UI 업데이트에 실패했습니다.");
        return;
    }

    // 실제 DB에서 받은 데이터로 카드 데이터 구성
    var cardData = {
        taskId: taskData.taskId,
        taskTitle: taskData.taskTitle,
        priority: taskData.priority || "MEDIUM",
        startDate: taskData.startDate || "",
        endDate: taskData.endDate || "",
        tags: taskData.tags || "",
        projectUserId: taskData.projectUserId || "",
        taskDescription: "", // 현재 TaskVo에 없는 필드
        boardId: taskData.boardId // DB에서 받은 실제 boardId 사용
    };

    console.log("칸반 카드 생성할 데이터:", cardData);

    // 해당 보드의 카드 컨테이너에 카드 동적 생성
    scwin.createKanbanCardInBoard(cardData);

    // 입력 폼 초기화
    dm_taskVo.set("taskTitle", "");
    dm_taskVo.set("boardId", "");
};

/**
 * 해당 보드의 카드 컨테이너에 칸반 카드를 동적 생성하는 함수
 * @param {Object} cardData - 카드 데이터 (taskId, taskTitle, boardId 등)
 */
scwin.createKanbanCardInBoard = function (cardData) {
    console.log("보드별 칸반 카드 생성 시작:", cardData);

    if (!cardData.boardId) {
        console.error("boardId가 없어 카드를 생성할 수 없습니다:", cardData);
        return;
    }

    // 해당 보드의 카드 컨테이너 찾기
    var cardContainerId = "card_container_" + cardData.boardId;
    var targetContainer = eval(cardContainerId);

    if (!targetContainer) {
        console.error("카드 컨테이너를 찾을 수 없습니다:", cardContainerId);
        return;
    }

    console.log("카드 생성 대상 컨테이너:", cardContainerId);

    // 고유한 카드 ID 생성
    var cardId = "card_" + cardData.taskId;

    // 중복 생성 방지 - 이미 존재하는 카드는 생성하지 않음
    var existingCard = $p.getComponentById(cardId);
    if (existingCard) {
        console.log("이미 존재하는 카드입니다:", cardId);
        return existingCard;
    }

    // 카드 데이터 디버깅
    console.log("=== 카드 렌더링 디버그 ===");
    console.log("전체 cardData:", cardData);
    console.log("cardData.priority:", cardData.priority);
    console.log("priority 타입:", typeof cardData.priority);
    console.log("========================");

    // 우선순위 값 정규화 (대소문자 통일 및 기본값 설정)
    var normalizedPriority = "";
    if (cardData.priority && typeof cardData.priority === "string") {
        normalizedPriority = cardData.priority.toUpperCase();
    } else {
        console.warn("Priority 필드가 없거나 잘못된 형태:", cardData.priority);
        normalizedPriority = "MEDIUM"; // 기본값
    }

    // 우선순위에 따른 CSS 클래스 결정
    var priorityClass = "";
    var priorityText = "";
    if (normalizedPriority === "HIGH") {
        priorityClass = "priority-high";
        priorityText = "높음";
    } else if (normalizedPriority === "MEDIUM") {
        priorityClass = "priority-medium";
        priorityText = "보통";
    } else if (normalizedPriority === "LOW") {
        priorityClass = "priority-low";
        priorityText = "낮음";
    } else {
        console.error("Unknown priority value after normalization:", normalizedPriority);
        priorityClass = "priority-medium"; // 알 수 없는 값은 보통으로 설정
        priorityText = "보통";
    }

    // 1. 메인 카드 그룹 생성 (드래그 가능하도록 설정)
    var cardGroup = null;
    try {
        cardGroup = $p.dynamicCreate(
            cardId,
            "group",
            {
                className: "project-card draggable-card",
                style: "margin-bottom: 8px; padding: 12px; background: white; border: 1px solid #d0d7de; border-radius: 6px; cursor: move;"
            },
            targetContainer
        );
    } catch (error) {
        console.error("카드 그룹 생성 중 오류 발생:", cardId, error);
        return;
    }

    if (!cardGroup) {
        console.error("카드 그룹 생성 실패:", cardId);
        return;
    }

    // 생성된 카드에 onclick 이벤트 핸들러를 연결합니다.
    cardGroup.bind("onclick", scwin.new_task_onclick);

    // WebSquare 컴포넌트 렌더링 완료 후 이벤트 바인딩 (async/await 사용)
    scwin.setupDragEventsAsync(cardGroup, cardData, cardId);

    // 2. 카드 헤더 그룹 생성
    var headerGroup = null;
    try {
        headerGroup = $p.dynamicCreate(
            cardId + "_header",
            "group",
            {
                className: "project-card-header",
                style: "display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;"
            },
            cardGroup
        );
    } catch (error) {
        console.error("헤더 그룹 생성 중 오류 발생:", cardId + "_header", error);
        cardGroup.remove();
        return;
    }

    if (!headerGroup) {
        console.error("헤더 그룹 생성 실패:", cardId + "_header");
        cardGroup.remove();
        return;
    }

    // 3. 작업 제목 생성
    var titleSpan = null;
    try {
        titleSpan = $p.dynamicCreate(
            cardId + "_title",
            "output",
            {
                className: "project-name",
                style: "font-weight: 500; font-size: 14px; color: #24292f; line-height: 1.3;"
            },
            headerGroup
        );
        if (titleSpan) {
            titleSpan.setValue(cardData.taskTitle);
        }
    } catch (error) {
        console.error("제목 생성 중 오류 발생:", cardId + "_title", error);
    }

    // 4. 우선순위 배지 생성
    var prioritySpan = null;
    try {
        prioritySpan = $p.dynamicCreate(
            cardId + "_priority",
            "output",
            {
                className: "priority-badge " + priorityClass
            },
            headerGroup
        );
        if (prioritySpan) {
            prioritySpan.setValue(priorityText);
        }
    } catch (error) {
        console.error("우선순위 배지 생성 중 오류 발생:", cardId + "_priority", error);
    }

    // 5. 설명 생성 (있는 경우)
    if (cardData.taskDescription && cardData.taskDescription.trim()) {
        var descSpan = $p.dynamicCreate(
            cardId + "_desc",
            "output",
            {
                className: "project-description",
                style: "font-size: 12px; color: #656d76; line-height: 1.4; margin-bottom: 8px;"
            },
            cardGroup
        );
        if (descSpan) {
            descSpan.setValue(cardData.taskDescription);
        }
    }

    // 6. 메타데이터 그룹 생성
    var metaGroup = $p.dynamicCreate(
        cardId + "_meta",
        "group",
        {
            className: "project-meta",
            style: "display: flex; justify-content: space-between; align-items: center; font-size: 12px; color: #656d76;"
        },
        cardGroup
    );

    // 7. 담당자 정보 (있는 경우)
    if (cardData.projectUserId) {
        var assigneeSpan = $p.dynamicCreate(
            cardId + "_assignee",
            "output",
            {
                className: "assignee-info"
            },
            metaGroup
        );
        if (assigneeSpan) {
            var userName = scwin.getUserNameByUserId(cardData.projectUserId, cardData);
            assigneeSpan.setValue("담당자: " + userName);
        }
    }

    // 8. 마감일 (있는 경우)
    if (cardData.endDate) {
        var dueDateSpan = $p.dynamicCreate(
            cardId + "_due_date",
            "output",
            {
                className: "due-date"
            },
            metaGroup
        );
        if (dueDateSpan) {
            dueDateSpan.setValue("마감: " + cardData.endDate);
        }
    }

    console.log("칸반 카드 생성 완료:", cardId, "보드:", cardData.boardId);

    return cardGroup;
};

/**
 * 칸반 카드를 동적으로 생성하는 함수 (기존 함수 - 호환성 유지)
 * @param {Object} cardData - 카드 데이터 (taskId, taskTitle, priority 등)
 * @param {String} columnType - 컬럼 타입 ("todo", "inprogress", "done")
 */
scwin.createKanbanCard = function (cardData, columnType) {
    console.log("칸반 카드 생성 시작:", cardData, columnType);

    // 컬럼별 타겟 컨테이너 ID 매핑 (동적 생성된 컨테이너 사용)
    var containerMap = {
        "todo": "card_container_BOARD_TODO_001",
        "inprogress": "card_container_BOARD_PROGRESS_001",
        "done": "card_container_BOARD_DONE_001"
    };

    // 동적으로 생성된 컨테이너 찾기 (boardId 기반)
    if (cardData.boardId) {
        containerMap[columnType] = "card_container_" + cardData.boardId;
    }

    var containerId = containerMap[columnType];
    if (!containerId) {
        console.error("잘못된 컬럼 타입:", columnType);
        return;
    }

    // 타겟 컨테이너 객체 가져오기
    var targetContainer = eval(containerId);
    if (!targetContainer) {
        console.error("컨테이너를 찾을 수 없습니다:", containerId);
        return;
    }

    // 우선순위에 따른 CSS 클래스 결정
    var priorityClass = "priority-medium"; // 기본값
    var priorityText = "보통";
    if (cardData.priority === "HIGH") {
        priorityClass = "priority-high";
        priorityText = "높음";
    } else if (cardData.priority === "LOW") {
        priorityClass = "priority-low";
        priorityText = "낮음";
    }

    // 고유한 카드 ID 생성
    var cardId = "card_" + (cardData.taskId || new Date().getTime());

    // 1. 메인 카드 그룹 생성
    var cardGroup = $p.dynamicCreate(
        cardId,
        "group",
        {
            className: "project-card",
            "ev:onclick": "scwin.new_task_onclick",
            "data-task-id": cardData.taskId || "",
            "data-board-id": cardData.boardId || "",
            "data-row": "0"
        },
        targetContainer
    );

    // 2. 카드 헤더 그룹 생성
    var headerGroup = $p.dynamicCreate(
        cardId + "_header",
        "group",
        {
            className: "project-card-header"
        },
        cardGroup
    );

    // 3. 작업 제목 생성
    var titleSpan = $p.dynamicCreate(
        cardId + "_title",
        "output",
        {
            className: "project-name"
        },
        headerGroup
    );
    if (titleSpan) {
        titleSpan.setValue(cardData.taskTitle);
    }

    // 4. 우선순위 배지 생성
    var prioritySpan = $p.dynamicCreate(
        cardId + "_priority",
        "output",
        {
            className: "priority-badge " + priorityClass
        },
        headerGroup
    );
    if (prioritySpan) {
        prioritySpan.setValue(priorityText);
    }

    // 5. 설명 생성 (있는 경우)
    if (cardData.taskDescription) {
        var descSpan = $p.dynamicCreate(
            cardId + "_desc",
            "output",
            {
                className: "project-description"
            },
            cardGroup
        );
        if (descSpan) {
            descSpan.setValue(cardData.taskDescription);
        }
    }

    // 6. 메타데이터 그룹 생성
    var metaGroup = $p.dynamicCreate(
        cardId + "_meta",
        "group",
        {
            className: "project-meta"
        },
        cardGroup
    );
    if (!metaGroup) {
        console.error("메타그룹 생성 실패:", cardId);
        return;
    }

    // 7. 담당자 정보 그룹 생성
    var assigneeGroup = $p.dynamicCreate(
        cardId + "_assignee",
        "group",
        {
            className: "assignee"
        },
        metaGroup
    );
    if (!assigneeGroup) {
        console.error("담당자 그룹 생성 실패:", cardId);
        return;
    }

    // 8. 담당자 아바타 생성
    var avatarSpan = $p.dynamicCreate(
        cardId + "_avatar",
        "output",
        {
            className: "assignee-avatar"
        },
        assigneeGroup
    );
    if (avatarSpan) {
        if (cardData.projectUserId) {
            var userName = scwin.getUserNameByUserId(cardData.projectUserId, cardData);
            if (userName && typeof userName === 'string' && userName.length > 0) {
                avatarSpan.setValue(userName.charAt(0)); // 사용자 이름의 첫 글자
            } else {
                avatarSpan.setValue('?'); // 기본값
            }
        } else {
            avatarSpan.setValue('?'); // 사용자 없음 기본값
        }
    } else {
        console.error("아바타 스팬 생성 실패:", cardId);
    }

    // 9. 담당자 이름 생성
    var assigneeNameSpan = $p.dynamicCreate(
        cardId + "_assignee_name",
        "output",
        {},
        assigneeGroup
    );
    if (assigneeNameSpan) {
        if (cardData.projectUserId) {
            var userName = scwin.getUserNameByUserId(cardData.projectUserId, cardData);
            if (userName && typeof userName === 'string') {
                assigneeNameSpan.setValue(userName);
            } else {
                assigneeNameSpan.setValue('담당자 없음');
            }
        } else {
            assigneeNameSpan.setValue('담당자 없음'); // 사용자 없음 기본값
        }
    } else {
        console.error("담당자 이름 스팬 생성 실패:", cardId);
    }

    // 10. 마감일 생성 (있는 경우)
    if (cardData.endDate) {
        var dueDateSpan = $p.dynamicCreate(
            cardId + "_due_date",
            "output",
            {
                className: "due-date"
            },
            metaGroup
        );
        if (dueDateSpan && cardData.endDate) {
            dueDateSpan.setValue(cardData.endDate);
        }
    }

    console.log("칸반 카드 생성 완료:", cardId);
    return cardGroup;
};

scwin.load_Board_submitdone = function (e) {
    console.log("Board data loaded successfully:", e);

    // 응답에서 보드 데이터 추출
    var responseData = e.responseJSON;
    var boardList = responseData.boardVoList;
    let userHeader = responseData.userHeader;
    dm_userInfo.set("userId", userHeader.userId);
    dm_userInfo.set("userName", userHeader.userName);
    dm_userInfo.set("userImage", userHeader.userImage);
    if (!boardList || boardList.length === 0) {
        console.warn("보드 데이터가 없습니다. 기본 컬럼을 사용합니다.");
        return;
    }

    console.log("로드된 보드 목록:", boardList);

    // DataList에 보드 데이터 설정
    dlt_boardListVo.setJSON(boardList);

    // 동적 칸반 컬럼들 생성
    scwin.createDynamicKanbanColumns(boardList);
};


/**
 * 보드 데이터를 기반으로 동적 칸반 컬럼들을 생성하는 함수 (순차 실행)
 * @param {Array} boardList - 서버에서 받은 보드 목록
 */
scwin.createDynamicKanbanColumns = function (boardList) {
    console.log("동적 칸반 컬럼 생성 시작:", boardList);

    // 새로운 보드 로딩 시작 시 기존 태스크 데이터 초기화
    scwin.taskList = [];
    console.log("새로운 보드 로딩을 위해 기존 태스크 데이터 초기화");

    // boardList 유효성 검증
    if (!boardList || !Array.isArray(boardList) || boardList.length === 0) {
        console.warn("유효하지 않은 보드 목록:", boardList);
        return;
    }

    var kanbanContainer = grp_kanban_board;
    if (!kanbanContainer) {
        console.error("칸반 컨테이너를 찾을 수 없습니다");
        return;
    }

    // 이미 생성 중인 경우 중복 실행 방지
    if (scwin.isCreatingColumns) {
        console.log("이미 칸반 컬럼을 생성 중입니다. 중복 실행을 방지합니다.");
        return;
    }

    scwin.isCreatingColumns = true;

    scwin.clearExistingKanbanColumns();

    for (let i = 0; i < boardList.length; i++) {
        const board = boardList[i];

        // board 객체 유효성 검증
        if (!board || !board.boardId || !board.boardTitle) {
            console.error("유효하지 않은 보드 객체:", board);
            continue;
        }

        console.log(`컬럼 ${i + 1}/${boardList.length} 생성:`, board.boardTitle);

        try {
            scwin.createSingleKanbanColumn(board, i, kanbanContainer);
        } catch (error) {
            console.error("컬럼 생성 중 오류:", board.boardId, error);
            continue;
        }

        // 칸반용 태스크 로드
        if (board.boardId) {
            console.log("칸반용 태스크 로드 실행, boardId:", board.boardId);
            dm_search_task.set("boardId", board.boardId);
            $p.executeSubmission("load_Tasks_With_UserName");
        }
    }

    console.log("동적 칸반 컬럼 생성 및 태스크 로드 요청 완료");

    // 생성 완료 후 플래그 해제
    setTimeout(function () {
        scwin.isCreatingColumns = false;
    }, 100);
};

/**
 * 태스크 로드 완료 후, 칸반 카드를 생성하는 콜백 함수 (프론트엔드 필터링 지원)
 */
scwin.load_Tasks_submitdone = function (e) {
    console.log("태스크 로드 완료 (프론트엔드 필터링 지원):", e);

    // 1. 응답에서 직접 태스크 목록 추출
    var responseData = e.responseJSON;

    // 다중 보드 데이터 누적을 위해 기존 데이터에 추가
    var newTasks = responseData.elData.taskVoList || [];
    if (!scwin.taskList) {
        scwin.taskList = [];
    }
    scwin.taskList = scwin.taskList.concat(newTasks);
    console.log("서버로부터 직접 받은 태스크 목록:", scwin.taskList);

    // 칸반 보드용 태스크 처리
    if (scwin.taskList && scwin.taskList.length > 0) {
        var boardId = scwin.taskList[0].boardId; // 첫 번째 태스크의 boardId를 사용

        // 전체 태스크 데이터를 로컬에 저장 (필터링용)
        scwin.storeAllTasksData(boardId, scwin.taskList);

        // 필터링과 정렬을 모두 적용하여 태스크 표시
        scwin.sortAndFilterBoardTasks(boardId);

        console.log(`보드 [${boardId}]의 태스크 로드 및 처리 완료: ${scwin.taskList.length}개`);
    } else {
        console.log("해당 보드에 대한 태스크가 없습니다.");

        // boardId 추출 (검색 조건에서)
        var searchCondition = $p.getComponentById("dm_search_task");
        if (searchCondition) {
            var boardId = searchCondition.get("boardId");
            if (boardId) {
                // 빈 데이터 저장 및 정렬/필터링 적용
                scwin.storeAllTasksData(boardId, []);
                scwin.sortAndFilterBoardTasks(boardId);
            }
        }
    }

    // 칸반 데이터 업데이트 후 간트차트 동기화
    scwin.syncGanttWithKanban();
};

/**
 * 기존 동적 칸반 컬럼들을 제거하는 함수 (중복 생성 방지)
 */
scwin.clearExistingKanbanColumns = function () {
    console.log("기존 동적 칸반 컬럼 제거 시작");

    var kanbanContainer = grp_kanban_board;
    if (!kanbanContainer) {
        console.error("칸반 컨테이너를 찾을 수 없습니다");
        return;
    }

    // 기존 보드 데이터가 있으면 해당 컬럼들 제거
    var existingBoardList = dlt_boardListVo.getAllJSON();
    if (existingBoardList && existingBoardList.length > 0) {
        for (let i = 0; i < existingBoardList.length; i++) {
            var board = existingBoardList[i];
            var columnId = "grp_dynamic_" + board.boardId;

            try {
                var existingColumn = eval(columnId);
                if (existingColumn) {
                    existingColumn.remove();
                    console.log("기존 컬럼 제거:", columnId);
                }
            } catch (e) {
                console.log("컬럼이 존재하지 않음:", columnId);
            }
        }
    }

    // WebSquare ID로 생성된 동적 컴포넌트들도 확인 제거
    try {
        var children = kanbanContainer.getChildren();
        for (let i = children.length - 1; i >= 0; i--) {
            var child = children[i];
            var childId = child.getID();

            // grp_dynamic_ 또는 card_container_로 시작하는 동적 컴포넌트 제거
            if (childId && (childId.startsWith("grp_dynamic_") || childId.startsWith("card_container_"))) {
                child.remove();
                console.log("동적 컴포넌트 제거:", childId);
            }
        }
    } catch (e) {
        console.log("자식 컴포넌트 제거 중 오류:", e);
    }

    console.log("기존 동적 칸반 컬럼 제거 완료");
};

/**
 * sleep 유틸리티 함수
 * @param {Number} ms - 대기 시간 (밀리초)
 */
scwin.sleep = function (ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
};

/**
 * 단일 칸반 컬럼을 생성하는 함수
 * @param {Object} board - 보드 데이터 (boardId, boardTitle, projectId)
 * @param {Number} index - 컬럼 순서
 * @param {Object} container - 부모 컨테이너
 */
scwin.createSingleKanbanColumn = function (board, index, container) {
    // board 파라미터 유효성 검증
    if (!board || !board.boardId || !board.boardTitle) {
        console.error("유효하지 않은 board 데이터:", board);
        return;
    }

    console.log("칸반 컬럼 생성:", board.boardTitle);

    var columnId = "grp_dynamic_" + board.boardId;
    var cardContainerId = "card_container_" + board.boardId;

    // 중복 생성 방지 - 이미 존재하는 컬럼인지 확인
    try {
        var existingColumn = eval(columnId);
        if (existingColumn) {
            console.log("이미 존재하는 컬럼:", columnId, "- 생성 건너뜀");
            return;
        }
    } catch (e) {
        // 컴포넌트가 존재하지 않음 - 정상적으로 생성 진행
    }

    // 1. 메인 컬럼 그룹 생성
    var columnGroup = $p.dynamicCreate(
        columnId,
        "group",
        {
            className: "kanban-column",
            style: "flex: 1; margin: 0 8px; background: #f6f8fa; border-radius: 8px; padding: 16px;",
            "data-board-id": board.boardId
        },
        container
    );

    if (!columnGroup) {
        console.error("메인 컬럼 그룹 생성 실패:", columnId);
        return;
    }

    // 2. 컬럼 헤더 생성
    var headerGroup = $p.dynamicCreate(
        columnId + "_header",
        "group",
        {
            className: "kanban-column-header",
            style: "display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px;"
        },
        columnGroup
    );

    if (!headerGroup) {
        console.error("헤더 그룹 생성 실패:", columnId);
        return;
    }

    // 3. 컬럼 제목 그룹 생성
    var titleGroup = $p.dynamicCreate(
        columnId + "_title_group",
        "group",
        {
            style: "display: flex; align-items: center; gap: 8px;"
        },
        headerGroup
    );
    if (!titleGroup) {
        console.error("타이틀 그룹 생성 실패:", columnId);
        return;
    }

    // 4. 상태 인디케이터 생성
    var statusColor = scwin.getBoardStatusColor(
        (board.boardTitle && typeof board.boardTitle === 'string') ? board.boardTitle : 'default'
    );
    var statusIndicator = $p.dynamicCreate(
        columnId + "_status",
        "output",
        {
            className: "status-indicator",
            style: "width: 8px; height: 8px; border-radius: 50%; background-color: " + statusColor + ";"
        },
        titleGroup
    );
    if (!statusIndicator) {
        console.error("상태 인디케이터 생성 실패:", columnId);
    }

    // 5. 컬럼 제목 생성
    var titleSpan = $p.dynamicCreate(
        columnId + "_title",
        "output",
        {
            className: "column-title",
            style: "font-weight: 600; font-size: 14px; color: #24292f;"
        },
        titleGroup
    );
    if (titleSpan) {
        try {
            titleSpan.setValue(board.boardTitle || 'Untitled');
        } catch (e) {
            console.error("제목 스팬 setValue 오류:", e, columnId);
        }
    } else {
        console.error("제목 스팬 생성 실패:", columnId);
    }

    // 6. 태스크 카운트 생성
    var countSpan = $p.dynamicCreate(
        columnId + "_count",
        "output",
        {
            className: "task-count",
            style: "background: #d1d9e0; color: #656d76; padding: 2px 6px; border-radius: 12px; font-size: 12px; font-weight: 500;"
        },
        titleGroup
    );
    if (countSpan) {
        try {
            countSpan.setValue("0"); // 초기값, 나중에 태스크 로드 시 업데이트
        } catch (e) {
            console.error("카운트 스팬 setValue 오류:", e, columnId);
        }
    } else {
        console.error("카운트 스팬 생성 실패:", columnId);
    }

    // 7. 카드 컨테이너 생성 (드롭 존으로 설정)
    var cardContainer = $p.dynamicCreate(
        cardContainerId,
        "group",
        {
            className: "kanban-cards-container drop-zone",
            style: "display: flex; flex-direction: column; gap: 8px; min-height: 100px; width: 100%;",
            "data-board-id": board.boardId
        },
        columnGroup
    );

    if (!cardContainer) {
        console.error("카드 컨테이너 생성 실패:", cardContainerId);
        return;
    }

    // 드롭 존 이벤트 핸들러 추가 (async/await 사용)
    scwin.setupDropZoneAsync(cardContainer, board.boardId, cardContainerId);

    // 8. Add Card 버튼 생성
    var addButton = $p.dynamicCreate(
        columnId + "_add_btn",
        "trigger",
        {
            style: "width: 100%; padding: 8px; margin-top: 8px; background: transparent; border: 1px dashed #d1d9e0; border-radius: 6px; color: #656d76; font-size: 14px; cursor: pointer;",
            className: "add-card-btn"
        },
        columnGroup
    );

    if (addButton) {
        // setValue로 버튜 텍스트 설정
        try {
            addButton.setValue("+ Add card");
        } catch (e) {
            console.error("Add Card 버튼 setValue 오류:", e, columnId);
        }

        // boardId 저장 (null 체크)
        if (board.boardId) {
            addButton.boardId = board.boardId;

            // onclick 이벤트 바인딩
            addButton.bind("onclick", function (e) {
                console.log("Add Card 버튼 클릭, boardId:", addButton.boardId);
                scwin.dynamicAddCard_onclick_fixed(addButton.boardId);
            });
        } else {
            console.error("보드 ID가 없어 Add Card 버튼 기능을 설정할 수 없습니다:", board);
        }

        console.log("Add Card 버튼 생성 성공:", columnId, "boardId:", board.boardId);
    } else {
        console.error("Add Card 버튼 생성 실패:", columnId, "부모:", columnGroup);
    }

    console.log("칸반 컬럼 생성 완료:", board.boardTitle);
};

// ==================== 드래그 앤 드롭 테스트 및 디버깅 ====================

// WebSquare 컴포넌트 렌더링 대기 유틸리티
scwin.waitForElementReady = function (component, maxAttempts = 50) {
    return new Promise((resolve, reject) => {
        let attempts = 0;

        const checkElement = () => {
            attempts++;

            // WebSquare 컴포넌트 체크
            if (component && component.element && component.element.nodeType === 1) {
                console.log(`컴포넌트 렌더링 완료 (${attempts}회 시도):`, component.id);
                resolve(component.element);
                return;
            }

            // WebSquare 컴포넌트가 존재하지만 element가 없는 경우 (display:contents 등)
            // if (component && component.id && !component.element) {
            //     console.log(`컴포넌트는 존재하지만 DOM 요소가 없습니다 (${attempts}회 시도):`, component.id);

            //     // 10회 이상 시도했는데도 element가 없으면 컴포넌트 자체를 반환
            //     if (attempts >= 10) {
            //         console.warn(`DOM 요소가 없는 컴포넌트를 반환합니다:`, component.id);
            //         resolve(component);
            //         return;
            //     }
            // }

            if (attempts >= maxAttempts) {
                console.error(`컴포넌트 렌더링 실패 (${maxAttempts}회 시도):`, component.id);
                // 에러 대신 컴포넌트 자체를 반환하여 계속 진행
                resolve(component);
                return;
            }

            // 비동기적으로 다음 체크 예약
            setTimeout(checkElement, 10);
        };

        checkElement();
    });
};

// ==================== 드래그 락 시스템 ====================

/**
 * 카드 락 요청
 */
scwin.requestCardLock = function (taskId) {
    var currentUserId = scwin.getCurrentUserId();
    var currentUserName = scwin.getCurrentUserName();

    console.log("카드 락 요청:", taskId, "by", currentUserName);

    // 이미 다른 사용자가 락을 보유하고 있는지 확인
    if (scwin.lockedCards.has(taskId)) {
        var lockInfo = scwin.lockedCards.get(taskId);
        if (lockInfo.userId !== currentUserId) {
            console.log("카드가 이미 락되어 있습니다:", lockInfo.userName);
            return false;
        }
    }

    // 락 정보 설정
    var lockInfo = {
        userId: currentUserId,
        userName: currentUserName,
        timestamp: Date.now()
    };

    scwin.lockedCards.set(taskId, lockInfo);
    scwin.myLockedCards.add(taskId);

    // WebSocket으로 락 상태 전파
    scwin.sendCardLockMessage(taskId, "LOCK");

    // 자동 락 해제 타이머 설정
    setTimeout(function () {
        scwin.releaseCardLock(taskId, true);
    }, scwin.lockTimeout);

    // 락된 카드에 시각적 표시 추가
    scwin.updateCardLockVisual(taskId, lockInfo);

    return true;
};

/**
 * 카드 락 해제 (편집용)
 */
scwin.releaseCardLock = function (taskId, isAutoRelease) {
    var currentUserId = scwin.getCurrentUserId();

    console.log("카드 편집 락 해제:", taskId, isAutoRelease ? "(자동)" : "(수동)");

    // 내가 락한 카드인지 확인
    if (!scwin.myLockedCards.has(taskId)) {
        return false;
    }

    // 락 정보 제거
    scwin.lockedCards.delete(taskId);
    scwin.myLockedCards.delete(taskId);

    // WebSocket으로 락 해제 상태 전파
    scwin.sendCardLockMessage(taskId, "UNLOCK");

    // 락 시각적 표시 제거
    scwin.updateCardLockVisual(taskId, null);

    return true;
};

/**
 * ������ 카드 이동 락 요청 (신규)
 */
scwin.requestCardMoveLock = function (taskId) {
    var currentUserId = scwin.getCurrentUserId();
    var currentUserName = scwin.getCurrentUserName();

    console.log("������ 카드 이동 락 요청:", taskId, "by", currentUserName);

    // 이미 다른 사용자가 락을 보유하고 있는지 확인
    if (scwin.lockedCards.has(taskId)) {
        var lockInfo = scwin.lockedCards.get(taskId);
        if (lockInfo.userId !== currentUserId) {
            console.log("카드가 이미 락되어 있습니다:", lockInfo.userName, lockInfo.type);
            return false;
        }
    }

    // 이동 락 정보 설정
    var moveLockInfo = {
        userId: currentUserId,
        userName: currentUserName,
        timestamp: Date.now(),
        type: "move"
    };

    scwin.lockedCards.set(taskId, moveLockInfo);
    scwin.myLockedCards.add(taskId);

    // WebSocket으로 이동 락 상태 전파
    scwin.sendCardMoveLockMessage(taskId, "MOVE_LOCK");

    // 자동 락 해제 타이머 설정 (이동은 짧게 10초)
    setTimeout(function () {
        scwin.releaseCardMoveLock(taskId, true);
    }, 10000);

    // 락된 카드에 시각적 표시 추가
    scwin.updateCardMoveLockVisual(taskId, moveLockInfo);

    console.log("✅ 카드 이동 락 획득 완료:", taskId);
    return true;
};

/**
 * ������ 카드 이동 락 해제 (신규)
 */
scwin.releaseCardMoveLock = function (taskId, isAutoRelease) {
    var currentUserId = scwin.getCurrentUserId();

    console.log("������ 카드 이동 락 해제:", taskId, isAutoRelease ? "(자동)" : "(수동)");

    // 내가 락한 카드인지 확인
    if (!scwin.myLockedCards.has(taskId)) {
        console.log("⚠️ 해제할 이동 락이 없음:", taskId);
        return false;
    }

    // 현재 락이 이동 락인지 확인
    var currentLock = scwin.lockedCards.get(taskId);
    if (!currentLock || currentLock.type !== "move" || currentLock.userId !== currentUserId) {
        console.log("⚠️ 이동 락이 아니거나 소유자가 다름:", taskId);
        return false;
    }

    // 락 정보 제거
    scwin.lockedCards.delete(taskId);
    scwin.myLockedCards.delete(taskId);

    // WebSocket으로 이동 락 해제 상태 전파
    scwin.sendCardMoveLockMessage(taskId, "MOVE_UNLOCK");

    // 락 시각적 표시 제거
    scwin.updateCardMoveLockVisual(taskId, null);

    console.log("✅ 카드 이동 락 해제 완료:", taskId);
    return true;
};

/**
 * 카드가 락되어 있는지 확인
 */
scwin.isCardLocked = function (taskId) {
    var currentUserId = scwin.getCurrentUserId();

    if (!scwin.lockedCards.has(taskId)) {
        return false;
    }

    var lockInfo = scwin.lockedCards.get(taskId);
    // 내가 락한 카드는 락되지 않은 것으로 처리
    return lockInfo.userId !== currentUserId;
};

/**
 * 카드 락 WebSocket 메시지 전송
 */
scwin.sendCardLockMessage = function (taskId, action) {
    var currentUserId = scwin.getCurrentUserId();
    var currentUserName = scwin.getCurrentUserName();

    var message = {
        type: "CARD_LOCK",
        taskId: taskId,
        userId: currentUserId,
        message: action + "|" + currentUserName, // "LOCK|사용자명" 또는 "UNLOCK|사용자명"
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

/**
 * ������ 카드 이동 락 WebSocket 메시지 전송 (신규)
 */
scwin.sendCardMoveLockMessage = function (taskId, action) {
    var currentUserId = scwin.getCurrentUserId();
    var currentUserName = scwin.getCurrentUserName();

    var message = {
        type: "CARD_LOCK",
        taskId: taskId,
        userId: currentUserId,
        message: action + "|" + currentUserName, // "MOVE_LOCK|사용자명" 또는 "MOVE_UNLOCK|사용자명"
        timestamp: Date.now()
    };

    console.log("������ 카드 이동 락 메시지 전송:", message);
    scwin.sendWebSocketMessage(message);
};

/**
 * 카드 락 시각적 표시 업데이트 (편집용)
 */
scwin.updateCardLockVisual = function (taskId, lockInfo) {
    try {
        var cardElement = document.querySelector('[data-task-id="' + taskId + '"]');
        if (!cardElement) {
            console.log("카드 요소를 찾을 수 없습니다:", taskId);
            return;
        }

        if (lockInfo) {
            // 편집 락 표시 추가 - 빨간 테두리와 툴팁
            cardElement.classList.add("card-locked");
            cardElement.title = lockInfo.userName + "님이 편집 중입니다";
            cardElement.setAttribute("data-locked-by", lockInfo.userName);
        } else {
            // 편집 락 표시 제거
            cardElement.classList.remove("card-locked");
            cardElement.removeAttribute("title");
            cardElement.removeAttribute("data-locked-by");
        }
    } catch (e) {
        console.error("카드 편집 락 시각적 표시 업데이트 오류:", e);
    }
};

/**
 * 카드 이동 락 시각적 표시 업데이트 (이동용)
 */
scwin.updateCardMoveLockVisual = function (taskId, lockInfo) {
    try {
        var cardElement = document.querySelector('[data-task-id="' + taskId + '"]');
        if (!cardElement) {
            console.log("카드 요소를 찾을 수 없습니다:", taskId);
            return;
        }

        if (lockInfo) {
            // 이동 락 표시 추가 - 주황색 테두리와 툴팁
            cardElement.classList.add("card-move-locked");
            cardElement.title = lockInfo.userName + "님이 이동 중입니다";
            cardElement.setAttribute("data-move-locked-by", lockInfo.userName);

            // 드래그 비활성화
            cardElement.setAttribute("draggable", "false");

            console.log("������ 카드 이동 락 시각 표시 적용:", taskId, "by", lockInfo.userName);
        } else {
            // 이동 락 표시 제거
            cardElement.classList.remove("card-move-locked");
            cardElement.removeAttribute("title");
            cardElement.removeAttribute("data-move-locked-by");

            // 드래그 다시 활성화
            cardElement.setAttribute("draggable", "true");

            console.log("������ 카드 이동 락 시각 표시 제거:", taskId);
        }
    } catch (e) {
        console.error("카드 이동 락 시각적 표시 업데이트 오류:", e);
    }
};

/**
 * 다른 사용자의 카드 락 메시지 처리
 */
scwin.handleCardLockMessage = function (message) {
    console.log("카드 락 메시지 수신:", message);

    var currentUserId = scwin.getCurrentUserId();

    // 내가 보낸 메시지는 무시
    if (message.userId === currentUserId) {
        return;
    }

    // message 필드에서 액션과 사용자명 파싱 ("LOCK|사용자명", "UNLOCK|사용자명", "MOVE_LOCK|사용자명", "MOVE_UNLOCK|사용자명")
    var messageParts = message.message ? message.message.split("|") : [];
    var action = messageParts[0];
    var userName = messageParts[1] || message.userId;

    if (action === "LOCK") {
        // 편집용 락킹 (기존 로직)
        var lockInfo = {
            userId: message.userId,
            userName: userName,
            timestamp: message.timestamp,
            type: "edit"
        };

        scwin.lockedCards.set(message.taskId, lockInfo);
        scwin.updateCardLockVisual(message.taskId, lockInfo);

        console.log("카드가 편집 락되었습니다:", message.taskId, "by", userName);

    } else if (action === "UNLOCK") {
        // 편집용 언락 (기존 로직)
        scwin.lockedCards.delete(message.taskId);
        scwin.updateCardLockVisual(message.taskId, null);

        console.log("카드 편집 락이 해제되었습니다:", message.taskId);

    } else if (action === "MOVE_LOCK") {
        // ������ 이동용 락킹 (신규 로직)
        var moveLockInfo = {
            userId: message.userId,
            userName: userName,
            timestamp: message.timestamp,
            type: "move"
        };

        scwin.lockedCards.set(message.taskId, moveLockInfo);
        scwin.updateCardMoveLockVisual(message.taskId, moveLockInfo);

        console.log("������ 카드가 이동 락되었습니다:", message.taskId, "by", userName);

    } else if (action === "MOVE_UNLOCK") {
        // ������ 이동용 언락 (신규 로직)
        var currentLock = scwin.lockedCards.get(message.taskId);

        // 이동 락만 해제 (편집 락은 유지)
        if (currentLock && currentLock.type === "move") {
            scwin.lockedCards.delete(message.taskId);
            scwin.updateCardMoveLockVisual(message.taskId, null);
            console.log("������ 카드 이동 락이 해제되었습니다:", message.taskId);
        }
    }
};

// 드래그 시작 시 호출되는 함수
scwin.handleDragStart = function (e) {
    console.log("=== 드래그 시작 ===");

    // 드래그되는 카드 정보 저장
    var cardElement = e.target;
    var taskId = cardElement.getAttribute("data-task-id");
    var currentBoardId = cardElement.getAttribute("data-board-id");

    console.log("카드 정보 추출:");
    console.log("- taskId:", taskId);
    console.log("- currentBoardId:", currentBoardId);
    console.log("- cardElement:", cardElement);

    // 필수 정보 유효성 검사
    if (!taskId || !currentBoardId) {
        console.error("필수 드래그 정보가 누락되었습니다:", { taskId: taskId, currentBoardId: currentBoardId });
        e.preventDefault();
        return false;
    }

    // 카드 락 확인 - 다른 사용자가 편집하거나 이동 중인지 체크
    if (scwin.isCardLocked(taskId)) {
        var lockInfo = scwin.lockedCards.get(taskId);
        var lockType = lockInfo.type === "move" ? "이동" : "편집";
        console.log("드래그 차단: 카드가 " + lockType + " 락되어 있습니다.", lockInfo.userName);
        $c.win.alert(lockInfo.userName + "님이 현재 이 카드를 " + lockType + " 중입니다. 잠시 후 다시 시도해주세요.");
        e.preventDefault();
        return false;
    }

    // ������ 카드 이동 락 요청 (편집 락 대신 이동 락 사용)
    if (!scwin.requestCardMoveLock(taskId)) {
        console.log("드래그 차단: 카드 이동 락 획득 실패");
        e.preventDefault();
        return false;
    }

    // 전역 변수에 드래그 정보 저장 (더 안전한 방식)
    scwin.draggedCard = {
        element: cardElement,
        taskId: taskId,
        sourceBoardId: currentBoardId,
        sourceContainer: cardElement.parentElement,
        timestamp: new Date().getTime() // 타임스탬프 추가로 신뢰성 향상
    };

    // dataTransfer에도 백업 정보 저장
    if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/html", cardElement.outerHTML);
        e.dataTransfer.setData("application/json", JSON.stringify({
            taskId: taskId,
            sourceBoardId: currentBoardId
        }));
        console.log("dataTransfer 설정 완료");
    } else {
        console.error("dataTransfer 객체가 없습니다!");
    }

    // 드래그 중 카드 스타일 변경
    cardElement.classList.add("dragging");

    // 전체 화면에 드래그 상태 클래스 추가
    document.body.classList.add("dragging-in-progress");

    console.log("드래그 데이터 설정 완료:", scwin.draggedCard);
    console.log("=== 드래그 시작 완료 ===");
};

// 드래그 종료 시 호출되는 함수
scwin.handleDragEnd = function (e) {
    console.log("드래그 종료:", e.target);

    // 드래그 스타일 원복
    e.target.classList.remove("dragging");

    // 전체 화면 드래그 상태 클래스 제거
    document.body.classList.remove("dragging-in-progress");

    // 모든 드롭 존의 하이라이트 제거
    var dropZones = document.querySelectorAll(".drop-zone");
    dropZones.forEach(function (zone) {
        zone.classList.remove("drag-over");
    });

    // ������ 드래그가 끝났으므로 카드 이동 락 해제
    if (scwin.draggedCard && scwin.draggedCard.taskId) {
        scwin.releaseCardMoveLock(scwin.draggedCard.taskId, false);
        console.log("드래그 종료: 카드 이동 락 해제:", scwin.draggedCard.taskId);
    }
};

// 드래그 상태 정리 함수
scwin.cleanupDragState = function () {
    console.log("=== 드래그 상태 정리 ===");

    // 드래그 중인 모든 요소에서 스타일 제거
    var draggingElements = document.querySelectorAll('.dragging');
    draggingElements.forEach(function (element) {
        element.classList.remove("dragging");
    });

    // 전체 드래그 상태 정리
    document.body.classList.remove("dragging-in-progress");

    // 모든 드롭 존의 하이라이트 제거
    var dropZones = document.querySelectorAll(".drop-zone, [data-drop-zone]");
    dropZones.forEach(function (zone) {
        zone.classList.remove("drag-over");
    });

    // 드래그 정보 초기화 (약간의 지연 후)
    setTimeout(function () {
        scwin.draggedCard = null;
    }, 100);
};

// 드래그 오버 이벤트 (드롭 존에서 발생)
scwin.handleDragOver = function (e) {
    console.log("드래그 오버 이벤트 상세:", e);
    console.log("currentTarget:", e.currentTarget);
    console.log("dataTransfer:", e.dataTransfer);

    // 강력한 기본 동작 방지
    if (e.preventDefault) {
        e.preventDefault();
    }
    if (e.stopPropagation) {
        e.stopPropagation();
    }

    // dataTransfer 설정
    if (e.dataTransfer) {
        e.dataTransfer.dropEffect = "move";
        console.log("dropEffect 설정:", e.dataTransfer.dropEffect);
    }

    // 드롭 존 하이라이트
    if (e.currentTarget && e.currentTarget.classList) {
        e.currentTarget.classList.add("drag-over");
        console.log("드롭 존 하이라이트 추가:", e.currentTarget.className);
    }

    return false; // 추가 방지
};

// 드래그 엔터 이벤트 (드롭 존에 진입)
scwin.handleDragEnter = function (e) {
    console.log("드래그 엔터 이벤트 발생!");
    e.preventDefault();
    e.stopPropagation();
    e.currentTarget.classList.add("drag-over");
    return false;
};

// 드래그 리브 이벤트 (드롭 존에서 벗어남)
scwin.handleDragLeave = function (e) {
    console.log("드래그 리브 이벤트 발생!");
    e.currentTarget.classList.remove("drag-over");
};


// 드롭 이벤트 (실제 드롭 처리)
scwin.handleDrop = function (e) {
    console.log("=== handleDrop 함수 호출됨 ===");
    console.log("드래그된 카드 정보:", scwin.draggedCard);

    e.preventDefault();
    e.stopPropagation();

    var dropZone = e.currentTarget;
    var targetBoardId = dropZone.getAttribute("data-board-id");

    console.log("드롭 존 정보:");
    console.log("- dropZone:", dropZone);
    console.log("- targetBoardId:", targetBoardId);

    // 드래그된 카드 정보 확인 (더 안전한 방식)
    if (!scwin.draggedCard || !scwin.draggedCard.element || !scwin.draggedCard.taskId) {
        console.error("드래그된 카드 정보가 없거나 불완전합니다.");
        console.error("현재 draggedCard:", scwin.draggedCard);

        // 1차 복구 시도: dataTransfer에서 정보 복구
        try {
            var transferData = e.dataTransfer.getData("application/json");
            if (transferData) {
                var dragInfo = JSON.parse(transferData);
                console.log("dataTransfer에서 정보 복구 시도:", dragInfo);

                // DOM에서 해당 카드 찾기
                var cardElement = document.querySelector('[data-task-id="' + dragInfo.taskId + '"]');
                if (cardElement) {
                    scwin.draggedCard = {
                        element: cardElement,
                        taskId: dragInfo.taskId,
                        sourceBoardId: dragInfo.sourceBoardId,
                        sourceContainer: cardElement.parentElement
                    };
                    console.log("dataTransfer에서 정보 복구 성공");
                }
            }
        } catch (error) {
            console.log("dataTransfer 정보 복구 실패:", error);
        }

        // 2차 복구 시도: 드래그 중인 요소에서 정보 복구
        if (!scwin.draggedCard || !scwin.draggedCard.taskId) {
            var draggedElements = document.querySelectorAll('.dragging');
            if (draggedElements.length > 0) {
                var draggedElement = draggedElements[0];
                var taskId = draggedElement.getAttribute("data-task-id");
                var sourceBoardId = draggedElement.getAttribute("data-board-id");

                if (taskId && sourceBoardId) {
                    console.log("DOM에서 드래그 정보 복구 성공:", { taskId: taskId, sourceBoardId: sourceBoardId });
                    scwin.draggedCard = {
                        element: draggedElement,
                        taskId: taskId,
                        sourceBoardId: sourceBoardId,
                        sourceContainer: draggedElement.parentElement
                    };
                }
            }
        }

        // 최종 확인: 여전히 정보가 없으면 알림
        if (!scwin.draggedCard || !scwin.draggedCard.taskId) {
            $c.win.alert("드래그된 카드 정보가 없습니다. 다시 시도해주세요.");
            scwin.cleanupDragState();
            return;
        }
    }

    var draggedElement = scwin.draggedCard.element;
    var sourceBoardId = scwin.draggedCard.sourceBoardId;
    var taskId = scwin.draggedCard.taskId;

    console.log("카드 이동:", {
        taskId: taskId,
        from: sourceBoardId,
        to: targetBoardId
    });

    // 같은 보드로 이동하는 경우 무시
    if (sourceBoardId === targetBoardId) {
        console.log("같은 보드로 이동하려고 시도했습니다. 무시합니다.");
        dropZone.classList.remove("drag-over");
        scwin.cleanupDragState();
        return;
    }

    // 카드 이동 처리
    try {
        scwin.moveCardToBoard(draggedElement, targetBoardId, taskId);

        // WebSocket으로 카드 이동 메시지 전송
        scwin.sendCardMoveMessage(taskId, sourceBoardId, targetBoardId);

        console.log("카드 이동 성공:", taskId, "->", targetBoardId);

    } catch (error) {
        console.error("카드 이동 중 오류 발생:", error);
        $c.win.alert("카드 이동 중 오류가 발생했습니다. 다시 시도해주세요.");
    }

    // 드롭 존 하이라이트 제거
    dropZone.classList.remove("drag-over");

    // 드래그 상태 정리
    scwin.cleanupDragState();
};

// 카드를 다른 보드로 이동하는 함수
scwin.moveCardToBoard = function (cardElement, targetBoardId, taskId) {
    console.log("카드 이동 처리:", {
        cardElement: cardElement,
        targetBoardId: targetBoardId,
        taskId: taskId
    });

    // 현재 보드 정보
    var sourceBoardId = cardElement.getAttribute("data-board-id");

    // 타겟 컨테이너 찾기
    var targetContainerId = "card_container_" + targetBoardId;
    var targetContainer = eval(targetContainerId);

    if (!targetContainer) {
        console.error("타겟 컨테이너를 찾을 수 없습니다:", targetContainerId);
        return;
    }

    // 카드 이동 (DOM 조작)
    try {
        targetContainer.element.appendChild(cardElement);

        // 카드의 data-board-id 업데이트
        cardElement.setAttribute("data-board-id", targetBoardId);

        // 카운트 업데이트
        scwin.updateBoardCardCounts(sourceBoardId, targetBoardId);

        console.log("카드 이동 완료:", taskId, "->", targetBoardId);

        // 이동 완료 알림 (선택사항)
        var sourceBoard = scwin.getBoardTitle(sourceBoardId);
        var targetBoard = scwin.getBoardTitle(targetBoardId);
        console.log(`카드가 "${sourceBoard}"에서 "${targetBoard}"로 이동되었습니다.`);

    } catch (error) {
        console.error("카드 이동 중 오류 발생:", error);
    }
};

// async/await를 사용한 드래그 이벤트 설정
scwin.setupDragEventsAsync = async function (cardGroup, cardData, cardId) {
    console.log("=== 드래그 이벤트 설정 시작 ===", cardId);

    try {
        // 컴포넌트 렌더링 완료 대기
        const elementOrComponent = await scwin.waitForElementReady(cardGroup);

        console.log("컴포넌트 렌더링 완료:", cardId, elementOrComponent);

        // 실제 DOM 요소 찾기 (WebSquare 컴포넌트 대응)
        let targetElement = null;

        if (elementOrComponent && elementOrComponent.element && elementOrComponent.element.nodeType === 1) {
            // 정상적인 DOM 요소가 있는 경우
            targetElement = elementOrComponent.element;
        } else if (elementOrComponent && elementOrComponent.nodeType === 1) {
            // 이미 DOM 요소인 경우
            targetElement = elementOrComponent;
        } else if (elementOrComponent && elementOrComponent.id) {
            // WebSquare 컴포넌트인 경우 - DOM에서 직접 찾기
            targetElement = document.getElementById(elementOrComponent.id);
            if (!targetElement) {
                // ID로 찾지 못한 경우 querySelector로 시도
                targetElement = document.querySelector(`[id="${elementOrComponent.id}"]`);
            }
        }

        if (!targetElement) {
            console.warn("드래그 타겟 DOM 요소를 찾을 수 없습니다:", cardId);
            return;
        }

        console.log("드래그 타겟 요소:", targetElement);

        // 속성 설정
        targetElement.setAttribute("data-task-id", cardData.taskId);
        targetElement.setAttribute("data-board-id", cardData.boardId);
        targetElement.setAttribute("draggable", "true");

        console.log("카드 속성 설정 완료:");
        console.log("- taskId:", targetElement.getAttribute("data-task-id"));
        console.log("- boardId:", targetElement.getAttribute("data-board-id"));
        console.log("- draggable:", targetElement.getAttribute("draggable"));

        // 드래그 이벤트 핸들러 바인딩
        targetElement.ondragstart = function (e) {
            console.log("드래그 시작 이벤트 발생!");
            scwin.handleDragStart(e);
        };

        targetElement.ondragend = function (e) {
            console.log("드래그 종료 이벤트 발생!");
            scwin.handleDragEnd(e);
        };




    } catch (error) {
        console.error("드래그 이벤트 설정 중 오류:", error);
    }

    console.log("=== 드래그 이벤트 설정 완료 ===", cardId);
};


// async/await를 사용한 드롭 존 설정
scwin.setupDropZoneAsync = async function (cardContainer, boardId, cardContainerId) {
    console.log("=== 드롭 존 설정 시작 ===", cardContainerId);

    try {
        // 컴포넌트 렌더링 완료 대기
        const elementOrComponent = await scwin.waitForElementReady(cardContainer);

        console.log("드롭 존 렌더링 완료:", cardContainerId, elementOrComponent);

        // DOM 요소가 있는 경우와 없는 경우 처리
        let targetElement = elementOrComponent;
        if (elementOrComponent && elementOrComponent.element) {
            targetElement = elementOrComponent.element;
        } else if (elementOrComponent && elementOrComponent.render && elementOrComponent.render.nodeType === 1) {
            // WebSquare 컴포넌트의 render 속성 사용
            targetElement = elementOrComponent.render;
            console.log("WebSquare render 속성 사용:", targetElement);
        } else if (elementOrComponent && elementOrComponent.nodeType === 1) {
            targetElement = elementOrComponent;
        } else if (elementOrComponent && elementOrComponent.id) {
            // ID로 직접 찾기
            targetElement = document.getElementById(elementOrComponent.id);
            console.log("ID로 찾은 요소:", targetElement);
        } else {
            console.warn("드롭 존 DOM 요소를 찾을 수 없습니다. 이벤트 바인딩을 건너뜁니다:", cardContainerId);
            console.log("elementOrComponent 상세 정보:", elementOrComponent);
            return;
        }

        console.log("드롭 존 타겟 요소:", targetElement);

        // 드롭 존 이벤트 핸들러 바인딩 (WebSquare 호환성을 위해 혼합 방식 사용)

        // 1. dragover 이벤트 - 다중 바인딩 방식
        var dragoverHandler = function (e) {
            console.log("드래그 오버 이벤트 발생!", e.type);
            console.log("드래그 오버 타겟:", e.target);
            console.log("드래그 오버 현재타겟:", e.currentTarget);

            // 강력한 기본 동작 방지
            if (e.preventDefault) {
                e.preventDefault();
            }
            if (e.stopPropagation) {
                e.stopPropagation();
            }

            // dataTransfer 설정
            if (e.dataTransfer) {
                e.dataTransfer.dropEffect = "move";
                console.log("dropEffect 설정:", e.dataTransfer.dropEffect);
            }

            // 비주얼 피드백
            if (e.currentTarget && e.currentTarget.classList) {
                e.currentTarget.classList.add("drag-over");
            }

            return false;
        };

        // addEventListener 방식
        targetElement.addEventListener('dragover', dragoverHandler, false);

        // 직접 속성 설정 방식
        targetElement.ondragover = dragoverHandler;

        // 캡처 단계 리스너
        targetElement.addEventListener('dragover', dragoverHandler, true);

        // 2. 드롭 이벤트 - 다중 바인딩 방식
        var dropHandler = function (e) {
            console.log("=== 드롭 이벤트 발생 ===");
            console.log("이벤트 객체:", e);
            console.log("타겟 요소:", e.target);
            console.log("현재 타겟:", e.currentTarget);
            console.log("handleDrop 함수 존재 여부:", typeof scwin.handleDrop);

            e.preventDefault();
            e.stopPropagation();

            // 즉시 실행과 지연 실행 둘 다 시도
            try {
                console.log("handleDrop 즉시 호출 시도");
                scwin.handleDrop(e);
                console.log("handleDrop 즉시 호출 완료");
            } catch (error) {
                console.error("handleDrop 즉시 호출 실패:", error);

                // 지연 실행 시도
                setTimeout(function () {
                    console.log("handleDrop 지연 호출 시도");
                    try {
                        scwin.handleDrop(e);
                        console.log("handleDrop 지연 호출 완료");
                    } catch (delayedError) {
                        console.error("handleDrop 지연 호출도 실패:", delayedError);
                    }
                }, 10);
            }
            return false;
        };

        // addEventListener 방식
        targetElement.addEventListener('drop', dropHandler);

        // 직접 속성 설정 방식 (WebSquare 호환성)
        targetElement.ondrop = dropHandler;

        // 3. dragenter 이벤트 - 다중 바인딩 방식
        var dragenterHandler = function (e) {
            console.log("드래그 엔터 이벤트 발생!", e.type);
            e.preventDefault();
            e.stopPropagation();
            if (e.currentTarget && e.currentTarget.classList) {
                e.currentTarget.classList.add("drag-over");
            }
            return false;
        };

        targetElement.addEventListener('dragenter', dragenterHandler, false);
        targetElement.ondragenter = dragenterHandler;
        targetElement.addEventListener('dragenter', dragenterHandler, true);

        // 4. dragleave 이벤트
        var dragleaveHandler = function (e) {
            console.log("드래그 리브 이벤트 발생!", e.type);
            if (e.currentTarget && e.currentTarget.classList) {
                e.currentTarget.classList.remove("drag-over");
            }
        };

        targetElement.addEventListener('dragleave', dragleaveHandler, false);
        targetElement.ondragleave = dragleaveHandler;

        console.log("드롭 존 이벤트 핸들러 바인딩 완료:", cardContainerId);

        // WebSquare 환경 전용 설정
        targetElement.setAttribute("data-drop-zone", "true");
        targetElement.setAttribute("data-board-id", boardId);

        // 강제로 드롭 존 CSS 스타일 적용
        targetElement.style.pointerEvents = "auto";

        // 직접 HTML 속성으로 이벤트 핸들러 설정 (WebSquare 호환)
        targetElement.setAttribute("ondragover", "event.preventDefault(); event.dataTransfer.dropEffect='move'; return false;");
        targetElement.setAttribute("ondrop", "event.preventDefault(); scwin.handleDrop(event); return false;");

        targetElement.setAttribute("data-drop-handler", "ready");

        // 강제 이벤트 캡처 설정 (WebSquare 호환성)
        targetElement.addEventListener('drop', dropHandler, true); // 캡처 단계

        // 추가적인 드롭 이벤트 감지 방법 (WebSquare 환경 대응)
        targetElement.setAttribute('onDrop', 'scwin.handleDrop(event)');

        // 전역 이벤트 리스너로 백업 (최후 수단)
        if (!window.globalDropBackup) {
            window.globalDropBackup = true;
            document.addEventListener('drop', function (e) {
                console.log("전역 드롭 이벤트 발생 - 상세 분석:", e.target);

                var dropZone = e.target.closest('[data-drop-zone="true"]');
                console.log("가장 가까운 드롭존:", dropZone);

                if (dropZone) {
                    console.log("전역 드롭 이벤트 백업 핸들러 동작:", e.target);
                    var targetBoardId = dropZone.getAttribute('data-board-id');
                    console.log("타겟 보드 ID:", targetBoardId);
                    console.log("드롭존의 모든 속성:", dropZone.attributes);

                    // 속성 값이 없어도 진행 (디버깅용)
                    if (targetBoardId || true) {
                        e.preventDefault();
                        e.stopPropagation();
                        console.log("전역 백업에서 scwin.handleDrop 직접 호출 시도");
                        console.log("scwin.handleDrop 함수 타입:", typeof scwin.handleDrop);

                        if (typeof scwin.handleDrop === 'function') {
                            console.log("전역 백업에서 scwin.handleDrop 호출 시작");
                            // 이벤트 객체 수정
                            var modifiedEvent = {
                                preventDefault: function () { if (e.preventDefault) e.preventDefault(); },
                                stopPropagation: function () { if (e.stopPropagation) e.stopPropagation(); },
                                currentTarget: dropZone,
                                target: e.target,
                                type: 'drop',
                                dataTransfer: e.dataTransfer
                            };
                            scwin.handleDrop(modifiedEvent);
                            console.log("전역 백업에서 scwin.handleDrop 호출 완료");
                        } else {
                            console.error("scwin.handleDrop 함수를 찾을 수 없습니다!");
                            console.log("scwin 객체:", scwin);
                            console.log("scwin의 모든 메소드:", Object.getOwnPropertyNames(scwin));
                        }
                    } else {
                        console.log("타겟 보드 ID가 없습니다.");
                    }
                } else {
                    console.log("드롭존을 찾을 수 없습니다.");
                }
            }, true);
        }
        targetElement.addEventListener('drop', dropHandler, true); // 캡처 단계에서도 리스너 추가

    } catch (error) {
        console.error("드롭 존 설정 중 오류:", error);
    }

    console.log("=== 드롭 존 설정 완료 ===", cardContainerId);
};

// ==================== 드래그 앤 드롭 이벤트 핸들러들 ====================


// 카드를 다른 보드로 이동하는 함수 (WebSquare 환경 호환)
scwin.moveCardToBoard = function (cardElement, targetBoardId, taskId) {
    console.log("카드 이동 처리:", {
        cardElement: cardElement,
        targetBoardId: targetBoardId,
        taskId: taskId
    });

    try {
        // taskId 검증 및 복구 시도
        if (!taskId || taskId === "" || taskId === "null" || taskId === "undefined") {
            console.warn("taskId가 유효하지 않습니다. 카드 element에서 추출을 시도합니다.");

            // 카드 element에서 taskId 다시 추출 시도
            taskId = cardElement.getAttribute("data-task-id");

            if (!taskId || taskId === "" || taskId === "null" || taskId === "undefined") {
                console.error("카드 element에서도 taskId를 찾을 수 없습니다. 이동을 중단합니다.");
                $c.win.alert("카드 정보를 찾을 수 없어 이동할 수 없습니다.");
                return false;
            }

            console.log("카드 element에서 taskId 복구 성공:", taskId);
        }

        // 현재 보드 정보
        var sourceBoardId = cardElement.getAttribute("data-board-id");
        console.log("소스 보드 ID:", sourceBoardId);

        // 같은 보드로 이동하는 경우 처리하지 않음
        if (sourceBoardId === targetBoardId) {
            console.log("같은 보드로 이동하려고 시도함. 처리 중단.");
            return true;
        }

        // 타겟 컴포넌트 찾기
        var targetContainerId = "card_container_" + targetBoardId;
        console.log("타겟 컴포넌트 ID:", targetContainerId);

        // WebSquare 컴포넌트 찾기
        var targetContainer = eval(targetContainerId);
        if (!targetContainer) {
            console.error("타겟 컴포넌트를 찾을 수 없습니다:", targetContainerId);
            return false;
        }

        console.log("타겟 컴포넌트 찾기 성공:", targetContainer);

        // WebSquare 컴포넌트의 DOM 요소 찾기
        var targetDOMElement = null;
        if (targetContainer.element && targetContainer.element.nodeType === 1) {
            targetDOMElement = targetContainer.element;
        } else if (targetContainer.render && targetContainer.render.nodeType === 1) {
            targetDOMElement = targetContainer.render;
        } else {
            // ID로 직접 찾기
            targetDOMElement = document.getElementById(targetContainerId);
        }

        if (!targetDOMElement) {
            console.error("타겟 DOM 요소를 찾을 수 없습니다:", targetContainerId);
            return false;
        }

        console.log("타겟 DOM 요소 찾기 성공:", targetDOMElement);

        // 서버에 먼저 업데이트 요청
        console.log("서버에 태스크 보드 업데이트 요청:", taskId, "->", targetBoardId);
        dm_taskVo.set("taskId", taskId);
        dm_taskVo.set("boardId", targetBoardId);

        // 비동기 서버 업데이트를 위한 콜백 설정
        scwin.pendingCardMove = {
            cardElement: cardElement,
            sourceBoardId: sourceBoardId,
            targetBoardId: targetBoardId,
            targetDOMElement: targetDOMElement,
            taskId: taskId
        };

        // 서버 업데이트 실행
        $c.sbm.execute(update_task_board);

        return true;

    } catch (error) {
        console.error("카드 이동 중 오류 발생:", error);
        return false;
    }
};

// 태스크 보드 업데이트 성공 콜백
scwin.update_task_board_submitdone = function (e) {
    console.log("서버 태스크 보드 업데이트 성공:", e);

    try {
        // 대기 중인 카드 이동 정보 확인
        if (!scwin.pendingCardMove) {
            console.error("대기 중인 카드 이동 정보가 없습니다.");
            return;
        }

        var moveInfo = scwin.pendingCardMove;
        console.log("서버 업데이트 성공 후 DOM 업데이트 실행:", moveInfo.taskId);

        // DOM 업데이트 실행
        moveInfo.targetDOMElement.appendChild(moveInfo.cardElement);

        // 카드의 data-board-id 업데이트
        moveInfo.cardElement.setAttribute("data-board-id", moveInfo.targetBoardId);

        // 카운트 업데이트
        scwin.updateBoardCardCounts(moveInfo.sourceBoardId, moveInfo.targetBoardId);

        // allTasksData 로컬 캐시 업데이트
        scwin.updateLocalTaskCache(moveInfo.taskId, moveInfo.targetBoardId);

        // 이동 완료 알림
        var sourceBoard = scwin.getBoardTitle(moveInfo.sourceBoardId);
        var targetBoard = scwin.getBoardTitle(moveInfo.targetBoardId);
        console.log(`카드가 "${sourceBoard}"에서 "${targetBoard}"로 이동되었습니다.`);

        // WebSocket을 통해 다른 사용자에게 알림
        if (scwin.isWebSocketConnected) {
            scwin.sendWebSocketMessage({
                type: "CARD_MOVED",
                taskId: moveInfo.taskId,
                fromBoardId: moveInfo.sourceBoardId,
                toBoardId: moveInfo.targetBoardId,
                timestamp: Date.now()
            });
        }

        // 대기 정보 초기화
        scwin.pendingCardMove = null;

        console.log("카드 이동 완료 (서버+DOM 동기화):", moveInfo.taskId);

    } catch (error) {
        console.error("서버 업데이트 성공 후 DOM 업데이트 중 오류:", error);
        // 에러가 발생해도 대기 정보는 초기화
        scwin.pendingCardMove = null;
    }
};

// 태스크 보드 업데이트 실패 콜백
scwin.update_task_board_submiterror = function (e) {
    console.error("서버 태스크 보드 업데이트 실패:", e);

