    }
};

// 로컬 캐시에서 태스크 정보 업데이트
scwin.updateLocalTaskCache = function (taskId, newBoardId) {
    try {
        if (!scwin.allTasksData) {
            scwin.allTasksData = {};
        }

        var movedTask = null;
        var sourceBoardId = null;

        // 모든 보드의 캐시에서 해당 태스크를 찾아서 제거
        for (var boardId in scwin.allTasksData) {
            if (scwin.allTasksData.hasOwnProperty(boardId)) {
                var tasks = scwin.allTasksData[boardId];
                for (var i = 0; i < tasks.length; i++) {
                    if (tasks[i].taskId === taskId) {
                        movedTask = tasks[i];
                        sourceBoardId = boardId;

                        // 기존 보드에서 제거 (다른 보드로 이동하는 경우에만)
                        if (boardId !== newBoardId) {
                            tasks.splice(i, 1);
                            console.log(`로컬 캐시에서 태스크 제거: ${taskId} from ${boardId}`);
                        }
                        break;
                    }
                }
                if (movedTask) break;
            }
        }

        // 태스크를 찾았고 다른 보드로 이동하는 경우
        if (movedTask && sourceBoardId !== newBoardId) {
            // 태스크의 boardId 업데이트
            movedTask.boardId = newBoardId;

            // 새 보드 캐시에 추가
            if (!scwin.allTasksData[newBoardId]) {
                scwin.allTasksData[newBoardId] = [];
            }
            scwin.allTasksData[newBoardId].push(movedTask);
            console.log(`로컬 캐시에 태스크 추가: ${taskId} to ${newBoardId}`);

            // 변경된 보드들의 화면 업데이트
            scwin.sortAndFilterBoardTasks(sourceBoardId);
            scwin.sortAndFilterBoardTasks(newBoardId);
        }

        console.log("로컬 캐시 업데이트 완료:", taskId, "->", newBoardId);

    } catch (error) {
        console.error("로컬 캐시 업데이트 중 오류:", error);
    }
};

// 보드별 카드 카운트 업데이트
scwin.updateBoardCardCounts = function (sourceBoardId, targetBoardId) {
    try {
        // 소스 보드 카운트 감소
        var sourceCountSpan = eval("grp_dynamic_" + sourceBoardId + "_count");
        if (sourceCountSpan) {
            var currentCount = parseInt(sourceCountSpan.getValue() || "0");
            sourceCountSpan.setValue(Math.max(0, currentCount - 1));
        }

        // 타겟 보드 카운트 증가
        var targetCountSpan = eval("grp_dynamic_" + targetBoardId + "_count");
        if (targetCountSpan) {
            var currentCount = parseInt(targetCountSpan.getValue() || "0");
            targetCountSpan.setValue(currentCount + 1);
        }

        console.log("보드 카운트 업데이트 완료:", sourceBoardId, "->", targetBoardId);
    } catch (error) {
        console.error("보드 카운트 업데이트 중 오류:", error);
    }
};

// 보드 ID로 보드 제목 가져오기 (유틸리티 함수)
scwin.getBoardTitle = function (boardId) {
    try {
        var boardList = dlt_boardListVo.getAllJSON();
        var board = boardList.find(function (item) {
            return item.boardId === boardId;
        });
        return board ? board.boardTitle : "알 수 없음";
    } catch (error) {
        console.error("보드 제목 조회 중 오류:", error);
        return "알 수 없음";
    }
};

/**
 * 보드 제목에 따른 상태 색상 반환
 * @param {String} boardTitle - 보드 제목
 * @returns {String} 색상 코드
 */
scwin.getBoardStatusColor = function (boardTitle) {
    // boardTitle null 체크
    if (!boardTitle || typeof boardTitle !== 'string') {
        return '#656d76'; // 기본 회색
    }

    var title = boardTitle.toLowerCase();

    if (title.includes('할 일') || title.includes('todo')) {
        return '#fb8500'; // 주황색
    } else if (title.includes('진행') || title.includes('progress') || title.includes('진행중')) {
        return '#d4af37'; // 금색
    } else if (title.includes('완료') || title.includes('done') || title.includes('완성')) {
        return '#1f883d'; // 녹색
    } else {
        return '#656d76'; // 기본 회색
    }
};

/**
 * 동적 Add Card 버튼 클릭 핸들러
 */
scwin.dynamicAddCard_onclick_fixed = function (boardId) {
    console.log("Add Card 버튼 클릭, boardId:", boardId);

    if (boardId) {
        // 해당 보드의 카드 컨테이너 찾기
        var cardContainerId = "card_container_" + boardId;
        var parentGroup = eval(cardContainerId);

        if (!parentGroup) {
            console.error("카드 컨테이너를 찾을 수 없습니다:", cardContainerId);
            $c.win.alert("카드 컨테이너를 찾을 수 없습니다.");
            return;
        }

        console.log("카드 생성 대상 컨테이너:", cardContainerId);

        // 동적 카드와 input 생성
        var cardId = "dyn_card_" + new Date().getTime();
        var cardOptions = {
            className: "project-card",
            style: "border-color: #2da44e; background-color: #f6ffed;"
        };
        var newCard = $p.dynamicCreate(cardId, "group", cardOptions, parentGroup);

        if (newCard) {
            // 동적 input 생성
            var inputId = "dyn_input_" + new Date().getTime();
            var newInput = $p.dynamicCreate(inputId, "input", {
                placeholder: "새 작업명을 입력하세요.",
                style: "width: 100%; height: 24px;"
            }, newCard);

            if (newInput) {
                // boardId를 input의 data 속성에 저장 (WebSquare 호환)
                newInput.setUserData("boardId", boardId);

                // 키보드 이벤트 바인딩 시 boardId를 클로저로 전달
                newInput.bind("onkeydown", function (e) {
                    scwin.dynamicInput_onkeydown_with_board.call(this, e, boardId);
                });

                // input에 포커스
                newInput.focus();

                console.log("동적 input 생성 및 포커스 설정 완료, boardId:", boardId);
            } else {
                console.error("input 생성 실패");
                newCard.remove();
            }
        } else {
            console.error("카드 생성 실패");
        }
    }
    else {
        console.error("boardId가 없습니다.");
        $c.win.alert("보드 정보를 찾을 수 없습니다.");
    }
};

/**
 * 동적 input 키보드 이벤트 핸들러 (boardId 포함)
 */
scwin.dynamicInput_onkeydown_with_board = function (e, boardId) {
    var inputComponent = this;
    var keyCode = e.keyCode;

    // boardId 가져오기 (파라미터 우선, 없으면 userData에서 가져오기)
    var targetBoardId = boardId || inputComponent.getUserData("boardId");

    console.log("키 입력:", keyCode, "값:", inputComponent.getValue(), "boardId:", targetBoardId);

    if (keyCode === 13) { // Enter 키
        var input = inputComponent.getValue();
        if (input && input.trim()) {
            console.log("Enter 키 - 태스크 생성:", input.trim(), "boardId:", targetBoardId);

            if (!targetBoardId) {
                console.error("boardId를 찾을 수 없습니다.");
                $c.win.alert("보드 정보를 찾을 수 없습니다.");
                return;
            }

            // dm_taskVo에 데이터 설정
            dm_taskVo.set("taskTitle", input.trim());
            dm_taskVo.set("boardId", targetBoardId);

            // 태스크 생성 API 호출
            $p.executeSubmission("add_task");

            // input 카드 제거
            var cardComponent = inputComponent.getParent();
            if (cardComponent) {
                cardComponent.remove();
            }
        } else {
            $c.win.alert("작업명을 입력해주세요.");
        }
    } else if (keyCode === 27) { // ESC 키
        console.log("ESC 키 - 취소");

        // 카드 제거
        var cardComponent = inputComponent.getParent();
        if (cardComponent) {
            cardComponent.remove();
        }
    }
};

/**
 * 보드 로드 서브미션 전 처리 함수
 */
scwin.load_Board_submit = function (e) {
    console.log("보드 데이터 로드 요청 시작");

    // 프로젝트 ID 확인
    var projectId = dm_projectVo.get("projectId");
