        // scwin.currentProjectData에서 프로젝트 ID를 찾아보기
        if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
            console.log("currentProjectData에서 프로젝트 ID 복구:", scwin.currentProjectData.projectId);
            dm_projectVo.set("projectId", scwin.currentProjectData.projectId);
            projectId = scwin.currentProjectData.projectId;
        } else {
