//task 버튼 눌렀을 때 
scwin.new_task_onclick = function (e) {
    // 클릭된 카드에서 taskId와 projectId 추출
    var taskId = null;
    var projectId = null;

    if (e && e.target) {
        // 클릭된 요소나 부모 요소에서 data-task-id 찾기
        var currentElement = e.target;
        while (currentElement && !taskId) {
            if (currentElement.getAttribute && currentElement.getAttribute("data-task-id")) {
                taskId = currentElement.getAttribute("data-task-id");
                break;
            }
            currentElement = currentElement.parentElement;
        }
    }

    // 프로젝트 ID 가져오기
    if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
        projectId = scwin.currentProjectData.projectId;
    }

    // 보드 타이틀 가져오기
    var boardTitle = "알 수 없음";
    if (e && e.target) {
        var currentElement = e.target;
        while (currentElement && boardTitle === "알 수 없음") {
            if (currentElement.getAttribute && currentElement.getAttribute("data-board-id")) {
                var boardId = currentElement.getAttribute("data-board-id");
                boardTitle = scwin.getBoardTitle(boardId);
                break;
            }
            currentElement = currentElement.parentElement;
        }
    }

    // 프로젝트 이름 가져오기
    var projectName = "프로젝트";
    if (scwin.currentProjectData && scwin.currentProjectData.projectName) {
        projectName = scwin.currentProjectData.projectName;
    }

    // 팝업 이름 동적 생성
    var popupName = projectName + " / " + boardTitle;

    console.log("모달 열기 - taskId:", taskId, "projectId:", projectId, "popupName:", popupName);

    // 사용자 정보 가져오기 (안전한 방법으로)
    var userId = scwin.getCurrentUserId();
    if (!userId) {
        console.error("사용자 정보를 가져올 수 없어 태스크 생성이 불가능합니다.");
        $c.win.alert("로그인 정보를 확인할 수 없습니다. 페이지를 새로고침해주세요.");
        return;
    }

    var userName = userId; // userId를 userName으로 사용
    var userImage = "/InsWebApp/images/default-avatar.png"; // 기본 아바타 이미지

    console.log("태스크 생성을 위한 사용자 정보:", {
        userId: userId,
        userName: userName,
        userImage: userImage
    });

    var param = {
        "type": "json",
        "name": "userInfo",
        "data": {
            "userId": userId,
            "userName": userName,
            "userImage": userImage,
            "taskId": taskId,
            "projectId": projectId
        }
    };

    // 팝업 생성 옵션 지정
    var options = {
        id: "exa_popup",
        type: "wframePopup",
        width: "1350",
        height: "800",
        top: "115",
        left: "330",
        popupName: popupName,
        modal: false,
        closeAction: "scwin.popup_closeAction",
        customTitleBar: false,
        dataObject: param
    };

    // 팝업 생성
    $p.openPopup("/InsWebApp/ui/project/taskModal.xml", options);

};

