// 화상통화 버튼 클릭 이벤트
scwin.btn_videoCall_onclick = function (e) {
    // 1. 고유 팝업 ID 생성
    var uniquePopupId = scwin.generateVideoChatPopupId();
    console.log("생성된 고유 팝업 ID:", uniquePopupId);

    // 2. 현재 화상통화 팝업 ID를 전역 변수에 저장 (닫기 시 사용)
    scwin.currentVideoChatPopupId = uniquePopupId;

    // 3. 프로젝트 ID 가져오기
    var projectId = null;

    // 첫 번째 방법: currentProjectData에서 가져오기
    if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
        projectId = scwin.currentProjectData.projectId;
    }

    // 두 번째 방법: dm_projectVo에서 가져오기
    if (!projectId) {
        try {
            projectId = dm_projectVo.get("projectId");
        } catch (e) {
            console.log("dm_projectVo에서 projectId 가져오기 실패:", e);
        }
    }

    // 세 번째 방법: URL 파라미터에서 가져오기
    if (!projectId) {
        var urlParams = new URLSearchParams(window.location.search);
        projectId = urlParams.get('projectId');
    }

    if (!projectId) {
        $c.win.alert("프로젝트 ID를 찾을 수 없습니다.");
        console.error("프로젝트 ID를 찾을 수 없습니다.");
        return;
    }

    console.log("화상통화 모달 시작 - 프로젝트 ID:", projectId);

    // 프로젝트 설정과 동일한 방식으로 파라미터 구성
    var param = {
        "type": "json",
        "name": "projectInfo",
        "data": {
            "projectId": projectId
        }
    };

    // 기본 모달 옵션 설정 (동적 ID 사용)
    var options = {
        id: uniquePopupId,  // 동적 생성된 고유 ID 사용
        type: "wframePopup",
        width: "1920",      // 고정 크기로 테스트
        height: "940",
        left: "0",
        modal: false,
        header: false,
        customTitleBar: false,
        scrollbars: false,
        overflow: "hidden",
        closeAction: "scwin.videoChat_closeAction",
        dataObject: param
    };

    // 4. 100ms 대기 후 화상통화 팝업 열기 (DOM 정리 완료 대기)
    setTimeout(function () {
        $p.openPopup("/InsWebApp/ui/videochat/webRTCVideoChatPage.xml", options);
    }, 100);
};

// 화상통화 팝업 닫기 액션
scwin.videoChat_closeAction = function () {
    console.log("화상통화 팝업 닫기");
    // 동적 생성된 팝업 ID로 닫기
    if (scwin.currentVideoChatPopupId) {
        console.log("동적 팝업 ID로 닫기:", scwin.currentVideoChatPopupId);
        $p.closePopup(scwin.currentVideoChatPopupId);
        scwin.currentVideoChatPopupId = null; // ID 초기화
    } else {
        // 기존 방식으로 fallback
        console.log("기존 방식으로 팝업 닫기");
        $p.closePopup("videoChatPopup");
    }
};

// 화상통화 모달 닫기 함수 (자식 페이지에서 호출용)
scwin.closeVideoChatModal = function (isPipMode) {
    console.log("자식 페이지에서 화상통화 모달 닫기 요청", isPipMode ? "(PIP 모드)" : "(일반 모드)");

    // PIP 모드일 때는 모달만 닫고 화상통화는 유지
    if (isPipMode || scwin.isPipModeActive) {
        console.log("PIP 모드 - 모달만 닫고 화상통화 유지");
        scwin.isPipModeActive = true; // PIP 모드 활성화 표시

        // PIP 모드에서는 간단하게 모달만 닫기
        if (scwin.currentVideoChatPopupId) {
            $p.closePopup(scwin.currentVideoChatPopupId);
        } else {
            $p.closePopup("videoChatPopup");
        }
        return; // 화상통화 종료 없이 여기서 끝
    }

    console.log("일반 모드 - 화상통화 완전 종료");

    // 방법 1: 동적 ID로 정상적인 closePopup 호출
    if (scwin.currentVideoChatPopupId) {
        console.log("동적 팝업 ID로 모달 닫기:", scwin.currentVideoChatPopupId);
        $p.closePopup(scwin.currentVideoChatPopupId);
        scwin.currentVideoChatPopupId = null;
    } else {
        // fallback
        $p.closePopup("videoChatPopup");
    }

    // 방법 2: 강제 DOM 제거
    setTimeout(function () {
        try {
            console.log("강제 DOM 제거 시도");
            var selectors = [
                '#videoChatPopup',
                '[id*="videoChatPopup"]',
                '[id*="popup"][id*="video"]',
                '[id*="mf_wfr_mainContent_videoChatPopup"]',
                '.w2popup_window',
                '.wframe_popup'
            ];

            selectors.forEach(function (selector) {
                var elements = document.querySelectorAll(selector);
                elements.forEach(function (element) {
                    console.log("팝업 요소 발견 및 제거:", selector);
                    element.remove();
                });
            });

            // 백드롭 제거
            var backdrop = document.querySelector('.w2popup_backdrop');
            if (backdrop) {
                backdrop.remove();
                console.log("백드롭 제거 완료");
            }

        } catch (e) {
            console.error("강제 DOM 제거 실패:", e);
        }

        // 화상통화 모달이 완전히 닫힌 후 다른 팝업들의 헤더 복원
        setTimeout(function() {
            try {
                console.log("다른 팝업들의 헤더 복원 시작");

                // 모든 WebSquare 팝업 헤더를 다시 표시
                var allHeaders = document.querySelectorAll('.w2window_header');
                for (var i = 0; i < allHeaders.length; i++) {
                    var header = allHeaders[i];
                    // 화상통화 팝업이 아닌 헤더들만 복원
                    if (!header.closest('[id*="videoChatPopup"]')) {
                        header.style.display = '';
                        header.style.height = '';
                        header.style.minHeight = '';
                        header.style.visibility = '';
                    }
                }

                // 추가로 WebSquare 기본 헤더 스타일 복원
                var popupHeaders = document.querySelectorAll('.w2popup_window .w2window_header');
                for (var j = 0; j < popupHeaders.length; j++) {
                    var popupHeader = popupHeaders[j];
                    // 화상통화 팝업이 아닌 헤더들만 복원
                    if (!popupHeader.closest('[id*="videoChatPopup"]')) {
                        popupHeader.style.display = '';
                        popupHeader.style.height = '';
                        popupHeader.style.minHeight = '';
                        popupHeader.style.visibility = '';
                    }
                }

                console.log("다른 팝업들의 헤더 복원 완료");
            } catch (error) {
                console.error("헤더 복원 중 오류:", error);
            }
        }, 200);

    }, 100);
};

// PIP 상태 저장을 위한 전역 변수
scwin.pipVideoState = null;
scwin.isPipModeActive = false; // PIP 모드 활성화 상태
scwin.originalModalInfo = null; // 원래 모달 크기/위치 저장

// 모달을 PIP 크기로 축소하는 함수
scwin.resizeModalToPip = function () {
    console.log("모달 PIP 크기 축소 시작");
    scwin.isPipModeActive = true;

    try {
        // 현재 활성화된 화상통화 모달 찾기
        const modalSelectors = [
            '[id*="videoChatPopup"]',
            '[id*="mf_wfr_mainContent_videoChatPopup"]'
        ];

        let modalElement = null;
        for (const selector of modalSelectors) {
            const elements = document.querySelectorAll(selector);
            for (const element of elements) {
                if (element.style.display !== 'none' && element.offsetWidth > 0) {
                    modalElement = element;
                    break;
                }
            }
            if (modalElement) break;
        }

        if (modalElement) {
            // 원래 크기/위치 저장 (복원용)
            scwin.originalModalInfo = {
                width: modalElement.style.width || modalElement.offsetWidth + 'px',
                height: modalElement.style.height || modalElement.offsetHeight + 'px',
                left: modalElement.style.left || '',
                top: modalElement.style.top || '',
                position: modalElement.style.position || ''
            };

            // PIP 크기/위치로 변경
            modalElement.style.setProperty('width', '320px', 'important');
            modalElement.style.setProperty('height', '240px', 'important');
            modalElement.style.setProperty('position', 'fixed', 'important');
            modalElement.style.setProperty('bottom', '20px', 'important');
            modalElement.style.setProperty('right', '20px', 'important');
            modalElement.style.setProperty('top', 'auto', 'important');
            modalElement.style.setProperty('left', 'auto', 'important');
            modalElement.style.setProperty('z-index', '999999', 'important');

            console.log("✅ 모달 PIP 크기로 축소 완료:", modalElement.id);

            // PIP 확대 버튼 추가
            scwin.addPipExpandButton(modalElement);

        } else {
            console.error("활성화된 화상통화 모달을 찾을 수 없음");
        }

    } catch (error) {
        console.error("모달 PIP 축소 실패:", error);
    }
};

// PIP 확대 버튼 추가
scwin.addPipExpandButton = function (modalElement) {
    // 기존 확대 버튼이 있으면 제거
    const existingBtn = modalElement.querySelector('.pip-expand-btn');
    if (existingBtn) existingBtn.remove();

    // 확대 버튼 생성
    const expandBtn = document.createElement('button');
    expandBtn.className = 'pip-expand-btn';
    expandBtn.innerHTML = '⛶';
    expandBtn.style.cssText = `
        position: absolute !important;
        top: 5px !important;
        right: 25px !important;
        width: 20px !important;
        height: 20px !important;
        background: #FFB823 !important;
        border: none !important;
        border-radius: 3px !important;
        color: white !important;
        font-size: 12px !important;
        cursor: pointer !important;
        z-index: 1000000 !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
    `;

    // 확대 버튼 클릭 이벤트
    expandBtn.addEventListener('click', function () {
        scwin.expandModalFromPip();
    });

    modalElement.appendChild(expandBtn);
    console.log("✅ PIP 확대 버튼 추가 완료");
};

// PIP에서 모달 확대 복원
scwin.expandModalFromPip = function () {
    console.log("PIP에서 모달 확대 시작");
    scwin.isPipModeActive = false;

    try {
        // resizeModalToPip와 동일한 방식으로 모달 요소 찾기
        const modalSelectors = [
            '[id*="videoChatPopup"]',
            '[id*="mf_wfr_mainContent_videoChatPopup"]'
        ];

        let modalElement = null;
        for (const selector of modalSelectors) {
            const elements = document.querySelectorAll(selector);
            for (const element of elements) {
                if (element.style.display !== 'none' && element.offsetWidth > 0) {
                    modalElement = element;
                    break;
                }
            }
            if (modalElement) break;
        }

        if (modalElement) {
            // 정확한 원래 크기로 복원 (1920x940)
            modalElement.style.setProperty('width', '1920px', 'important');
            modalElement.style.setProperty('height', '940px', 'important');
            modalElement.style.setProperty('position', 'absolute', 'important');
            modalElement.style.setProperty('left', '0px', 'important');
            modalElement.style.setProperty('top', '0px', 'important');
            modalElement.style.setProperty('bottom', 'auto', 'important');
            modalElement.style.setProperty('right', 'auto', 'important');
            modalElement.style.setProperty('z-index', '999999', 'important');

            // 확대 버튼 제거
            const expandBtn = modalElement.querySelector('.pip-expand-btn');
            if (expandBtn) expandBtn.remove();

            console.log("✅ 모달 확대 복원 완료 (1920x940):", modalElement.id);

            // 자식 창에 복원 알림
            const iframe = modalElement.querySelector('iframe');
            if (iframe && iframe.contentWindow) {
                iframe.contentWindow.postMessage({
                    action: 'restoreFromPip'
                }, '*');
            }

        } else {
            console.error("활성화된 화상통화 모달을 찾을 수 없음");
        }

    } catch (error) {
        console.error("모달 확대 복원 실패:", error);
    }
};

// PostMessage 이벤트 리스너 추가 (자식 창에서 보낸 메시지 처리)
window.addEventListener('message', function (event) {

    // PIP 창 생성 요청 처리
    if (event.data && event.data.action === 'createPipWindow') {
        // console.log("PIP 창 생성 요청 받음");
        scwin.createPipWindow(event.data.videoState);
        return;
    }

    // 화상통화 상태 저장 요청 처리
    if (event.data && event.data.action === 'saveVideoChatState') {
        // console.log("화상통화 상태 저장 요청 받음");
        scwin.pipVideoState = event.data.state;
        return;
    }

    // 모달 PIP 크기 축소 요청 처리
    if (event.data && event.data.action === 'resizeModalToPip') {
        // console.log("������ PostMessage 수신 - 모달 PIP 크기 축소 요청 받음");
        // console.log('수신된 데이터:', event.data);
        // console.log('event.origin:', event.origin);
        // console.log('event.source:', event.source);

        try {
            // 즉시 실행
            scwin.resizeModalToPip();
            console.log('✅ 모달 PIP 축소 완료');

            // 추가로 짧은 지연 후 한 번 더 실행 (안전장치)
            setTimeout(() => {
                // console.log('������ PIP 축소 안전장치 실행');
                scwin.resizeModalToPip();
            }, 50);

        } catch (error) {
            console.error('❌ 모달 PIP 축소 실패:', error);
        }
        return;
    }

    // 모달 PIP에서 확대 복원 요청 처리
    if (event.data && event.data.action === 'expandModalFromPip') {
        console.log("������ PostMessage 수신 - 모달 PIP에서 확대 복원 요청 받음");
        console.log('수신된 데이터:', event.data);

        try {
            scwin.expandModalFromPip();
            console.log('✅ 모달 확대 복원 완료');
        } catch (error) {
            console.error('❌ 모달 확대 복원 실패:', error);
        }
        return;
    }

    // 화상통화 모달 재열기 요청 처리
    if (event.data && event.data.action === 'reopenVideoChatPopup') {
        console.log("화상통화 모달 재열기 요청 받음");
        scwin.isPipModeActive = false; // PIP 모드 해제
        // 화상통화 버튼 클릭과 동일한 동작 수행
        scwin.btn_videoCall_onclick();
        return;
    }

    if (event.data && event.data.action === 'closeVideoChatPopup') {
        // PIP 모드와 일반 모드 구분 처리
        if (event.data.isPipMode) {
            console.log("PIP 모드 - 모달만 닫기 (화상통화 유지)");
            scwin.isPipModeActive = true; // PIP 모드 활성화

            // PIP 모드에서는 모달만 숨기기 (DOM 제거하지 않음)
            try {
                console.log("PIP - 모달 숨기기 시작 (DOM 유지)");

                // 방법 1: 모달 DOM을 숨기기만 함 (제거하지 않음)
                const selectors = [
                    '[id*="videoChatPopup"]',
                    '[id*="mf_wfr_mainContent_videoChatPopup"]'
                ];

                let hiddenCount = 0;
                selectors.forEach(selector => {
                    const elements = document.querySelectorAll(selector);
                    elements.forEach(element => {
                        if (element && element.style) {
                            element.style.setProperty('display', 'none', 'important');
                            console.log("PIP - 모달 숨김:", element.id || element.className);
                            hiddenCount++;
                        }
                    });
                });
                console.log("PIP - 총", hiddenCount, "개 모달 요소 숨김 완료");

            } catch (e) {
                console.error("PIP 모달 숨기기 실패:", e);
            }
            return; // 화상통화 종료 없이 여기서 끝
        }

        console.log("일반 모드 - 화상통화 팝업 닫기 메시지 받음 - 강제 닫기 실행");

        // 간단하고 안전한 모달 닫기
        try {
            console.log("화상통화 모달 닫기 시작");

            // 1단계: WebSquare API로 정식 팝업 닫기
            if (typeof $p !== 'undefined' && $p.closePopup) {
                console.log("WebSquare API로 videoChatPopup 닫기");
                $p.closePopup("videoChatPopup");
            }

            // 2단계: 화상통화 DOM 완전 정리 (ID 중복 오류 방지)
            console.log("화상통화 DOM 완전 정리 시작");

            // 1) videoChatPopup 관련 모든 요소 제거
            var videoSelectors = [
                '[id*="videoChatPopup"]',
                '[id*="mf_wfr_mainContent_videoChatPopup"]',
                '.videochat-popup',
                '.video-chat-container'
            ];

            var totalRemoved = 0;
            videoSelectors.forEach(function (selector) {
                var elements = document.querySelectorAll(selector);
                elements.forEach(function (element) {
                    console.log("화상통화 DOM 제거:", element.id);
                    element.remove();
                    totalRemoved++;
                });
            });

            // 2) WebSquare 내부 캐시도 정리
            try {
                if (typeof $p !== 'undefined' && $p.destroyPopup) {
                    $p.destroyPopup("videoChatPopup");
                    console.log("WebSquare 팝업 캐시 정리 완료");
                } else if (typeof $p !== 'undefined' && $p.removePopup) {
                    $p.removePopup("videoChatPopup");
                    console.log("WebSquare 팝업 제거 완료");
                }
            } catch (e) {
                console.log("WebSquare 캐시 정리:", e.message);
            }

            console.log("총 " + totalRemoved + "개 DOM 요소 제거됨");

            // 3단계: 강제 페이지 활성화 (백드롭 대신)
            document.body.style.pointerEvents = 'auto !important';
            document.body.style.filter = 'none !important';
            document.body.style.opacity = '1 !important';
            document.documentElement.style.pointerEvents = 'auto !important';
            console.log("페이지 강제 활성화 완료");


            // 4단계: 기본 스타일 초기화
            document.body.style.pointerEvents = 'auto';
            document.body.style.overflow = 'auto';

            console.log("화상통화 모달 닫기 완료");

        } catch (e) {
            console.error("PostMessage 처리 중 DOM 제거 실패:", e);
        }
    }
});

// 비디오 연결 상태 저장용 전역 변수
scwin.videoConnectionState = null;

