// 소형 컨테이너 드래그 기능
scwin.makeMiniContainerDraggable = function (container) {
    const header = container.querySelector('.mini-video-header');
    let isDragging = false;
    let dragOffset = { x: 0, y: 0 };

    header.addEventListener('mousedown', function (e) {
        if (e.target.closest('button')) return; // 버튼 클릭은 무시

        isDragging = true;
        const rect = container.getBoundingClientRect();
        dragOffset.x = e.clientX - rect.left;
        dragOffset.y = e.clientY - rect.top;

        function handleMouseMove(e) {
            if (!isDragging) return;

            const x = Math.max(0, Math.min(e.clientX - dragOffset.x, window.innerWidth - container.offsetWidth));
            const y = Math.max(0, Math.min(e.clientY - dragOffset.y, window.innerHeight - container.offsetHeight));

            container.style.left = x + 'px';
            container.style.top = y + 'px';
            container.style.right = 'auto';
            container.style.bottom = 'auto';
        }

        function handleMouseUp() {
            isDragging = false;
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        }

        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);
        e.preventDefault();
    });

    // 드래그 중 커서 변경
    header.style.cursor = 'move';
};

// 비디오 상태 복원
scwin.restoreVideoState = function () {
    try {
        console.log("비디오 상태 복원 시작");

        const videoState = scwin.videoConnectionState;
        if (!videoState) {
            console.warn("복원할 비디오 상태가 없습니다");
            return;
        }

        const miniGrid = document.getElementById('miniVideoGrid');
        if (!miniGrid) {
            console.error("미니 비디오 그리드를 찾을 수 없습니다");
            return;
        }

        // 로컬 비디오 추가
        if (videoState.localStream) {
            scwin.addMiniVideo('local', videoState.localStream, videoState.currentUser.userName);
        }

        // 원격 비디오들 추가 (연결 상태 유지)
        if (videoState.remoteStreams) {
            videoState.remoteStreams.forEach((stream, userId) => {
                const userInfo = videoState.remoteUserInfo.get(userId);
                const userName = userInfo ? userInfo.userName : `사용자 ${userId}`;
                scwin.addMiniVideo(userId, stream, userName);
            });
        }

        console.log("✅ 비디오 상태 복원 완료");

    } catch (error) {
        console.error("비디오 상태 복원 실패:", error);
    }
};

// 미니 비디오 추가
scwin.addMiniVideo = function (videoId, stream, userName) {
    try {
        const miniGrid = document.getElementById('miniVideoGrid');
        if (!miniGrid) return;

        const videoItem = document.createElement('div');
        videoItem.className = 'mini-video-item';
        videoItem.id = 'miniVideo_' + videoId;

        const video = document.createElement('video');
        video.srcObject = stream;
        video.autoplay = true;
        video.muted = videoId === 'local'; // 로컬 비디오는 음소거
        video.playsInline = true;
        video.className = 'mini-video';

        const nameDiv = document.createElement('div');
        nameDiv.className = 'mini-video-name';
        nameDiv.textContent = userName;

        videoItem.appendChild(video);
        videoItem.appendChild(nameDiv);
        miniGrid.appendChild(videoItem);

        console.log("미니 비디오 추가됨:", videoId, userName);

    } catch (error) {
        console.error("미니 비디오 추가 실패:", error);
    }
};

// 소형 비디오 채팅 닫기
scwin.closeMiniVideoChat = function () {
    console.log("소형 비디오 채팅 닫기");

    try {
        const container = document.getElementById('miniVideoChatContainer');
        if (container) {
            // 비디오 스트림 정리
            const videos = container.querySelectorAll('video');
            videos.forEach(video => {
                if (video.srcObject) {
                    video.srcObject.getTracks().forEach(track => track.stop());
                    video.srcObject = null;
                }
            });

            container.remove();
            console.log("✅ 소형 비디오 컨테이너 제거됨");
        }

        // 비디오 상태 정리
        scwin.videoConnectionState = null;

        // 로컬 스토리지 정리
        localStorage.removeItem('tempVideoChatState');

    } catch (error) {
        console.error("소형 비디오 채팅 닫기 실패:", error);
    }
};

// 비디오 채팅 확대 (다시 모달로)
