/**
 * 보드명 입력 input의 키보드 이벤트 처리
 */
scwin.boardInput_onkeydown = function (e) {
    var inputComponent = this;
    var keyCode = e.keyCode;

    if (keyCode === 13) { // Enter 키 - 보드 생성
        var boardTitle = inputComponent.getValue();

        if (boardTitle && boardTitle.trim() !== "") {
            var projectId = inputComponent.getAttribute("data-project-id");
            var tempBoardId = inputComponent.getAttribute("data-temp-board-id");

            console.log("보드 생성 요청:", {
                boardTitle: boardTitle.trim(),
                projectId: projectId,
                tempBoardId: tempBoardId
            });

            // 임시 보드 ID 저장 (생성 성공 시 교체용)
            scwin.currentTempBoardId = tempBoardId;

            // 데이터 설정
            dm_boardVo_add.set("boardTitle", boardTitle.trim());
            dm_boardVo_add.set("projectId", projectId);

            // 서버에 보드 생성 요청
            $p.executeSubmission("add_board");

        } else {
            $c.win.alert("보드 이름을 입력해주세요.");
            inputComponent.focus();
        }

    } else if (keyCode === 27) { // ESC 키 - 취소
        console.log("보드 생성 취소");

        // 임시 보드 컬럼 제거
        var tempBoardId = inputComponent.getAttribute("data-temp-board-id");
        var columnId = "grp_dynamic_" + tempBoardId;

        try {
            var columnComponent = eval(columnId);
            if (columnComponent) {
                columnComponent.remove();
                console.log("임시 보드 컬럼 제거:", columnId);
            }
        } catch (error) {
            console.log("임시 보드 컬럼 제거 중 오류:", error);
        }
    }
};

/**
 * 임시 보드 제거
 */
scwin.removeTempBoard = function (tempBoardId) {
    console.log("임시 보드 제거:", tempBoardId);

    try {
        var tempColumnId = "grp_dynamic_" + tempBoardId;
        var tempColumn = eval(tempColumnId);

        if (tempColumn) {
            tempColumn.remove();
            console.log("임시 보드 컬럼 제거 완료:", tempColumnId);
        } else {
            console.log("제거할 임시 보드 컬럼을 찾을 수 없습니다:", tempColumnId);
        }

    } catch (error) {
        console.error("임시 보드 제거 중 오류:", error);
    }
};

/**
 * 사용자 이름을 포함한 태스크 목록 로드 성공 콜백
 */
scwin.load_Tasks_With_UserName_submitdone = function (e) {
    console.log("태스크 로드 완료 (프론트엔드 필터링 지원):", e);

    // 1. 응답에서 직접 태스크 목록 추출
    var responseData = e.responseJSON;

    // 새로운 태스크만 처리 (누적하지 않음)
    var newTasks = responseData.elData.taskVoList || [];
    console.log("서버로부터 받은 새 태스크 목록:", newTasks);

    // 칸반 보드용 태스크 처리 (보드별로 분리 저장)
    if (newTasks && newTasks.length > 0) {
        // 보드별로 태스크 데이터 분리
        var tasksByBoard = {};
        for (var i = 0; i < newTasks.length; i++) {
            var task = newTasks[i];
            if (!tasksByBoard[task.boardId]) {
                tasksByBoard[task.boardId] = [];
            }
            tasksByBoard[task.boardId].push(task);
        }

        // 각 보드별로 데이터 저장 및 표시
        for (var boardId in tasksByBoard) {
            var boardTasks = tasksByBoard[boardId];
            console.log(`보드 [${boardId}]에 태스크 ${boardTasks.length}개 저장`);

            // 전체 태스크 데이터를 로컬에 저장 (필터링용)
            scwin.storeAllTasksData(boardId, boardTasks);

            // 필터링과 정렬을 모두 적용하여 태스크 표시
            scwin.sortAndFilterBoardTasks(boardId);
        }

        console.log(`전체 태스크 로드 및 처리 완료: ${newTasks.length}개 (보드 수: ${Object.keys(tasksByBoard).length})`);
    } else {
        console.log("해당 보드에 대한 태스크가 없습니다.");

        // boardId 추출 (검색 조건에서)
        var searchCondition = $p.getComponentById("dm_search_task");
        if (searchCondition) {
            var boardId = searchCondition.get("boardId");
            if (boardId) {
                // 빈 데이터 저장 및 정렬/필터링 적용
                scwin.storeAllTasksData(boardId, []);
                scwin.sortAndFilterBoardTasks(boardId);
                console.log(`빈 보드 [${boardId}] 처리 완료`);
            }
        }
    }

    // 칸반 데이터 업데이트 후 간트차트 동기화
    scwin.syncGanttWithKanban();
};

/**
 * 사용자 이름 포함 태스크 로드 테스트 함수
 */
scwin.loadTasksWithUserName = function () {
    console.log("사용자 이름 포함 태스크 로드 시작");
    try {
        $p.executeSubmission("load_Tasks_With_UserName");
    } catch (error) {
        console.error("태스크 로드 실행 중 오류:", error);
    }
};

/**
 * 사용자 이름 포함 태스크 로드 비동기 함수 (Promise 반환)
 */
scwin.loadTasksWithUserNameAsync = function () {
    return new Promise((resolve, reject) => {
        console.log("사용자 이름 포함 태스크 로드 시작 (비동기)");
        try {
            // 기존 콜백 저장
            const originalCallback = scwin.load_Tasks_With_UserName_success;
            const originalErrorCallback = scwin.load_Tasks_With_UserName_error;

            // 임시 콜백 설정
            scwin.load_Tasks_With_UserName_success = function (res) {
                // 원래 콜백 실행
                if (originalCallback && typeof originalCallback === 'function') {
                    originalCallback.call(this, res);
                }
                // 콜백 복원
                scwin.load_Tasks_With_UserName_success = originalCallback;
                scwin.load_Tasks_With_UserName_error = originalErrorCallback;
                // Promise 해결
                resolve(res);
            };

            scwin.load_Tasks_With_UserName_error = function (error) {
                // 원래 에러 콜백 실행
                if (originalErrorCallback && typeof originalErrorCallback === 'function') {
                    originalErrorCallback.call(this, error);
                }
                // 콜백 복원
                scwin.load_Tasks_With_UserName_success = originalCallback;
                scwin.load_Tasks_With_UserName_error = originalErrorCallback;
                // Promise 거부
                reject(error);
            };

            $p.executeSubmission("load_Tasks_With_UserName");
        } catch (error) {
            console.error("태스크 로드 실행 중 오류:", error);
            reject(error);
        }
    });
};

/**
 * 특정 보드의 데이터를 새로고침 (taskModal 저장/삭제 후 호출)
 */
scwin.refreshBoardData = function (boardId) {
  console.log("������ 보드 데이터 새로고침 시작:", boardId);

  try {
    // 1. 해당 보드의 로컬 캐시 데이터 초기화
    if (scwin.allTasksData && scwin.allTasksData[boardId]) {
      delete scwin.allTasksData[boardId];
      console.log("로컬 캐시 데이터 삭제 완료:", boardId);
    }

    // 2. 서버에서 최신 데이터 다시 로드
    dm_search_task.set("boardId", boardId);
    dm_search_task.set("sortField", scwin.currentSortField);
    dm_search_task.set("sortOrder", scwin.currentSortOrder);

    // 3. 태스크 목록 다시 로드
    $p.executeSubmission("load_Tasks_With_UserName");

    console.log("✅ 보드 데이터 새로고침 요청 완료:", boardId);
  } catch (error) {
    console.error("❌ 보드 데이터 새로고침 실패:", boardId, error);
  }
};
